// Read only own completed textbook conversations, even after a downgrade/provider stop.
import {requestBody} from './openai-policy.mjs';
import {textbookChatRequest,textbookChatContent,textbookChatReply} from './textbook-ai-chat-content.mjs';
import {textbookOperationId,textbookRequestDigest,validateTextbookSnapshot} from './textbook-ai-chat-context.mjs';
const sha=async text=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text))),x=>x.toString(16).padStart(2,'0')).join('');
export async function completedTextbookChat(snapshot,operation){
 const context=snapshot?.context;
 const body=textbookChatRequest({id:snapshot?.id,text:snapshot?.text,book:context?.book,anchor:context?.anchor,annotationSignature:context?.annotationSignature,contextSha256:context?.contextSha256});
 validateTextbookSnapshot(snapshot,body,await textbookRequestDigest(body));
 const policy=requestBody(snapshot.plan,'chat',textbookChatContent(context,body.text,snapshot.history));
 if(operation?.state!=='done'||operation.digest!==await sha(JSON.stringify(policy.body))||operation.pricing?.model!==policy.body.model)throw Error('invalid_book_history');
 return {id:body.id,book:body.book,anchor:body.anchor,text:body.text,answer:textbookChatReply(JSON.stringify(operation.value)).answer,context,model:policy.body.model,real:true,mock:false,state:'done',at:snapshot.at};
}
export async function textbookChatHistory(db,uid,{book,anchor,id}){
 // Reuse the strict public identifiers without allowing caller-supplied text or source.
 textbookChatRequest({book,anchor,id:id||'history_query',text:'履歴',annotationSignature:'0'.repeat(64),contextSha256:'0'.repeat(64)});
 if(!/^(?:u[124]|p_(?:free|mini|standard|pro|unlimit))$/.test(uid))throw Error('invalid_book_history');
 const prefix='textbook-ai-context:'+uid+':',opPrefix='openai-operation:'+uid+':';
 if(id){
  const opId=await textbookOperationId({book,anchor,id,text:'履歴',annotationSignature:'0'.repeat(64),contextSha256:'0'.repeat(64)});
  const raw=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(prefix+opId).first('v');
  if(!raw)return {state:'not_found'};
  const snapshot=JSON.parse(raw);if(snapshot.context?.book!==book||snapshot.context?.anchor!==anchor||snapshot.id!==id)throw Error('invalid_book_history');
  const journal=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(opPrefix+opId).first('v');
  if(!journal)return {state:'not_started'};
  const operation=JSON.parse(journal);
  if(operation.state==='done')return {state:'done',item:await completedTextbookChat(snapshot,operation)};
  if(!['reserved','started','rejected'].includes(operation.state))throw Error('invalid_book_history');
  return {state:operation.state==='started'?'unknown':operation.state};
 }
 const rows=(await db.prepare("SELECT c.v AS snapshot,o.v AS operation FROM auth_kv c JOIN auth_kv o ON o.k=?||substr(c.k,?) WHERE c.k>=? AND c.k<? AND json_valid(c.v) AND json_valid(o.v) AND json_extract(c.v,'$.context.book')=? AND json_extract(c.v,'$.context.anchor')=? AND json_extract(o.v,'$.state')='done' ORDER BY CAST(json_extract(c.v,'$.at') AS INTEGER) DESC,c.k DESC LIMIT 30").bind(opPrefix,prefix.length+1,prefix,prefix+'\uffff',book,anchor).all()).results||[];
 const items=[];for(const row of rows)items.unshift(await completedTextbookChat(JSON.parse(row.snapshot),JSON.parse(row.operation)));
 return {items};
}
