// Own book/anchor history only; ordinary AI chat, grades and private notes are never read.
import {textbookChatRequest,textbookReference,textbookChatContent,textbookChatReply} from './textbook-ai-chat-content.mjs';
const UID=/^(?:u[124]|p_(?:free|mini|standard|pro|unlimit))$/;
const sha=async text=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text))),x=>x.toString(16).padStart(2,'0')).join('');
const fail=()=>{throw Error('textbook_context_unavailable');};
export async function textbookOperationId(body){const b=textbookChatRequest(body);return sha('textbook-chat:'+b.book+':'+b.anchor+':'+b.id);}
export const textbookRequestDigest=body=>sha(JSON.stringify(textbookChatRequest(body)));
export function textbookThreadPrefix(uid,body){if(!UID.test(uid))fail();return 'textbook-ai-chat:'+uid+':'+body.book+':'+body.anchor+':';}
export function validateTextbookSnapshot(row,body,digest){
 if(!row||Object.keys(row).sort().join(',')!=='at,context,history,id,plan,requestDigest,text,version'||row.version!==1||row.id!==body.id||row.requestDigest!==digest||row.text!==body.text||!['pro','unlimit'].includes(row.plan)||!Number.isSafeInteger(row.at)||row.at<0)throw Error('id_conflict');
 const context=textbookReference(row.context);
 if(context.book!==body.book||context.anchor!==body.anchor||context.annotationSignature!==body.annotationSignature||context.contextSha256!==body.contextSha256)throw Error('id_conflict');
 textbookChatContent(context,row.text,row.history);return row;
}
export async function capturedTextbookChat(db,uid,body,{plan,readContext,env,now,guard,operationExists=false}){
 if(!UID.test(uid)||!['pro','unlimit'].includes(plan)||!Number.isSafeInteger(now)||typeof guard!=='function')fail();
 const request=textbookChatRequest(body),id=await textbookOperationId(request),digest=await textbookRequestDigest(request),prefix='textbook-ai-context:'+uid+':',key=prefix+id;
 const prior=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(key).first('v');
 if(prior){if(prior.length>18000)fail();return validateTextbookSnapshot(JSON.parse(prior),request,digest);}
 if(operationExists)fail();
 const context=textbookReference(await readContext(env,{book:request.book,anchor:request.anchor,annotationSignature:request.annotationSignature,contextSha256:request.contextSha256}));
 if(context.book!==request.book||context.anchor!==request.anchor||context.annotationSignature!==request.annotationSignature||context.contextSha256!==request.contextSha256)throw Error('context_changed');
 const {textbookChatHistory}=await import('./textbook-ai-history.mjs');
 const rows=(await textbookChatHistory(db,uid,{book:request.book,anchor:request.anchor})).items;
 const history=[];
 for(const row of rows.slice(-6).reverse()){
  if(row.book!==request.book||row.anchor!==request.anchor||row.real!==true||row.mock!==false||!['gpt-6-luna','gpt-6.1-sol'].includes(row.model)||typeof row.text!=='string')fail();
  const pair={text:row.text.slice(0,1000),answer:textbookChatReply(JSON.stringify({answer:row.answer})).answer.slice(0,1000)};
  if(JSON.stringify([pair,...history]).length>6000)break;
  history.unshift(pair);
 }
 const snapshot={version:1,id:request.id,requestDigest:digest,plan,text:request.text,context,history,at:now};
 textbookChatContent(context,request.text,history);
 const serialized=JSON.stringify(snapshot);if(serialized.length>18000)fail();
 const writeGuard=guard();if(!writeGuard?.sql||!Array.isArray(writeGuard.values))fail();
 const saved=await db.prepare('INSERT INTO auth_kv(k,v,expires_at) SELECT ?,?,0 WHERE '+writeGuard.sql+' AND (SELECT COUNT(*) FROM auth_kv WHERE k>=? AND k<?)<1000 ON CONFLICT(k) DO NOTHING RETURNING v').bind(key,serialized,...writeGuard.values,prefix,prefix+'\uffff').first('v');
 const authoritative=saved||await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(key).first('v');
 if(!authoritative||authoritative.length>18000)fail();
 return validateTextbookSnapshot(JSON.parse(authoritative),request,digest);
}
