// Textbook-only release rights. Never upgrades a normal plan or changes learning records.
import {PLANS,PREVIEW_PROFILES,SUBSCRIPTION_TERMS,PLAN_CHANGE_REASONS,planStatus,planFeatures,readPlanContractSnapshot,subscriptionOn} from './plans.mjs';
import {CREDIT_LIMITS} from './subscription-credits.mjs';
const POLICY='textbook-release-policy',DAY=86400000,KEY=Symbol('server-textbook-access');
const sameKeys=(v,s)=>!!v&&typeof v==='object'&&!Array.isArray(v)&&Object.keys(v).sort().join(',')===s;
const integer=x=>Number.isSafeInteger(x)&&x>=0;
const error=code=>{throw Error(code);};
const member=(env,uid)=>typeof uid==='string'&&(/^(?:u1|u2|u4)$/.test(uid)||(env?.PREVIEW_PLAN_ACCOUNTS==='1'&&Object.hasOwn(PREVIEW_PROFILES,uid)));
const configured=env=>env?.TEXTBOOK_RELEASE_STAGE!==undefined||env?.TEXTBOOK_RELEASE_EPOCH!==undefined;
export const textbookAccessOn=env=>configured(env)||subscriptionOn(env);
function configuration(env,now){
 if(!configured(env))return null;
 const stage=env.TEXTBOOK_RELEASE_STAGE,raw=env.TEXTBOOK_RELEASE_EPOCH;
 if(!['early','v3'].includes(stage)||typeof raw!=='string'||!/^\d{13}$/.test(raw))error('book_access_unavailable');
 const epoch=Number(raw);if(!integer(epoch)||epoch<946684800000||epoch>now)error('book_access_unavailable');
 return {version:1,stage,epoch};
}
function parsePolicy(row){
 if(!row)return null;
 let v;try{v=JSON.parse(row.v);}catch(_){error('book_access_unavailable');}
 if(row.expires_at!==0||!sameKeys(v,'epoch,stage,version')||v.version!==1||!['early','v3'].includes(v.stage)||!integer(v.epoch)||v.epoch<946684800000)error('book_access_unavailable');
 return {...v,raw:row.v};
}
const policyRow=db=>db.prepare('SELECT v,expires_at FROM auth_kv WHERE k=?').bind(POLICY).first();
async function release(db,cfg){
 const previous=parsePolicy(await policyRow(db));
 if(!cfg){if(previous)error('release_changed');return null;}
 if(previous){
  if(previous.epoch>cfg.epoch||(previous.epoch===cfg.epoch&&previous.stage!==cfg.stage)||(previous.stage==='v3'&&cfg.stage==='early'))error('release_changed');
  if(previous.epoch===cfg.epoch)return previous;
 }
 const raw=JSON.stringify(cfg),write=previous
  ?db.prepare('UPDATE auth_kv SET v=? WHERE k=? AND v=? AND expires_at=0').bind(raw,POLICY,previous.raw)
  :db.prepare('INSERT INTO auth_kv(k,v,expires_at) VALUES(?,?,0) ON CONFLICT(k) DO NOTHING').bind(POLICY,raw);
 // Version change and its public audit record commit together. A stale Worker cannot roll back rights.
 await db.batch([write,db.prepare('INSERT INTO auth_kv(k,v,expires_at) SELECT ?,?,0 WHERE EXISTS(SELECT 1 FROM auth_kv WHERE k=? AND v=? AND expires_at=0) ON CONFLICT(k) DO NOTHING').bind('textbook-release-log:'+cfg.epoch,raw,POLICY,raw)]);
 const current=parsePolicy(await policyRow(db));
 if(!current||current.epoch!==cfg.epoch||current.stage!==cfg.stage)error('release_changed');
 return current;
}
function deadline(c){
 if(!c.row)return null;
 let until=null;
 if(c.row.end!==null){until=c.row.end+SUBSCRIPTION_TERMS.graceDays*DAY;if(!integer(until))error('book_access_unavailable');}
 if(c.row.next){
  const n=c.row.next;
  if(!Object.hasOwn(PLANS,n.plan)||!integer(n.from)||!integer(n.start)||!integer(n.end)||n.end<=n.start)error('book_access_unavailable');
  until=Math.min(until??Number.MAX_SAFE_INTEGER,n.from);
 }
 return until;
}
async function confirmation(db,uid,c,epoch,now){
 if(c.plan==='free'||!c.row||!['active','grace'].includes(c.state))return null;
 const lower='plan-log:'+String(epoch).padStart(15,'0')+':';
 const found=await db.prepare("SELECT k,v,expires_at FROM auth_kv WHERE k>=? AND k<? AND json_valid(v) AND json_extract(v,'$.uid')=? AND json_extract(v,'$.to')=? AND json_extract(v,'$.start')=? AND json_extract(v,'$.end') IS ? ORDER BY k DESC LIMIT 1").bind(lower,'plan-log:\uffff',uid,c.plan,c.row.start,c.row.end).first();
 if(!found)return null;
 let log;try{log=JSON.parse(found.v);}catch(_){error('book_access_unavailable');}
 if(found.expires_at!==0||!sameKeys(log,'applies,at,by,end,from,reason,start,to,uid')||log.by!=='admin（なお）'||log.uid!==uid||!Object.hasOwn(PLANS,log.from)||log.to!==c.plan||log.start!==c.row.start||log.end!==c.row.end||!PLAN_CHANGE_REASONS.includes(log.reason)||!integer(log.at)||log.at<epoch||log.at>now||!integer(log.applies)||log.applies<log.at||!new RegExp('^plan-log:'+String(log.at).padStart(15,'0')+':[a-f0-9]{12}$').test(found.k))error('book_access_unavailable');
 return log.applies<=now?found:null;
}
class AccessSnapshot {
 #guard;
 constructor(key,fields,guard){if(key!==KEY)error('invalid_entitlement');Object.assign(this,fields);this.#guard=guard;Object.freeze(this);}
 sql(key,{uid,owner,feature,now}){
  if(key!==KEY||uid!==this.#guard.uid||typeof owner!=='string'||!owner||!integer(now))error('invalid_entitlement');
  if(!['annotations','chat'].includes(feature)||!this.enabled||!this.features[feature])error('plan_required');
  if(this.#guard.deadline!==null&&now>=this.#guard.deadline)error('plan_changed');
  const parts=['EXISTS(SELECT 1 FROM auth_kv WHERE k=? AND v=? AND expires_at>?)'],values=['active-session:'+uid,owner,now];
  for(const [key,value] of this.#guard.required){parts.push('EXISTS(SELECT 1 FROM auth_kv WHERE k=? AND v=? AND expires_at=0)');values.push(key,value);}
  for(const key of this.#guard.absent){parts.push('NOT EXISTS(SELECT 1 FROM auth_kv WHERE k=?)');values.push(key);}
  if(this.#guard.deadline!==null){parts.push('?<?');values.push(now,this.#guard.deadline);}
  return Object.freeze({sql:parts.join(' AND '),values:Object.freeze(values)});
 }
}
async function snapshot(uid,{enabled,mode,epoch,plan,state,activation,dailyLimit},guard){
 const f=planFeatures(plan),features=Object.freeze({annotations:enabled&&f.annotations,chat:enabled&&f.chat});
 const material=JSON.stringify({uid,enabled,mode,epoch,plan,features,guard});
 const accessVersion=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(material))),v=>v.toString(16).padStart(2,'0')).join('');
 return new AccessSnapshot(KEY,{enabled,scope:'textbook',mode,epoch,plan,label:PLANS[plan].label,state,activation,features,dailyLimit,quotaMode:mode==='legacy'?'legacy':'textbook-daily-v1',accessVersion},{uid,...guard});
}
export async function textbookAccess(env,uid,now=Date.now()){
 if(!member(env,uid)||!integer(now))error('invalid_member');
 if(!textbookAccessOn(env))return snapshot(uid,{enabled:false,mode:'off',epoch:null,plan:'free',state:'off',activation:'off',dailyLimit:0},{required:[],absent:[],deadline:null});
 if(!env.AUTH_DB)error('book_access_unavailable');
 try{
  const cfg=configuration(env,now),db=env.AUTH_DB,policy=await release(db,cfg);
  if(!cfg){
   const s=await planStatus(env,uid,now),c=await readPlanContractSnapshot(db,uid,now);
   if(!s.provisional||s.plan!==c.plan||s.revision!==(c.row?.revision||0))error('plan_changed');
   const required=c.rawContract===null?[]:[['plan:'+uid,c.rawContract]],absent=[POLICY];if(c.rawContract===null)absent.push('plan:'+uid);
   return snapshot(uid,{enabled:true,mode:'legacy',epoch:null,plan:s.plan,state:s.state,activation:'contract',dailyLimit:s.dailyLimit},{required,absent,deadline:deadline(c)});
  }
  const required=[[POLICY,policy.raw]],profile=Object.hasOwn(PREVIEW_PROFILES,uid);let plan='free',state='none',activation='initial-free',until=null;
  if(profile){plan=PREVIEW_PROFILES[uid];state='preview';activation='profile';}
  else if(cfg.stage==='early'){plan='unlimit';state='early';activation='early-access';}
  else{
   const c=await readPlanContractSnapshot(db,uid,now);
   if(c.rawContract!==null&&!c.row)error('book_access_unavailable');
   const log=await confirmation(db,uid,c,cfg.epoch,now);
   if(log){plan=c.plan;state=c.state;activation='operator-confirmed';required.push(['plan:'+uid,c.rawContract],[log.k,log.v]);until=deadline(c);}
   else if(c.plan!=='free')state='confirmation-needed';
  }
  return snapshot(uid,{enabled:true,mode:cfg.stage,epoch:cfg.epoch,plan,state,activation,dailyLimit:CREDIT_LIMITS[plan]},{required,absent:[],deadline:until});
 }catch(e){if(['release_changed','plan_changed','book_access_unavailable'].includes(e?.message))throw e;error('book_access_unavailable');}
}
export function textbookWriteGuard(access,options){if(!(access instanceof AccessSnapshot))error('invalid_entitlement');return access.sql(KEY,options);}
