import engine from './material-engine.cjs';
import bank from './material-bank.mjs';
import {planStatus,historyWindow} from './plans.mjs';
const units=bank.units.filter(u=>u.status==='ready'&&u.subject!=='保健体育'&&engine.validateUnit(u,{sources:bank.sources}).length===0);
const uuid=/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/;
const cursorPattern=/^\d{13}:[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/;
const active='EXISTS (SELECT 1 FROM auth_kv WHERE k=? AND v=? AND expires_at>?)';
function sameAttempt(record,body){return ['id','unitId','questionId','mode','answer','elapsedMs'].every(k=>record[k]===body[k]);}
function validDiaryDay(day){return typeof day==='string'&&/^20\d{2}-\d{2}-\d{2}$/.test(day)&&Number.isFinite(Date.parse(day+'T00:00:00Z'))&&new Date(day+'T00:00:00Z').toISOString().slice(0,10)===day;}
export async function materialRecordsRoute(request,env,session,helpers){
 const {json,requestJson,invalidBody,owner}=helpers;
 if(!env.AUTH_DB)return json({error:'learning_store_unavailable'},503);
 const url=new URL(request.url),prefix='material-attempt:'+session.uid+':',history='material-history:'+session.uid+':';
 const guard=()=>['active-session:'+session.uid,owner,Date.now()];
 try{
  if(url.pathname.replace(/\/+$/,'')==='/material-speed'){
   if(request.method!=='GET')return json({error:'method not allowed'},405);
   const fields=['unitId','questionId','mode','cursor'];
   if([...url.searchParams.keys()].some(key=>!fields.includes(key))||fields.some(key=>url.searchParams.getAll(key).length>1))return json({error:'bad speed query'},400);
   const unitId=url.searchParams.get('unitId'),questionId=url.searchParams.get('questionId'),mode=url.searchParams.get('mode'),cursor=url.searchParams.get('cursor')||'';
   if(!unitId||!questionId||!['study','test'].includes(mode)||(cursor&&!cursorPattern.test(cursor)))return json({error:'bad speed query'},400);
   const unit=units.find(u=>u.id===unitId),question=unit&&(mode==='test'?unit.tests:unit.questions).find(q=>q.id===questionId);
   if(!question||question.type==='reading')return json({error:'unknown question'},404);
   if(!await env.AUTH_DB.prepare('SELECT v FROM auth_kv WHERE k=? AND v=? AND expires_at>?').bind(...guard()).first('v'))return json({error:'active_session'},409);
   // Only the authenticated owner's immutable, server-graded answers qualify.
   // A zero duration can be kept in history but cannot become a speed target.
   const where=" FROM auth_kv WHERE k>=? AND k<? AND json_extract(v,'$.unitId')=? AND json_extract(v,'$.questionId')=? AND json_extract(v,'$.mode')=? AND "+active;
   const values=[prefix,prefix+'\uffff',unitId,questionId,mode,...guard()];
   const summary=await env.AUTH_DB.prepare("SELECT COUNT(*) attempts,SUM(CASE WHEN json_extract(v,'$.result.correct')=1 THEN 1 ELSE 0 END) correct,MIN(CASE WHEN json_extract(v,'$.result.correct')=1 AND CAST(json_extract(v,'$.elapsedMs') AS INTEGER)>0 THEN CAST(json_extract(v,'$.elapsedMs') AS INTEGER) END) bestMs"+where).bind(...values).first();
   const projection="SELECT json_extract(v,'$.id') id,CAST(json_extract(v,'$.at') AS INTEGER) at,CAST(json_extract(v,'$.elapsedMs') AS INTEGER) elapsedMs,json_extract(v,'$.result.correct') correct";
   const rows=(await env.AUTH_DB.prepare(projection+where+(cursor?" AND (printf('%013d',CAST(json_extract(v,'$.at') AS INTEGER))||':'||json_extract(v,'$.id'))<?":"")+" ORDER BY at DESC,id DESC LIMIT 51").bind(...values,...(cursor?[cursor]:[])).all()).results||[];
   if(!await env.AUTH_DB.prepare('SELECT v FROM auth_kv WHERE k=? AND v=? AND expires_at>?').bind(...guard()).first('v'))return json({error:'active_session'},409);
   const items=rows.slice(0,50).map(row=>({id:row.id,at:row.at,elapsedMs:row.elapsedMs,correct:row.correct===1}));
   if(!Number.isSafeInteger(summary.attempts)||summary.attempts<0||!Number.isSafeInteger(summary.correct??0)||(summary.correct??0)<0||(summary.correct??0)>summary.attempts||(summary.bestMs!==null&&(!Number.isSafeInteger(summary.bestMs)||summary.bestMs<1||summary.bestMs>86400000))||items.some(row=>!uuid.test(row.id||'')||!Number.isSafeInteger(row.at)||row.at<0||!Number.isSafeInteger(row.elapsedMs)||row.elapsedMs<0||row.elapsedMs>86400000))throw Error('invalid speed records');
   const last=items.at(-1);
   return json({unitId,questionId,mode,subject:unit.subject,title:unit.title,attempts:summary.attempts,correct:summary.correct??0,bestMs:summary.bestMs,items,next:rows.length>50?String(last.at).padStart(13,'0')+':'+last.id:null,serverTime:Date.now()});
  }
  if(url.pathname.replace(/\/+$/,'')==='/material-diary'){
   const now=Date.now(),today=new Date(now+32400000).toISOString().slice(0,10),diaryPrefix='material-diary:'+session.uid+':';
   if(!['GET','POST'].includes(request.method))return json({error:'method not allowed'},405);
   if(!await env.AUTH_DB.prepare('SELECT v FROM auth_kv WHERE k=? AND v=? AND expires_at>?').bind(...guard()).first('v'))return json({error:'active_session'},409);
   if(request.method==='GET'){
    const cursor=url.searchParams.get('cursor')||'';
    if([...url.searchParams.keys()].some(k=>k!=='cursor')||url.searchParams.getAll('cursor').length>1||(cursor&&!validDiaryDay(cursor)))return json({error:'bad diary query'},400);
    const rows=(await env.AUTH_DB.prepare('SELECT k,v FROM auth_kv WHERE k>=? AND k<? AND '+active+' ORDER BY k DESC LIMIT 51').bind(diaryPrefix,cursor?diaryPrefix+cursor:diaryPrefix+'\uffff',...guard()).all()).results||[];
    const visible=rows.slice(0,50);return json({today,serverTime:now,items:visible.map(row=>JSON.parse(row.v)),next:rows.length>50?visible.at(-1).k.slice(diaryPrefix.length):null});
   }
   if(url.search)return json({error:'bad diary query'},400);
   let body;try{body=await requestJson(request,4096);}catch(e){return invalidBody(e);}
   const fields=['day','stamp','note','unitId','revision'];
   if(!body||typeof body!=='object'||Array.isArray(body)||Object.keys(body).length!==fields.length||Object.keys(body).some(k=>!fields.includes(k))||!validDiaryDay(body.day)||!['great','steady','challenging'].includes(body.stamp)||typeof body.note!=='string'||body.note.length>200||/[\x00-\x1f\x7f]/.test(body.note)||typeof body.unitId!=='string'||!Number.isSafeInteger(body.revision)||body.revision<0||body.revision>=Number.MAX_SAFE_INTEGER)return json({error:'bad diary'},400);
   if(body.day!==today)return json({error:'diary_day_changed',today},409);
   const unit=body.unitId?units.find(u=>u.id===body.unitId):null;if(body.unitId&&!unit)return json({error:'unknown unit'},400);
   const key=diaryPrefix+today,previous=await env.AUTH_DB.prepare('SELECT v FROM auth_kv WHERE k=? AND '+active).bind(key,...guard()).first('v'),old=previous?JSON.parse(previous):null;
   const same=row=>row&&row.day===body.day&&row.stamp===body.stamp&&row.note===body.note.trim()&&row.unitId===body.unitId;
   if(old&&(!Number.isSafeInteger(old.revision)||old.revision<1||!Number.isSafeInteger(old.createdAt)))throw Error('invalid diary record');
   if((old?.revision||0)!==body.revision){
    if(old?.revision===body.revision+1&&same(old))return json({record:old,serverTime:now});
    return json({error:'diary_conflict'},409);
   }
   const record={day:today,stamp:body.stamp,note:body.note.trim(),unitId:body.unitId,unitTitle:unit?.title||'',subject:unit?.subject||'',createdAt:old?.createdAt??now,updatedAt:now,revision:body.revision+1};
   // Compare revisions in the write itself; a second device cannot silently
   // replace a diary changed since its form was opened.
   await env.AUTH_DB.prepare('INSERT INTO auth_kv(k,v,expires_at) SELECT ?,?,0 WHERE '+active+' ON CONFLICT(k) DO UPDATE SET v=excluded.v,expires_at=0 WHERE CAST(json_extract(auth_kv.v,\'$.revision\') AS INTEGER)=?').bind(key,JSON.stringify(record),...guard(),body.revision).run();
   const stored=await env.AUTH_DB.prepare('SELECT v FROM auth_kv WHERE k=? AND '+active).bind(key,...guard()).first('v');
   if(!stored)return json({error:'active_session'},409);
   const saved=JSON.parse(stored);if(saved.revision!==body.revision+1||!same(saved))return json({error:'diary_conflict'},409);
   return json({record:saved,serverTime:now});
  }
  if(url.pathname.replace(/\/+$/,'')==='/material-rewards'){
   if(request.method!=='GET')return json({error:'method not allowed'},405);
   if(url.search)return json({error:'bad rewards query'},400);
   // The immutable attempt namespace is written only after server grading. Keep
   // earned credit even if a previously valid unit is later retired from the bank.
   const rows=(await env.AUTH_DB.prepare("SELECT json_extract(v,'$.unitId') unitId,json_extract(v,'$.mode') mode,json_extract(v,'$.questionId') questionId,MIN(json_extract(v,'$.subject')) subject,MIN(json_extract(v,'$.unitTitle')) title,MIN(CAST(json_extract(v,'$.at') AS INTEGER)) firstAt FROM auth_kv WHERE k>=? AND k<? AND json_extract(v,'$.result.correct')=1 AND json_extract(v,'$.mode') IN ('study','test') AND json_extract(v,'$.questionId') NOT LIKE 'gen-%' AND "+active+" GROUP BY unitId,mode,questionId ORDER BY unitId,mode,questionId").bind(prefix,prefix+'\uffff',...guard()).all()).results||[];
   const groups=new Map();
   for(const row of rows){
    if(typeof row.unitId!=='string'||!row.unitId||typeof row.questionId!=='string'||!row.questionId||typeof row.subject!=='string'||typeof row.title!=='string'||!Number.isSafeInteger(row.firstAt)||row.firstAt<0)throw Error('invalid reward record');
    const key=JSON.stringify([row.unitId,row.mode]),group=groups.get(key);
    if(group){group.correctQuestions++;group.firstAt=Math.min(group.firstAt,row.firstAt);group.lastFirstAt=Math.max(group.lastFirstAt,row.firstAt);}
    else groups.set(key,{unitId:row.unitId,mode:row.mode,subject:row.subject,title:row.title,correctQuestions:1,firstAt:row.firstAt,lastFirstAt:row.firstAt});
   }
   return json({earned:rows.length,byUnit:[...groups.values()],pointsPerQuestion:1,serverTime:Date.now()});
  }
  if(url.pathname.replace(/\/+$/,'')==='/material-daily'){
   if(request.method!=='GET')return json({error:'method not allowed'},405);
   if(url.search)return json({error:'bad daily query'},400);
   const now=Date.now(),day=new Date(now+32400000).toISOString().slice(0,10),start=Date.parse(day+'T00:00:00+09:00');
   const rows=(await env.AUTH_DB.prepare("SELECT DISTINCT json_extract(v,'$.unitId') unitId,json_extract(v,'$.mode') mode,json_extract(v,'$.questionId') questionId FROM auth_kv WHERE k>=? AND k<? AND json_extract(v,'$.result.correct')=1 AND CAST(json_extract(v,'$.at') AS INTEGER)>=? AND CAST(json_extract(v,'$.at') AS INTEGER)<? AND "+active).bind(prefix,prefix+'\uffff',start,start+86400000,...guard()).all()).results||[];
   const correctQuestions=rows.filter(row=>{const unit=units.find(u=>u.id===row.unitId);return unit&&['study','test'].includes(row.mode)&&(row.mode==='test'?unit.tests:unit.questions).some(q=>q.id===row.questionId);}).length;
   return json({day,correctQuestions,serverTime:now});
  }
  if(url.pathname.replace(/\/+$/,'')==='/material-review'){
   if(request.method!=='GET')return json({error:'method not allowed'},405);
   const cursor=url.searchParams.get('cursor')||'',view=url.searchParams.get('view')||'due';
   if(!['due','all'].includes(view)||(cursor&&!/^[a-z0-9][a-z0-9:_-]{0,250}$/.test(cursor)))return json({error:'bad review query'},400);
   const now=Date.now(),day=86400000;
   const sql="WITH events AS (SELECT k,v,json_extract(v,'$.unitId') unitId,json_extract(v,'$.mode') mode,json_extract(v,'$.questionId') questionId,CAST(json_extract(v,'$.at') AS INTEGER) at,json_extract(v,'$.result.correct') correct FROM auth_kv WHERE k>=? AND k<? AND "+active+"), ranked AS (SELECT *,ROW_NUMBER() OVER (PARTITION BY unitId,mode,questionId,correct ORDER BY at DESC,k DESC) rank,ROW_NUMBER() OVER (PARTITION BY unitId,mode,questionId,correct ORDER BY at ASC,k ASC) firstRank FROM events), paired AS (SELECT unitId,mode,questionId,unitId||':'||mode||':'||questionId reviewKey,MAX(CASE WHEN correct=0 AND rank=1 THEN v END) beforeRecord,MAX(CASE WHEN correct=0 AND firstRank=1 THEN v END) firstRecord,MAX(CASE WHEN correct=1 AND rank=1 THEN v END) afterRecord,MAX(CASE WHEN correct=0 THEN at END) wrongAt,MAX(CASE WHEN correct=1 THEN at END) correctAt FROM ranked GROUP BY unitId,mode,questionId HAVING wrongAt IS NOT NULL), scheduled AS (SELECT *,CASE WHEN correctAt>=wrongAt+? THEN 0 WHEN correctAt>=wrongAt+? THEN 7 ELSE 3 END reviewDay FROM paired) SELECT * FROM scheduled WHERE reviewKey>?"+(view==='due'?' AND reviewDay>0 AND wrongAt+reviewDay*?<=?':'')+' ORDER BY reviewKey LIMIT 51';
   const values=[prefix,prefix+'\uffff',...guard(),7*day,3*day,cursor,...(view==='due'?[day,now]:[])];
   const rows=(await env.AUTH_DB.prepare(sql).bind(...values).all()).results||[],visible=rows.slice(0,50);
   const items=[];
   for(const row of visible){
    const u=units.find(u=>u.id===row.unitId);let q=u&&(row.mode==='test'?u.tests:u.questions).find(q=>q.id===row.questionId);
    if(!q&&u&&/^gen-[a-f0-9]{12}$/.test(row.questionId||'')){const g=await env.AUTH_DB.prepare('SELECT v FROM auth_kv WHERE k=?').bind('gemini-gen:'+u.id+':'+row.questionId).first('v');if(g)q=JSON.parse(g);}
    if(!q)continue;
    const before=JSON.parse(row.beforeRecord),first=JSON.parse(row.firstRecord),after=row.afterRecord?JSON.parse(row.afterRecord):null;
    const dueAt=row.reviewDay?row.wrongAt+row.reviewDay*day:null;
    const dontKnow=before.answer==='わからない';
    // 苦手ノートの自動記録：保存済みの誤答記録から作るので、ノート用の書き込みは増やさない。
    items.push({unitId:u.id,subject:u.subject,grade:u.grade,unitMode:u.mode,unitTitle:u.title,questionId:q.id,mode:row.mode,question:q,mistake:{attemptId:typeof before.id==='string'?before.id:null,answer:before.answer,dontKnow,reason:dontKnow?'「わからない」を選びました。':String(before.result?.reason||'')},firstBefore:{answer:first.answer,at:first.at},latestImprovement:after&&after.at>=first.at?{answer:after.answer,at:after.at}:null,before:{answer:before.answer,at:before.at},after:after&&after.at>=before.at?{answer:after.answer,at:after.at}:null,reviewDay:row.reviewDay,dueAt,due:dueAt!==null&&dueAt<=now,complete:row.reviewDay===0});
   }
   return json({items,next:rows.length>50?visible.at(-1).reviewKey:null,serverTime:now});
  }
  if(url.pathname.replace(/\/+$/,'')==='/material-stats'){
   if(request.method!=='GET')return json({error:'method not allowed'},405);
   const month=url.searchParams.get('month')||new Date(Date.now()+32400000).toISOString().slice(0,7);
   if(!/^\d{4}-(?:0[1-9]|1[0-2])$/.test(month))return json({error:'bad month'},400);
   const [year,m]=month.split('-').map(Number);
   if(year<2020||year>2100)return json({error:'bad month'},400);
   const select="json_extract(v,'$.unitId') unitId, json_extract(v,'$.mode') mode, COUNT(*) attempts, SUM(CASE WHEN json_extract(v,'$.result.correct')=1 THEN 1 ELSE 0 END) correct, SUM(CAST(json_extract(v,'$.elapsedMs') AS INTEGER)) elapsedMs";
   const where=' FROM auth_kv WHERE k>=? AND k<? AND '+active;
   const totals=(await env.AUTH_DB.prepare('SELECT '+select+where+' GROUP BY unitId, mode ORDER BY unitId, mode').bind(prefix,prefix+'\uffff',...guard()).all()).results||[];
   const days=(await env.AUTH_DB.prepare("SELECT strftime('%Y-%m-%d', CAST(json_extract(v,'$.at') AS INTEGER)/1000.0, 'unixepoch', '+9 hours') day, "+select+where+" GROUP BY day, unitId, mode ORDER BY day, unitId, mode").bind(prefix,prefix+'\uffff',...guard()).all()).results||[];
   const describe=row=>{const u=units.find(u=>u.id===row.unitId);return u?{...row,subject:u.subject,title:u.title}:null;};
   const activity=days.map(describe).filter(Boolean),serverTime=Date.now();
   return json({month,totals:totals.map(describe).filter(Boolean),days:activity.filter(row=>row.day?.startsWith(month+'-')),activity,serverTime});
  }
  if(url.pathname.replace(/\/+$/,'')==='/material-marks'){
   // 小単元の一覧：問題ごとの ○（一度でも正解）・△（惜しい→1週間後）・×（次の日の最初）と、見た回数（回答した回数）
   if(request.method!=='GET')return json({error:'method not allowed'},405);
   if([...url.searchParams.keys()].some(k=>k!=='unitId')||url.searchParams.getAll('unitId').length!==1)return json({error:'bad marks query'},400);
   const unitId=url.searchParams.get('unitId'),unit=units.find(u=>u.id===unitId);
   if(!unit)return json({error:'unknown unit'},404);
   if(!await env.AUTH_DB.prepare('SELECT v FROM auth_kv WHERE k=? AND v=? AND expires_at>?').bind(...guard()).first('v'))return json({error:'active_session'},409);
   const rows=(await env.AUTH_DB.prepare("WITH e AS (SELECT k,json_extract(v,'$.questionId') questionId,CAST(json_extract(v,'$.at') AS INTEGER) at,json_extract(v,'$.result.correct') correct,json_extract(v,'$.result.near') near FROM auth_kv WHERE k>=? AND k<? AND json_extract(v,'$.unitId')=? AND json_extract(v,'$.mode')='study' AND "+active+"), r AS (SELECT *,ROW_NUMBER() OVER (PARTITION BY questionId ORDER BY at DESC,k DESC) rk,COUNT(*) OVER (PARTITION BY questionId) views,MAX(CASE WHEN correct=1 THEN 1 ELSE 0 END) OVER (PARTITION BY questionId) ever FROM e) SELECT questionId,at,correct,near,views,ever FROM r WHERE rk=1").bind(prefix,prefix+'￿',unitId,...guard()).all()).results||[];
   if(!await env.AUTH_DB.prepare('SELECT v FROM auth_kv WHERE k=? AND v=? AND expires_at>?').bind(...guard()).first('v'))return json({error:'active_session'},409);
   const day=86400000,ids=new Set(unit.questions.map(q=>q.id)),items=[];
   for(const row of rows){
    if(!ids.has(row.questionId))continue;
    if(!Number.isSafeInteger(row.at)||row.at<0||!Number.isSafeInteger(row.views)||row.views<1)throw Error('invalid marks');
    // 一度でも正解した問題は○（進み具合の数と同じ）。まだなら、いちばん新しい回答が惜しい→△、それ以外→×
    const mark=row.ever===1?'○':row.near===1?'△':'×';
    // ×は答えた日の次の日（日本時間0時）から、△は答えてから7日後から出す
    const dueAt=mark==='○'?null:mark==='△'?row.at+7*day:(Math.floor((row.at+9*3600000)/day)+1)*day-9*3600000;
    items.push({questionId:row.questionId,mark,views:row.views,lastAt:row.at,dueAt});
   }
   return json({unitId,items,serverTime:Date.now()});
  }
  if(url.pathname.replace(/\/+$/,'')==='/material-progress'){
   if(request.method!=='GET')return json({error:'method not allowed'},405);
   const rows=(await env.AUTH_DB.prepare("SELECT DISTINCT json_extract(v,'$.unitId') unitId, json_extract(v,'$.questionId') questionId, json_extract(v,'$.mode') mode FROM auth_kv WHERE k>=? AND k<? AND json_extract(v,'$.result.correct')=1 AND "+active).bind(prefix,prefix+'\uffff',...guard()).all()).results||[];
   const progress=Object.create(null);
   for(const row of rows){const u=units.find(u=>u.id===row.unitId),key=row.mode==='test'?'testDone':'done';if(!u||(row.mode!=='test'&&row.mode!=='study')||!(row.mode==='test'?u.tests:u.questions).some(q=>q.id===row.questionId))continue;(progress[row.unitId]||=( {done:[],testDone:[]} ))[key].push(row.questionId);}
   return json({progress});
  }
  if(request.method==='GET'){
   const cursor=url.searchParams.get('cursor')||'';if(cursor&&!cursorPattern.test(cursor))return json({error:'bad cursor'},400);
   const upper=cursor?history+cursor:history+'\uffff';
   // プランごとの表示期間（確認版の仮ルールだけ）。それより前の回答は消さず、ここで見せないだけ
   let win=null;try{const st=await planStatus(env,session.uid,Date.now());if(st.provisional)win=historyWindow(st.plan,Date.now());}catch(_){return json({error:'plan_unavailable'},503);}
   const lower=win?history+String(Math.max(0,win.from)).padStart(13,'0'):history;
   const rows=(await env.AUTH_DB.prepare('SELECT i.k, r.v FROM auth_kv i JOIN auth_kv r ON r.k=i.v WHERE i.k>=? AND i.k<? AND '+active+' ORDER BY i.k DESC LIMIT 51').bind(lower,upper,...guard()).all()).results||[];
   const visible=rows.slice(0,50);return json({items:visible.map(r=>JSON.parse(r.v)),next:rows.length>50?visible.at(-1).k.slice(history.length):null,...(win?{window:{from:win.from,label:win.label}}:{})});
  }
  if(request.method!=='POST')return json({error:'method not allowed'},405);
  let body;try{body=await requestJson(request,32768);}catch(e){return invalidBody(e);}
  const fields=['id','unitId','questionId','mode','answer','elapsedMs'];
  if(!body||typeof body!=='object'||Array.isArray(body)||Object.keys(body).length!==fields.length||Object.keys(body).some(k=>!fields.includes(k))||!uuid.test(body.id||'')||!['study','test'].includes(body.mode)||typeof body.answer!=='string'||!body.answer.trim()||body.answer.length>4000||!Number.isSafeInteger(body.elapsedMs)||body.elapsedMs<0||body.elapsedMs>86400000)return json({error:'bad attempt'},400);
  const unit=units.find(u=>u.id===body.unitId);let q=unit&&(body.mode==='test'?unit.tests:unit.questions).find(q=>q.id===body.questionId);
  // AIが作って検算できた問題（練習のみ）も記録できる。問題はサーバーに保存されたものを使う
  if(!q&&unit&&body.mode==='study'&&/^gen-[a-f0-9]{12}$/.test(body.questionId||'')){const g=await env.AUTH_DB.prepare('SELECT v FROM auth_kv WHERE k=?').bind('gemini-gen:'+unit.id+':'+body.questionId).first('v');if(g)q=JSON.parse(g);}
  if(!q)return json({error:'unknown question'},404);
  const at=Date.now(),key=prefix+body.id,index=history+String(at).padStart(13,'0')+':'+body.id;
  const record={...body,at,subject:unit.subject,unitTitle:unit.title,prompt:q.prompt,expected:q.answer,explanation:q.explanation,source:q.source,result:engine.grade(q,body.answer)};
  // Immutable event and its chronological index are committed together. Retries reuse
  // the first event's timestamp; they never create a second chronological entry.
  await env.AUTH_DB.batch([
   env.AUTH_DB.prepare('INSERT INTO auth_kv(k,v,expires_at) SELECT ?,?,0 WHERE '+active+' ON CONFLICT(k) DO NOTHING').bind(key,JSON.stringify(record),...guard()),
   env.AUTH_DB.prepare("INSERT INTO auth_kv(k,v,expires_at) SELECT ?,?,0 WHERE EXISTS (SELECT 1 FROM auth_kv WHERE k=? AND CAST(json_extract(v,'$.at') AS INTEGER)=?) AND "+active+' ON CONFLICT(k) DO NOTHING').bind(index,key,key,at,...guard())
  ]);
  const saved=await env.AUTH_DB.prepare('SELECT v FROM auth_kv WHERE k=? AND '+active).bind(key,...guard()).first('v');
  if(!saved)return json({error:'active_session'},409);
  const stored=JSON.parse(saved);if(!sameAttempt(stored,body))return json({error:'attempt_id_conflict'},409);
  return json({record:stored});
 }catch(_){return json({error:'learning_store_unavailable'},503);}
}
