// Internal receipt recovery. Only an authoritative uncharged rejection can refund.
import {refundTextbookChat} from './textbook-ai-quota.mjs';
import {refundCredits} from './subscription-credits.mjs';
const keyFor=(uid,id)=>{
 if(!/^(?:u[124]|p_(?:free|mini|standard|pro|unlimit))$/.test(uid)||!/^[a-f0-9]{64}$/.test(id))throw Error('invalid_book_refund');
 return 'openai-operation:'+uid+':'+id;
};
export async function pinTextbookReceipt(db,uid,id,token,receipt){
 const key=keyFor(uid,id);
 return !!await db.prepare("UPDATE auth_kv SET v=json_set(v,'$.textbookReceipt',json(?)) WHERE k=? AND json_extract(v,'$.token')=? AND json_extract(v,'$.state')='started' AND json_type(v,'$.textbookReceipt') IS NULL RETURNING v").bind(JSON.stringify(receipt),key,token).first('v');
}
export async function recoverTextbookRefund(db,uid,id){
 const key=keyFor(uid,id),raw=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(key).first('v');
 let row;try{row=JSON.parse(raw);}catch{return false;}
 if(row?.state!=='rejected')return false;
 if(row.textbookRefunded===true)return true;
 const receipt=row.textbookReceipt;
 // No receipt means charging never completed. Unknown charged outcomes stay started.
 if(!receipt)return true;
 if(receipt.receiptKey?.startsWith('textbook-ai-quota:'+uid+':')){
  await refundTextbookChat(db,uid,receipt);
  const saved=JSON.parse(await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(receipt.receiptKey).first('v'));
  if(saved?.token!==receipt.token||saved.state!=='refunded')return false;
 }else if(receipt.key?.startsWith('plan-credit-day:'+uid+':')){
  await refundCredits(db,uid,receipt);
  const saved=JSON.parse(await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(receipt.receiptKey).first('v'));
  if(saved?.uid!==uid||saved.key!==receipt.key||saved.units!==receipt.units||saved.refunded!==true)return false;
 }else{
  // Legacy monthly counters have no receipt. Refund and once-only marker must commit together.
  if(!new RegExp('^plan-quota:'+uid+':\\d+$').test(receipt.key)||!Number.isSafeInteger(receipt.day))throw Error('invalid_book_refund');
  const nonce=crypto.randomUUID();
  await db.batch([
   db.prepare("UPDATE auth_kv SET v=json_set(v,'$.n',json_extract(v,'$.n')-1,'$.daily',CASE WHEN json_extract(v,'$.day')=? THEN MAX(0,json_extract(v,'$.daily')-1) ELSE json_extract(v,'$.daily') END,'$.textbookRefund',?) WHERE k=? AND json_valid(v) AND json_type(v,'$.n')='integer' AND json_extract(v,'$.n')>0 AND EXISTS(SELECT 1 FROM auth_kv WHERE k=? AND v=?)").bind(receipt.day,nonce,receipt.key,key,raw),
   db.prepare("UPDATE auth_kv SET v=json_set(v,'$.textbookRefunded',json('true')) WHERE k=? AND v=? AND EXISTS(SELECT 1 FROM auth_kv WHERE k=? AND json_extract(v,'$.textbookRefund')=?)").bind(key,raw,receipt.key,nonce)
  ]);
  const final=JSON.parse(await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(key).first('v'));
  return final?.token===row.token&&final.state==='rejected'&&final.textbookRefunded===true;
 }
 if(await db.prepare("UPDATE auth_kv SET v=json_set(v,'$.textbookRefunded',json('true')) WHERE k=? AND v=? RETURNING v").bind(key,raw).first('v'))return true;
 const final=JSON.parse(await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(key).first('v'));
 return final?.token===row.token&&final.state==='rejected'&&final.textbookRefunded===true;
}
