// 🌳 管理画面 v1 のサーバー部分（Claude・2026-10-09）。管理者は u1（なお）だけ。サーバーで毎回確かめる。
// 返すのは集計と活動の記録の「種類・時刻・単元・問題のID」だけ。入力した答えの文章・パスコード・ヒントの本文は返さない。
// 読むだけ（GET）。記録を消したり書きかえたりはしない。
const reply=(body,status=200)=>Response.json(body,{status,headers:{'Cache-Control':'no-store'}});
const FAMILY=['u1','u2'],DAY=86400000,JST=9*3600000;
const TYPES=['open','hint','admin-flag','admin-document','newspaper-create','assignment-create','assignment-start','assignment-draft','assignment-submit','assignment-return'];
const SAFE=['type','at','unitId','questionId','level','mock','id','student','paused','revision','action'];
const dayStart=now=>Math.floor((now+JST)/DAY)*DAY-JST;
function clean(row){const out={};for(const k of SAFE)if(row&&row[k]!==undefined&&['string','number','boolean'].includes(typeof row[k]))out[k]=typeof row[k]==='string'?row[k].slice(0,120):row[k];return out;}
async function overview(db,uid,now){
 const p='material-attempt:'+uid+':',lo=p,hi=p+'￿',start=dayStart(now);
 const sel="COUNT(*) attempts, SUM(CASE WHEN json_extract(v,'$.result.correct') THEN 1 ELSE 0 END) correct, SUM(CAST(json_extract(v,'$.elapsedMs') AS INTEGER)) elapsedMs";
 const today=await db.prepare('SELECT '+sel+" FROM auth_kv WHERE k>=? AND k<? AND CAST(json_extract(v,'$.at') AS INTEGER)>=?").bind(lo,hi,start).first()||{};
 const days=(await db.prepare("SELECT CAST((CAST(json_extract(v,'$.at') AS INTEGER)+?)/? AS INTEGER) d, "+sel+" FROM auth_kv WHERE k>=? AND k<? AND CAST(json_extract(v,'$.at') AS INTEGER)>=? GROUP BY d ORDER BY d").bind(JST,DAY,lo,hi,start-6*DAY).all()).results||[];
 const units=(await db.prepare("SELECT json_extract(v,'$.subject') subject, json_extract(v,'$.unitTitle') unitTitle, json_extract(v,'$.unitId') unitId, "+sel+" FROM auth_kv WHERE k>=? AND k<? GROUP BY unitId ORDER BY subject, unitTitle LIMIT 400").bind(lo,hi).all()).results||[];
 const lastAttempt=await db.prepare("SELECT MAX(CAST(json_extract(v,'$.at') AS INTEGER)) at FROM auth_kv WHERE k>=? AND k<?").bind(lo,hi).first('at');
 const lastAct=await db.prepare('SELECT k FROM auth_kv WHERE k>=? AND k<? ORDER BY k DESC LIMIT 1').bind('activity:'+uid+':','activity:'+uid+':￿').first('k');
 const lastActAt=lastAct?Number(lastAct.split(':')[2]):null;
 const presenceRaw=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind('learning-presence:'+uid).first('v');let presence=null;try{const value=JSON.parse(presenceRaw);if(value?.uid===uid&&value.at>=now-120000)presence={mode:value.mode,startedAt:value.startedAt,at:value.at};}catch(_){}
 const n=x=>Number(x)||0;
 return {uid,presence,today:{attempts:n(today.attempts),correct:n(today.correct),elapsedMs:n(today.elapsedMs)},
  days:days.map(r=>({day:new Date(r.d*DAY).toISOString().slice(0,10),attempts:n(r.attempts),correct:n(r.correct)})),
  units:units.filter(r=>typeof r.unitId==='string').map(r=>({subject:String(r.subject||''),unitTitle:String(r.unitTitle||''),unitId:r.unitId,attempts:n(r.attempts),correct:n(r.correct)})),
  lastActiveAt:Math.max(n(lastAttempt),n(lastActAt))||null};
}
export async function adminRoute(request,env,session){
 if(!session||typeof session.uid!=='string'||!session.uid)return reply({error:'unauthorized'},401);
 if(session.uid!=='u1')return reply({error:'forbidden'},403);
 if(request.method!=='GET')return reply({error:'method not allowed'},405);
 if(!env.AUTH_DB)return reply({error:'unavailable'},503);
 const url=new URL(request.url),db=env.AUTH_DB,now=Date.now();
 if(url.pathname==='/admin/overview'){
  if(url.search)return reply({error:'invalid_query'},400);
  const {profilesFor}=await import('./admin-workspace.mjs');
  const profiles=profilesFor(env),people=[];for(const p of profiles)people.push({...await overview(db,p.uid,now),...p});
  return reply({now,people,environment:env.PREVIEW_PLAN_ACCOUNTS==='1'?'preview':'production'});
 }
 if(url.pathname==='/admin/activity'){
  const keys=[...url.searchParams.keys()];if(keys.some(k=>!['uid','type','cursor'].includes(k))||new Set(keys).size!==keys.length)return reply({error:'invalid_query'},400);
  const uid=url.searchParams.get('uid'),type=url.searchParams.get('type')||'',cursor=url.searchParams.get('cursor')||'';
  const {profilesFor}=await import('./admin-workspace.mjs');
  if(!profilesFor(env).some(p=>p.uid===uid)||(type&&!TYPES.includes(type))||(cursor&&!/^activity:(?:u[12]|p_free|p_mini|p_standard|p_pro|p_unlimit):\d{15}:[a-f0-9]{12}$/.test(cursor))||(cursor&&!cursor.startsWith('activity:'+uid+':')))return reply({error:'invalid_query'},400);
  const lo='activity:'+uid+':',hi=cursor||lo+'￿';
  const rows=(await db.prepare('SELECT k,v FROM auth_kv WHERE k>=? AND k<? '+(type?"AND json_extract(v,'$.type')=? ":'')+'ORDER BY k DESC LIMIT 51').bind(...(type?[lo,hi,type]:[lo,hi])).all()).results||[];
  const items=rows.slice(0,50).map(r=>{let v={};try{v=JSON.parse(r.v);}catch(_){}return {...clean(v),key:r.k,at:Number(r.k.split(':')[2])};});
  return reply({uid,items,next:rows.length>50?rows[49].k:null});
 }
 return reply({error:'not_found'},404);
}
// アプリを開いた記録（ログインの代わり）：30分に1回まで。入力・パスコードは入れない。
export async function recordOpen(env,uid){
 if(!env.AUTH_DB||!FAMILY.includes(uid))return;
 const now=Date.now(),db=env.AUTH_DB,lo='activity:'+uid+':';
 const last=await db.prepare("SELECT k FROM auth_kv WHERE k>=? AND k<? AND json_extract(v,'$.type')='open' ORDER BY k DESC LIMIT 1").bind(String(lo+String(now-30*60000).padStart(15,'0')),lo+'￿').first('k');
 if(last)return;
 const rand=[...crypto.getRandomValues(new Uint8Array(6))].map(b=>b.toString(16).padStart(2,'0')).join('');
 await db.prepare('INSERT INTO auth_kv(k,v,expires_at) VALUES(?,?,?)').bind(lo+String(now).padStart(15,'0')+':'+rand,JSON.stringify({type:'open',at:now}),now+3650*DAY).run();
}
// 🚫 問題の一時停止（台帳28・2026-10-09）：問題そのものは消さず、なおが「出さない」印をつける／外す。
// 家族はだれでも「出さない問題の一覧」を読める（出題から外すため）。印をつけ外しできるのは u1 だけ。
const ID=/^[a-z0-9][a-z0-9_-]{0,120}$/;
export async function flagsRoute(request,env,session,{units}={}){
 if(!session||typeof session.uid!=='string'||!session.uid)return reply({error:'unauthorized'},401);
 const uid=session.uid,url=new URL(request.url);
 if(!env.AUTH_DB)return reply({error:'unavailable'},503);
 const db=env.AUTH_DB;
 if(request.method==='GET'){
  if(url.search)return reply({error:'invalid_query'},400);
  if(!(await import('./admin-workspace.mjs')).profilesFor(env).some(p=>p.uid===uid))return reply({items:[]});
  const rows=(await db.prepare("SELECT k,v FROM auth_kv WHERE k>=? AND k<? LIMIT 3000").bind('qflag:','qflag:￿').all()).results||[];
  const items=rows.map(r=>{try{return JSON.parse(r.v);}catch(_){return null;}}).filter(v=>v&&v.paused===true&&ID.test(v.unitId||'')&&ID.test(v.questionId||''));
  return reply({items:uid==='u1'?items.map(v=>({unitId:v.unitId,questionId:v.questionId,note:v.note||'',at:v.at})):items.map(v=>({unitId:v.unitId,questionId:v.questionId}))});
 }
 if(request.method!=='POST')return reply({error:'method not allowed'},405);
 if(uid!=='u1')return reply({error:'forbidden'},403);
 const origin=request.headers.get('Origin');if(env.APP_ORIGIN&&origin!==env.APP_ORIGIN)return reply({error:'origin'},403);
 if(!/^application\/json\b/.test(request.headers.get('Content-Type')||''))return reply({error:'content_type'},415);
 let body;try{const text=await request.text();if(text.length>2000)throw 0;body=JSON.parse(text);}catch(_){return reply({error:'invalid_body'},400);}
 const keys=body&&typeof body==='object'&&!Array.isArray(body)?Object.keys(body):[];
 if(keys.some(k=>!['action','unitId','questionId','note'].includes(k))||!['pause','resume'].includes(body.action)||!ID.test(body.unitId||'')||!ID.test(body.questionId||'')||(body.note!==undefined&&(typeof body.note!=='string'||body.note.length>200||/[\x00-\x1f\x7f]/.test(body.note))))return reply({error:'invalid_body'},400);
 const unit=(units||[]).find(u=>u.id===body.unitId);
 if(!unit||![...(unit.questions||[]),...(unit.tests||[])].some(q=>q.id===body.questionId))return reply({error:'not_found'},404);
 const now=Date.now(),key='qflag:'+body.unitId+':'+body.questionId,value={unitId:body.unitId,questionId:body.questionId,paused:body.action==='pause',note:(body.note||'').trim(),at:now};
 const rand=[...crypto.getRandomValues(new Uint8Array(6))].map(b=>b.toString(16).padStart(2,'0')).join('');
 await db.batch([db.prepare('INSERT INTO auth_kv(k,v,expires_at) VALUES(?,?,0) ON CONFLICT(k) DO UPDATE SET v=excluded.v,expires_at=0').bind(key,JSON.stringify(value)),
  db.prepare('INSERT INTO auth_kv(k,v,expires_at) VALUES(?,?,?)').bind('activity:u1:'+String(now).padStart(15,'0')+':'+rand,JSON.stringify({type:'admin-flag',unitId:body.unitId,questionId:body.questionId,mock:false,at:now,paused:value.paused}),now+3650*DAY)]);
 return reply({ok:true,item:{unitId:value.unitId,questionId:value.questionId,paused:value.paused,note:value.note,at:now}});
}
// 📰 のびログ新聞（台帳51・2026-10-09）：なお（u1）が管理画面で書いて配る。家族は配られた号を読める。
// 文字だけ（画像・リンクなし）。号は消さない（取り下げは「非公開」にするだけ）。
const NP='newspaper:',NP_MAX=200;
const npClean=t=>typeof t==='string'?t.replace(/\r\n?/g,'\n'):null;
export async function newspaperRoute(request,env,session){
 if(!session||typeof session.uid!=='string'||!session.uid)return reply({error:'unauthorized'},401);
 if(!env.AUTH_DB)return reply({error:'unavailable'},503);
 const uid=session.uid,db=env.AUTH_DB,now=Date.now(),url=new URL(request.url);
 if(request.method==='GET'){
  if(url.search)return reply({error:'invalid_query'},400);
  if(!FAMILY.includes(uid))return reply({items:[]});
  const rows=(await db.prepare('SELECT v FROM auth_kv WHERE k>=? AND k<? ORDER BY k DESC LIMIT ?').bind(NP,NP+'￿',NP_MAX).all()).results||[];
  const all=rows.map(r=>{try{return JSON.parse(r.v);}catch(_){return null;}}).filter(Boolean);
  const items=uid==='u1'?all:all.filter(x=>!x.hidden&&x.publishAt<=now);
  return reply({now,items:items.map(x=>({id:x.id,title:x.title,body:x.body,publishAt:x.publishAt,...(uid==='u1'?{hidden:!!x.hidden,createdAt:x.createdAt}:{})}))});
 }
 if(request.method!=='POST')return reply({error:'method not allowed'},405);
 if(uid!=='u1')return reply({error:'forbidden'},403);
 const origin=request.headers.get('Origin');if(env.APP_ORIGIN&&origin!==env.APP_ORIGIN)return reply({error:'origin'},403);
 if(!/^application\/json\b/.test(request.headers.get('Content-Type')||''))return reply({error:'content_type'},415);
 let body;try{const text=await request.text();if(text.length>12000)throw 0;body=JSON.parse(text);}catch(_){return reply({error:'invalid_body'},400);}
 const keys=body&&typeof body==='object'&&!Array.isArray(body)?Object.keys(body):[];
 if(body?.action==='create'){
  if(keys.some(k=>!['action','title','body','publishAt'].includes(k)))return reply({error:'invalid_body'},400);
  const title=npClean(body.title),text=npClean(body.body),at=body.publishAt===undefined?now:body.publishAt;
  if(!title||!title.trim()||title.length>40||/[\x00-\x1f\x7f]/.test(title)||!text||!text.trim()||text.length>3000||/[\x00-\x09\x0b-\x1f\x7f]/.test(text)||!Number.isSafeInteger(at)||at<now-60000||at>now+60*DAY)return reply({error:'invalid_body'},400);
  const count=await db.prepare('SELECT COUNT(*) n FROM auth_kv WHERE k>=? AND k<?').bind(NP,NP+'￿').first('n');if(Number(count)>=NP_MAX)return reply({error:'limit'},409);
  const id=[...crypto.getRandomValues(new Uint8Array(12))].map(b=>b.toString(16).padStart(2,'0')).join(''),item={id,title:title.trim(),body:text.trim(),publishAt:at,createdAt:now,hidden:false};
  const rand=[...crypto.getRandomValues(new Uint8Array(6))].map(b=>b.toString(16).padStart(2,'0')).join('');
  await db.batch([db.prepare('INSERT INTO auth_kv(k,v,expires_at) VALUES(?,?,0)').bind(NP+String(at).padStart(15,'0')+':'+id,JSON.stringify(item)),
   db.prepare('INSERT INTO auth_kv(k,v,expires_at) VALUES(?,?,?)').bind('activity:u1:'+String(now).padStart(15,'0')+':'+rand,JSON.stringify({type:'newspaper-create',id,at:now}),now+3650*DAY)]);
  return reply({ok:true,item,notify:at<=now?{title:'📰 のびログ新聞',body:item.title}:null},201);
 }
 if(body?.action==='hide'||body?.action==='show'){
  if(keys.some(k=>!['action','id'].includes(k))||!/^[a-f0-9]{24}$/.test(body.id||''))return reply({error:'invalid_body'},400);
  const row=await db.prepare("SELECT k,v FROM auth_kv WHERE k>=? AND k<? AND json_extract(v,'$.id')=? LIMIT 1").bind(NP,NP+'￿',body.id).first();
  if(!row)return reply({error:'not_found'},404);
  const item={...JSON.parse(row.v),hidden:body.action==='hide'};
  await db.prepare('UPDATE auth_kv SET v=? WHERE k=?').bind(JSON.stringify(item),row.k).run();
  return reply({ok:true,item});
 }
 return reply({error:'invalid_body'},400);
}
