import engine from './material-engine.cjs';
import bank from './material-bank.mjs';
import wordBank from '../../site-assets/eiken-vocab-bank.json' with {type:'json'};
import {createWorkerAdapter} from './coop-story/worker-adapter.mjs';
const adapters=new WeakMap();
export async function coopStoryRoute(request,env,session,helpers){
 const snapshot=helpers?.snapshot;
 if(typeof snapshot!=='function')return helpers.json({error:'coop_unavailable'},503);
 let adapter=adapters.get(snapshot);
 if(!adapter){adapter=createWorkerAdapter({bank,engine,wordBank,snapshot});adapters.set(snapshot,adapter);}
 return adapter(request,env,session,helpers);
}
