import {profilesFor} from './admin-workspace.mjs';
const reply=(body,status=200)=>Response.json(body,{status,headers:{'Cache-Control':'no-store'}});
const MODES=['study','study-textbook','study-tokkun','study-drill','study-kentei','textbook','eiken','assignments','exam','calendar','settings','stats','test-setup','run','game','money','life','hyakumasu','ottake'];
const FILES=['index.html','admin.js','admin-studio.js','assignments.js','eiken-practice.js','textbook-book.js','material-ui.js','app'];
async function body(request){
 if(!/^application\/json\b/.test(request.headers.get('Content-Type')||''))throw Error();
 if(!request.body)throw Error();const reader=request.body.getReader(),parts=[];let n=0;
 try{while(true){const r=await reader.read();if(r.done)break;n+=r.value.length;if(n>512){await reader.cancel();throw Error();}parts.push(r.value);}}finally{reader.releaseLock();}
 const b=new Uint8Array(n);let at=0;for(const p of parts){b.set(p,at);at+=p.length;}return JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(b));
}
export async function monitorRoute(request,env,session){
 if(!session?.uid)return reply({error:'unauthorized'},401);
 if(!env.AUTH_DB)return reply({error:'unavailable'},503);
 const profiles=profilesFor(env),uid=session.uid,db=env.AUTH_DB,url=new URL(request.url),now=Date.now();
 if(url.search)return reply({error:'invalid_query'},400);
 if(url.pathname==='/admin/health'){
  if(uid!=='u1')return reply({error:'forbidden'},403);
  if(request.method!=='GET')return reply({error:'method_not_allowed'},405);
  const rows=(await db.prepare('SELECT v FROM auth_kv WHERE k>=? AND k<? ORDER BY k DESC LIMIT 50').bind('app-health:','app-health:\uffff').all()).results||[];
  return reply({items:rows.map(r=>JSON.parse(r.v)),now});
 }
 if(!['/learning-presence','/learning-health'].includes(url.pathname))return reply({error:'not_found'},404);
 if(!profiles.some(p=>p.uid===uid))return reply({error:'forbidden'},403);
 if(request.method!=='POST')return reply({error:'method_not_allowed'},405);
 if(!env.APP_ORIGIN||request.headers.get('Origin')!==env.APP_ORIGIN)return reply({error:'origin'},403);
 let b;try{b=await body(request);}catch(_){return reply({error:'invalid_body'},400);}
 if(!b||typeof b!=='object'||Array.isArray(b))return reply({error:'invalid_body'},400);
 if(url.pathname==='/learning-presence'){
  if(Object.keys(b).length!==1||!MODES.includes(b.mode))return reply({error:'invalid_body'},400);
  const key='learning-presence:'+uid,old=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(key).first('v');
  let last=null;try{last=JSON.parse(old);}catch(_){}
  const item={uid,mode:b.mode,startedAt:last?.mode===b.mode&&last.at>=now-120000?last.startedAt:now,at:now};
  await db.prepare('INSERT INTO auth_kv(k,v,expires_at) VALUES(?,?,?) ON CONFLICT(k) DO UPDATE SET v=excluded.v,expires_at=excluded.expires_at').bind(key,JSON.stringify(item),now+300000).run();
  return reply({ok:true,at:now});
 }
 if(Object.keys(b).some(k=>!['code','file','line'].includes(k))||!['runtime','sync','network'].includes(b.code)||!FILES.includes(b.file)||!Number.isInteger(b.line)||b.line<0||b.line>100000)return reply({error:'invalid_body'},400);
 const gate=await db.prepare('INSERT INTO auth_kv(k,v,expires_at) VALUES(?,?,?) ON CONFLICT(k) DO UPDATE SET v=excluded.v,expires_at=excluded.expires_at WHERE auth_kv.expires_at<=? RETURNING v').bind('app-health-gate:'+uid,String(now),now+60000,now).first('v');
 if(!gate)return reply({ok:true,limited:true});
 const id=String(now).padStart(15,'0')+':'+crypto.randomUUID().replace(/-/g,'').slice(0,12),item={id,uid,at:now,code:b.code,file:b.file,line:b.line};
 await db.prepare('INSERT INTO auth_kv(k,v,expires_at) VALUES(?,?,?)').bind('app-health:'+id,JSON.stringify(item),now+90*86400000).run();
 return reply({ok:true});
}
