// ✉️ メッセージ（Claude・2026-10-10）。人形マークのマイページから開く画面のサーバー側。
// ① なおから：お知らせ・応援（なおが書く）と、返却連絡（配布物の返却から自動。ここで二重に作らない）
// ② AI相談：learning-assistant.mjs の /learning-chat をそのまま使う（ここには置かない）
// ③ なおへの詳しい解説依頼：UNLIMIT だけ。本人の回答記録を1つ選んで送り、なおが管理画面で返信する
// 生徒どうしのチャットは作らない。書けるのは なお（u1）だけ、読めるのは本人だけ。UIDはセッションだけから決める。
import {planStatus,subscriptionOn,PREVIEW_PROFILES} from './plans.mjs';
const reply=(body,status=200)=>Response.json(body,{status,headers:{'Cache-Control':'no-store'}});
const MSG='nao-msg:',READ='nao-msg-read:',SENT='nao-msg-send:',REQ='explain-req:',W_PREFIX='assignment-work:',A_PREFIX='assignment:',DAY=86400000,JST=9*3600000;
export const KINDS=Object.freeze({notice:'お知らせ',cheer:'応援'});
export const REQUEST_STATUS=Object.freeze({received:'受付済み',reviewing:'確認中',answered:'返信済み'});
export const LIMITS=Object.freeze({title:60,body:2000,note:1000,reply:4000,openRequests:20,requestsPerDay:10,list:100,gapMs:3000});
const NAMES={u1:'なお',u2:'りらん',p_mini:'Mini 確認版',p_standard:'Standard 確認版',p_pro:'Pro 確認版',p_unlimit:'UNLIMIT 確認版'};
const uuid=/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/;
const msgId=/^\d{15}:[a-f0-9]{12}$/,assignmentId=/^[A-Za-z0-9_-]{1,80}$/;
// なおが送れる相手：りらんと、確認版の4プラン（確認版だけ）。なお自身・新規アカウントには送らない
export const recipients=env=>['u2',...(env&&env.PREVIEW_PLAN_ACCOUNTS==='1'&&subscriptionOn(env)?Object.keys(PREVIEW_PROFILES):[])];
const control=/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/;
const text=(v,max,lines=true)=>typeof v==='string'&&v.trim().length>0&&v.length<=max&&!control.test(v)&&(lines||!/[\r\n]/.test(v));
async function bodyJson(request,max){
 if(!/^application\/json\b/.test(request.headers.get('Content-Type')||''))throw Object.assign(Error('type'),{status:415});
 if(!request.body||Number(request.headers.get('Content-Length'))>max)throw Object.assign(Error('size'),{status:400});
 const reader=request.body.getReader(),parts=[];let n=0;
 try{while(true){const r=await reader.read();if(r.done)break;n+=r.value.byteLength;if(n>max){await reader.cancel();throw Object.assign(Error('size'),{status:400});}parts.push(r.value);}}finally{reader.releaseLock();}
 const bytes=new Uint8Array(n);let at=0;for(const p of parts){bytes.set(p,at);at+=p.byteLength;}
 let b;try{b=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes));}catch(_){throw Object.assign(Error('json'),{status:400});}
 if(!b||typeof b!=='object'||Array.isArray(b))throw Object.assign(Error('shape'),{status:400});
 return b;
}
const keysAre=(b,need,optional=[])=>Object.keys(b).every(k=>need.includes(k)||optional.includes(k))&&need.every(k=>Object.hasOwn(b,k));
const originOk=(request,env)=>!env.APP_ORIGIN||request.headers.get('Origin')===env.APP_ORIGIN;
const rand=()=>[...crypto.getRandomValues(new Uint8Array(6))].map(x=>x.toString(16).padStart(2,'0')).join('');
// 連打の見張り：同じ人の同じ種類の送信は gap ミリ秒に1回まで
async function gate(db,key,gap,now){
 return !!await db.prepare("INSERT INTO auth_kv(k,v,expires_at) VALUES(?,?,?) ON CONFLICT(k) DO UPDATE SET v=excluded.v,expires_at=excluded.expires_at WHERE auth_kv.expires_at<=? RETURNING v").bind(key,String(now),now+gap,now).first('v');
}
const planOf=async(env,uid,now)=>{try{return await planStatus(env,uid,now);}catch(_){return null;}};

// ① なおから（本人が読む）
async function inbox(request,env,uid,now){
 const db=env.AUTH_DB,url=new URL(request.url);
 if(request.method==='GET'){
  if(url.search)return reply({error:'invalid_query'},400);
  const direct=((await db.prepare('SELECT v FROM auth_kv WHERE k>=? AND k<? ORDER BY k DESC LIMIT ?').bind(MSG+uid+':',MSG+uid+':￿',LIMITS.list).all()).results||[]).map(r=>JSON.parse(r.v)).map(m=>({id:m.id,kind:m.kind,label:KINDS[m.kind]||'お知らせ',title:m.title,body:m.body,at:m.at,readAt:m.readAt||null,assignmentId:m.assignmentId||null,from:'なお'}));
  // 返却連絡：配布物の返却そのものを読む（返却の通知は assignments.mjs が送るので、ここでは作らない）
  const works=(await db.prepare("SELECT k,v FROM auth_kv WHERE k>=? AND k<? AND json_extract(v,'$.uid')=? AND json_extract(v,'$.review.returnedAt') IS NOT NULL LIMIT 300").bind(W_PREFIX,W_PREFIX+'￿',uid).all()).results||[];
  const returns=[];
  for(const r of works){
   const w=JSON.parse(r.v);if(r.k!==W_PREFIX+w.id+':'+uid)continue;
   const a=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(A_PREFIX+w.id).first('v');if(!a)continue;
   const title=JSON.parse(a).title||'配布物',read=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(READ+uid+':return:'+w.id).first('v');
   returns.push({id:'return:'+w.id,kind:'return',label:'返却連絡',title:'「'+title+'」が返却されました',body:'なおが見て返しました。配布物を開くと、コメントと点数を確認できます。',at:w.review.returnedAt,readAt:read?Number(read):null,assignmentId:w.id,from:'なお'});
  }
  const items=[...direct,...returns].sort((x,y)=>y.at-x.at).slice(0,LIMITS.list);
  return reply({items,unread:items.filter(x=>!x.readAt).length,serverTime:now});
 }
 if(request.method!=='POST')return reply({error:'method_not_allowed'},405);
 if(!originOk(request,env))return reply({error:'origin'},403);
 let b;try{b=await bodyJson(request,400);}catch(e){return reply({error:'invalid_body'},e.status||400);}
 if(!keysAre(b,['action','id'])||b.action!=='read'||typeof b.id!=='string')return reply({error:'invalid_body'},400);
 if(msgId.test(b.id)){
  const k=MSG+uid+':'+b.id,row=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(k).first('v');
  if(!row)return reply({error:'not_found'},404);
  await db.prepare("UPDATE auth_kv SET v=json_set(v,'$.readAt',?) WHERE k=? AND json_extract(v,'$.readAt') IS NULL").bind(now,k).run();
  return reply({ok:true});
 }
 const m=/^return:([A-Za-z0-9_-]{1,80})$/.exec(b.id);
 if(!m)return reply({error:'invalid_body'},400);
 const w=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(W_PREFIX+m[1]+':'+uid).first('v');
 if(!w||!JSON.parse(w).review?.returnedAt)return reply({error:'not_found'},404);
 await db.prepare('INSERT INTO auth_kv(k,v,expires_at) VALUES(?,?,0) ON CONFLICT(k) DO NOTHING').bind(READ+uid+':return:'+m[1],String(now)).run();
 return reply({ok:true});
}

// ③ なおへの解説依頼（本人）
function publicRequest(r){return {id:r.id,status:r.status,label:REQUEST_STATUS[r.status],at:r.at,updatedAt:r.updatedAt,attempt:r.attempt,note:r.note,reply:r.reply||null};}
async function requests(request,env,uid,now){
 const db=env.AUTH_DB,url=new URL(request.url),prefix=REQ+uid+':';
 const plan=await planOf(env,uid,now);
 if(!plan)return reply({error:'plan_unavailable'},503);
 const allowed=!!plan.provisional&&!!plan.features?.nao;
 if(request.method==='GET'){
  if(url.search)return reply({error:'invalid_query'},400);
  const rows=((await db.prepare('SELECT v FROM auth_kv WHERE k>=? AND k<? LIMIT 500').bind(prefix,prefix+'￿').all()).results||[]).map(r=>JSON.parse(r.v)).sort((x,y)=>y.at-x.at);
  // 解約後は UNLIMIT 専用の解説を見せないだけ（消さない）。また UNLIMIT になれば同じ内容が戻る
  if(!allowed)return reply({items:[],locked:true,hidden:rows.length,plan:plan.plan||'free'});
  return reply({items:rows.slice(0,LIMITS.list).map(publicRequest),locked:false,hidden:0,plan:plan.plan,limits:{openRequests:LIMITS.openRequests,requestsPerDay:LIMITS.requestsPerDay}});
 }
 if(request.method!=='POST')return reply({error:'method_not_allowed'},405);
 if(!originOk(request,env))return reply({error:'origin'},403);
 let b;try{b=await bodyJson(request,6000);}catch(e){return reply({error:'invalid_body'},e.status||400);}
 if(!keysAre(b,['id','attemptId','note'])||!uuid.test(b.id)||!uuid.test(b.attemptId)||typeof b.note!=='string'||b.note.length>LIMITS.note||control.test(b.note))return reply({error:'invalid_body'},400);
 if(!allowed)return reply({error:'plan_required'},403);
 const key=prefix+b.id,same=r=>r.attemptId===b.attemptId&&r.note===b.note.trim();
 const old=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(key).first('v');
 // 同じ送信の再送（通信が切れたときなど）は1件のまま。中身がちがうIDの使い回しは断る
 if(old){const r=JSON.parse(old);return same(r)?reply({item:publicRequest(r),duplicate:true}):reply({error:'id_conflict'},409);}
 const raw=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind('material-attempt:'+uid+':'+b.attemptId).first('v');
 if(!raw)return reply({error:'attempt_not_found'},404);
 const all=((await db.prepare('SELECT v FROM auth_kv WHERE k>=? AND k<? LIMIT 500').bind(prefix,prefix+'￿').all()).results||[]).map(r=>JSON.parse(r.v));
 const today=Math.floor((now+JST)/DAY);
 if(all.filter(r=>r.status!=='answered').length>=LIMITS.openRequests)return reply({error:'too_many_open'},409);
 if(all.filter(r=>Math.floor((r.at+JST)/DAY)===today).length>=LIMITS.requestsPerDay)return reply({error:'daily_limit'},429);
 if(!await gate(db,'explain-gap:'+uid,LIMITS.gapMs,now))return reply({error:'too_fast'},429);
 const a=JSON.parse(raw);
 const item={id:b.id,uid,attemptId:b.attemptId,status:'received',at:now,updatedAt:now,note:b.note.trim(),reply:null,
  attempt:{unitId:a.unitId,unitTitle:a.unitTitle||'',subject:a.subject||'',questionId:a.questionId,mode:a.mode,prompt:String(a.prompt||'').slice(0,2000),answer:String(a.answer||'').slice(0,2000),correct:a.result?.correct===true,at:a.at}};
 const saved=await db.prepare('INSERT INTO auth_kv(k,v,expires_at) VALUES(?,?,0) ON CONFLICT(k) DO NOTHING RETURNING v').bind(key,JSON.stringify(item)).first('v');
 if(!saved){const again=JSON.parse(await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(key).first('v'));return same(again)?reply({item:publicRequest(again),duplicate:true}):reply({error:'id_conflict'},409);}
 return reply({item:publicRequest(item),notify:{uid:'u1',id:'explain-req:'+uid+':'+b.id,title:'解説の依頼が届きました',body:(NAMES[uid]||uid)+'から「'+(item.attempt.unitTitle||'問題')+'」の解説依頼です。管理の「解説依頼」で確認してください。'}},201);
}

// なお（u1）の管理画面：メッセージを送る・解説依頼の提出箱
async function admin(request,env,uid,now){
 if(uid!=='u1')return reply({error:'forbidden'},403);
 const db=env.AUTH_DB,url=new URL(request.url);
 if(url.pathname==='/admin/messages'){
  if(request.method==='GET'){
   if(url.search)return reply({error:'invalid_query'},400);
   const items=((await db.prepare('SELECT v FROM auth_kv WHERE k>=? AND k<? LIMIT 2000').bind(MSG,MSG+'￿').all()).results||[]).map(r=>JSON.parse(r.v)).sort((x,y)=>y.at-x.at).slice(0,LIMITS.list).map(m=>({...m,name:NAMES[m.uid]||m.uid}));
   return reply({items,recipients:recipients(env).map(u=>({uid:u,name:NAMES[u]||u})),kinds:KINDS,serverTime:now});
  }
  if(request.method!=='POST')return reply({error:'method_not_allowed'},405);
  if(!originOk(request,env))return reply({error:'origin'},403);
  let b;try{b=await bodyJson(request,12000);}catch(e){return reply({error:'invalid_body'},e.status||400);}
  if(!keysAre(b,['id','uid','kind','title','body'],['assignmentId'])||!uuid.test(b.id)||!recipients(env).includes(b.uid)||!Object.hasOwn(KINDS,b.kind)||!text(b.title,LIMITS.title,false)||!text(b.body,LIMITS.body)||(b.assignmentId!==undefined&&b.assignmentId!==null&&(typeof b.assignmentId!=='string'||!assignmentId.test(b.assignmentId))))return reply({error:'invalid_body'},400);
  if(b.assignmentId&&!await db.prepare('SELECT 1 AS x FROM auth_kv WHERE k=?').bind(A_PREFIX+b.assignmentId).first('x'))return reply({error:'assignment_not_found'},404);
  // 再送で二重に届かないよう、送信IDごとに1通だけ（送信IDの印にメッセージの置き場所を書いておく）
  const fresh=MSG+b.uid+':'+String(now).padStart(15,'0')+':'+rand();
  const target=await db.prepare('INSERT INTO auth_kv(k,v,expires_at) VALUES(?,?,0) ON CONFLICT(k) DO NOTHING RETURNING v').bind(SENT+b.id,fresh).first('v')||await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(SENT+b.id).first('v');
  if(!target||!target.startsWith(MSG+b.uid+':'))return reply({error:'id_conflict'},409);
  const existing=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(target).first('v');
  if(existing)return reply({item:JSON.parse(existing),duplicate:true});
  const item={id:target.slice(-28),uid:b.uid,kind:b.kind,title:b.title.trim(),body:b.body.trim(),assignmentId:b.assignmentId||null,at:now,readAt:null};
  await db.prepare('INSERT INTO auth_kv(k,v,expires_at) VALUES(?,?,0) ON CONFLICT(k) DO NOTHING').bind(target,JSON.stringify(item)).run();
  return reply({item,notify:{uid:b.uid,id:'nao-msg:'+item.id,title:'なおから：'+item.title,body:item.body.slice(0,120)}},201);
 }
 // /admin/explain-requests
 if(request.method==='GET'){
  if(url.search)return reply({error:'invalid_query'},400);
  const items=((await db.prepare('SELECT v FROM auth_kv WHERE k>=? AND k<? LIMIT 2000').bind(REQ,REQ+'￿').all()).results||[]).map(r=>JSON.parse(r.v)).sort((x,y)=>(x.status==='answered')-(y.status==='answered')||y.at-x.at).slice(0,200).map(r=>({...publicRequest(r),uid:r.uid,name:NAMES[r.uid]||r.uid}));
  return reply({items,statuses:REQUEST_STATUS,serverTime:now});
 }
 if(request.method!=='POST')return reply({error:'method_not_allowed'},405);
 if(!originOk(request,env))return reply({error:'origin'},403);
 let b;try{b=await bodyJson(request,20000);}catch(e){return reply({error:'invalid_body'},e.status||400);}
 const okStatus=b.action==='status'&&keysAre(b,['action','uid','id','status'])&&b.status==='reviewing';
 const okReply=b.action==='reply'&&keysAre(b,['action','uid','id','text'])&&text(b.text,LIMITS.reply);
 if((!okStatus&&!okReply)||typeof b.uid!=='string'||!/^[a-z0-9_]{2,40}$/.test(b.uid)||!uuid.test(b.id))return reply({error:'invalid_body'},400);
 const key=REQ+b.uid+':'+b.id,raw=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(key).first('v');
 if(!raw)return reply({error:'not_found'},404);
 const r=JSON.parse(raw);
 if(r.status==='answered')return reply({error:'already_answered'},409);
 if(okStatus&&r.status==='reviewing')return reply({item:{...publicRequest(r),uid:r.uid,name:NAMES[r.uid]||r.uid},notify:null});
 const next=okStatus?{...r,status:'reviewing',updatedAt:now}:{...r,status:'answered',updatedAt:now,reply:{text:b.text.trim(),at:now}};
 const saved=await db.prepare("UPDATE auth_kv SET v=? WHERE k=? AND json_extract(v,'$.status')=? RETURNING v").bind(JSON.stringify(next),key,r.status).first('v');
 if(!saved)return reply({error:'changed'},409);
 return reply({item:{...publicRequest(next),uid:r.uid,name:NAMES[r.uid]||r.uid},notify:okReply?{uid:r.uid,id:'explain-reply:'+r.id,title:'なおから解説が届きました',body:'「'+(r.attempt.unitTitle||'問題')+'」の解説依頼に返信がありました。メッセージで確認できます。'}:null});
}

export async function messagesRoute(request,env,session){
 if(!session||typeof session.uid!=='string'||!session.uid)return reply({error:'unauthorized'},401);
 if(!env.AUTH_DB)return reply({error:'unavailable'},503);
 const url=new URL(request.url),uid=session.uid,now=Date.now();
 if(url.pathname==='/admin/messages'||url.pathname==='/admin/explain-requests')return admin(request,env,uid,now);
 // 読めるのは なお・りらんと確認版の4プランだけ。新規アカウントは空のまま（家族データを見せない）
 if(uid!=='u1'&&!recipients(env).includes(uid))return request.method==='GET'?reply({items:[],unread:0,locked:true,hidden:0}):reply({error:'forbidden'},403);
 if(url.pathname==='/messages')return inbox(request,env,uid,now);
 if(url.pathname==='/explain-requests'){if(!subscriptionOn(env))return reply({error:'not_found'},404);return requests(request,env,uid,now);}
 return reply({error:'not_found'},404);
}
