    (h==='web.push.apple.com' && u.pathname.length>1) ||
    (h==='updates.push.services.mozilla.com' && /^\/wpush\/v[12]\/.+/.test(u.pathname)) ||
    (/^(?:[a-z0-9-]+\.)?notify\.windows\.com$/.test(h) && /^\/wpush\/v[12]$/.test(u.pathname));
  if(u.protocol!=='https:'||u.username||u.password||u.port||u.hash||!provider) throw new Error('invalid_endpoint');
