  const nonce=(await pushHMAC(prk,pushEncoder.encode('Content-Encoding: nonce\0\x01'))).slice(0,12);
  const key=await crypto.subtle.importKey('raw',cek,'AES-GCM',false,['encrypt']);
  const encrypted=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv:nonce},key,pushConcat(plaintext,new Uint8Array([2]))));
