  const signature=await crypto.subtle.sign({name:'ECDSA',hash:'SHA-256'},signing.privateKey,pushEncoder.encode(token));
  return 'vapid t='+token+'.'+pushB64(signature)+', k='+pushB64(signing.publicBytes);
