    // Recheck ownership and preferences immediately before encrypting/sending.
    const fresh=await env.AUTH_DB.prepare("SELECT v FROM auth_kv WHERE k=? AND json_extract(v,'$.uid')=?").bind(subscription.key,subscription.uid).first();
