// Private textbook handwriting. Existing authenticated session/lease; never changes teaching or grades.
import F from './textbook-ink-format.cjs';
import {textbookAccessOn,textbookAccess,textbookWriteGuard} from './textbook-access.mjs';
const reply=(v,status=200)=>Response.json(v,{status,headers:{'Cache-Control':'no-store'}});
const ACTIVE='EXISTS (SELECT 1 FROM auth_kv WHERE k=? AND v=? AND expires_at>?)';
async function bodyJson(request){
 if(!request.body||Number(request.headers.get('Content-Length'))>360000)throw Error('body');
 const reader=request.body.getReader(),parts=[];let n=0;
 try{for(;;){const {done,value}=await reader.read();if(done)break;n+=value.byteLength;if(n>360000){await reader.cancel();throw Error('body');}parts.push(value);}}finally{reader.releaseLock();}
 const bytes=new Uint8Array(n);let at=0;for(const p of parts){bytes.set(p,at);at+=p.byteLength;}
 return JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes));
}
export async function textbookInkRoute(request,env,session,{owner,now=()=>Date.now(),capacity=256}={}){
 if(!textbookAccessOn(env))return reply({error:'not_found'},404);
 if(!session?.uid||typeof owner!=='string'||!owner)return reply({error:'unauthorized'},401);
 const uid=session.uid;
 if(!/^(?:u[124]|p_(?:free|mini|standard|pro|unlimit))$/.test(uid))return reply({error:'forbidden'},403);
 if(uid.startsWith('p_')&&env.PREVIEW_PLAN_ACCOUNTS!=='1')return reply({error:'forbidden'},403);
 if(!env.AUTH_DB)return reply({error:'unavailable'},503);
 const url=new URL(request.url),db=env.AUTH_DB;
 if(url.pathname!=='/textbook-ink')return reply({error:'not_found'},404);
 const guard=()=>['active-session:'+uid,owner,now()];
 const active=async()=>!!await db.prepare('SELECT v FROM auth_kv WHERE k=? AND v=? AND expires_at>?').bind(...guard()).first('v');
 try{
  if(!await active())return reply({error:'active_session'},409);
  if(request.method==='GET'){
   const book=url.searchParams.get('book'),anchor=url.searchParams.get('anchor');
   if([...url.searchParams.keys()].some(k=>!['book','anchor'].includes(k))||url.searchParams.getAll('book').length!==1||url.searchParams.getAll('anchor').length>1||!F.BOOKS.includes(book)||(anchor!==null&&!F.anchor(anchor)))return reply({error:'invalid_query'},400);
   const status=await textbookAccess(env,uid,now()),prefix='textbook-ink:'+uid+':'+book+':';
   let result;
   if(anchor!==null){const raw=await db.prepare('SELECT v FROM auth_kv WHERE k=? AND '+ACTIVE).bind(prefix+anchor,...guard()).first('v');const item=raw?JSON.parse(raw):null;if(item&&!F.rowValid(item,book))throw Error('stored row');result={book,item,writable:!!status.features?.annotations};}
   else{const rows=(await db.prepare("SELECT json_extract(v,'$.anchor') AS anchor,json_extract(v,'$.quote') AS quote,json_extract(v,'$.revision') AS revision,json_extract(v,'$.updatedAt') AS updatedAt FROM auth_kv WHERE k>=? AND k<? AND "+ACTIVE+' ORDER BY k LIMIT 257').bind(prefix,prefix+'\uffff',...guard()).all()).results||[];if(rows.length>256)throw Error('capacity');result={book,items:rows,writable:!!status.features?.annotations};}
   if(!await active())return reply({error:'active_session'},409);
   return reply(result);
  }
  if(request.method!=='POST')return reply({error:'method_not_allowed'},405);
  if(url.search)return reply({error:'invalid_query'},400);
  if(!env.APP_ORIGIN||request.headers.get('Origin')!==env.APP_ORIGIN)return reply({error:'origin'},403);
  if(!/^application\/json\b/.test(request.headers.get('Content-Type')||''))return reply({error:'content_type'},415);
  let b;try{b=await bodyJson(request);}catch{return reply({error:'invalid_body'},400);}
  if(!F.draftValid(b,b?.book))return reply({error:'invalid_body'},400);
  const status=await textbookAccess(env,uid,now());
  if(!status.features?.annotations)return reply({error:'plan_required'},403);
  // The final write pins the actual owner and textbook release/contract/approval snapshot.
  const writeGuard=textbookWriteGuard(status,{uid,owner,feature:'annotations',now:now()});
  const prefix='textbook-ink:'+uid+':'+b.book+':',key=prefix+b.anchor,item={...b,revision:b.revision+1,updatedAt:now()};
  const raw=b.revision===0
   ?await db.prepare('INSERT INTO auth_kv(k,v,expires_at) SELECT ?,?,0 WHERE '+writeGuard.sql+' AND (SELECT COUNT(*) FROM auth_kv WHERE k>=? AND k<?)<? ON CONFLICT(k) DO NOTHING RETURNING v').bind(key,JSON.stringify(item),...writeGuard.values,prefix,prefix+'\uffff',capacity).first('v')
   :await db.prepare("UPDATE auth_kv SET v=? WHERE k=? AND CAST(json_extract(v,'$.revision') AS INTEGER)=? AND "+writeGuard.sql+' RETURNING v').bind(JSON.stringify(item),key,b.revision,...writeGuard.values).first('v');
  if(raw)return reply({item:JSON.parse(raw),cached:false});
  if(!await active())return reply({error:'active_session'},409);
  const latest=await textbookAccess(env,uid,now());
  if(latest.accessVersion!==status.accessVersion||!latest.features.annotations)return reply({error:'plan_changed'},409);
  const existing=await db.prepare('SELECT v FROM auth_kv WHERE k=? AND '+ACTIVE).bind(key,...guard()).first('v');
  if(existing){const row=JSON.parse(existing);if(F.rowValid(row,b.book)&&row.revision===b.revision+1&&row.quote===b.quote&&JSON.stringify(row.doc)===JSON.stringify(b.doc))return reply({item:row,cached:true});return reply({error:'revision_conflict'},409);}
  return reply({error:b.revision===0?'ink_limit':'revision_conflict'},409);
 }catch(error){if(['release_changed','plan_changed'].includes(error?.message))return reply({error:'plan_changed'},409);return reply({error:request.method==='GET'?'load_failed':'save_failed'},503);}
}
