import {finishedTestReviewResult} from './ai-test-review-jobs.mjs';
import {publicReviewPractice,gradeReviewPractice} from './ai-review-practice-library.mjs';
const UUID=/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/;
const UID=/^(?:u[124]|p_(?:free|mini|standard|pro|unlimit))$/;
const validId=v=>typeof v==='string'&&v.length>0&&v.length<=160&&!/[\x00-\x1f\x7f<>]/.test(v);
const reply=(v,status=200)=>Response.json(v,{status,headers:{'Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff'}});
const exact=(v,keys)=>v&&typeof v==='object'&&!Array.isArray(v)&&Object.keys(v).sort().join(',')===keys;
async function body(request){
 if(!/^application\/json(?:\s*;|$)/i.test(request.headers.get('Content-Type')||'')||!request.body)throw Error('invalid_body');
 const reader=request.body.getReader(),parts=[];let size=0;try{for(;;){const p=await reader.read();if(p.done)break;size+=p.value.byteLength;if(size>20000){await reader.cancel();throw Error('invalid_body');}parts.push(p.value);}}finally{reader.releaseLock();}
 const bytes=new Uint8Array(size);let at=0;for(const p of parts){bytes.set(p,at);at+=p.byteLength;}return JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes));
}
// Parent verifies the authenticated session and supplies only its opaque owner.
// Completion is independently rechecked here; client booleans never grant access.
export async function reviewPracticeRoute(request,env,session,{owner,now=()=>Date.now()}={}){
 const url=new URL(request.url),uid=session?.uid;
 if(url.pathname!=='/material-test-review/practice')return reply({error:'not_found'},404);
 if(!UID.test(uid||'')||uid.startsWith('p_')&&env.PREVIEW_PLAN_ACCOUNTS!=='1'||typeof owner!=='string'||!owner)return reply({error:'unauthorized'},401);
 if(!['GET','POST'].includes(request.method))return reply({error:'method_not_allowed'},405);
 const origin=request.headers.get('Origin');if((request.method==='POST'||origin!==null)&&origin!==env.APP_ORIGIN)return reply({error:'origin'},403);
 if(!env.AUTH_DB)return reply({error:'unavailable'},503);
 try{
  let selection;
  if(request.method==='GET'){
   if(!['jobId,practiceId,questionId','attemptId,jobId,practiceId,questionId'].includes([...url.searchParams.keys()].sort().join(','))||[...url.searchParams.keys()].some(k=>url.searchParams.getAll(k).length!==1)||url.searchParams.has('attemptId')&&!UUID.test(url.searchParams.get('attemptId')))return reply({error:'invalid_query'},400);
   selection=Object.fromEntries(url.searchParams);
  }else{
   if(url.search)return reply({error:'invalid_query'},400);
   try{selection=await body(request);}catch{return reply({error:'invalid_body'},400);}
   if(!exact(selection,'answer,id,jobId,practiceId,questionId')||!UUID.test(selection.id||'')||typeof selection.answer!=='string'||!selection.answer.trim()||selection.answer.length>4000||/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/.test(selection.answer))return reply({error:'invalid_body'},400);
  }
  if(!UUID.test(selection.jobId||'')||!validId(selection.questionId)||!validId(selection.practiceId))return reply({error:'invalid_query'},400);
  const began=performance.now(),base=now(),clock=()=>base+Math.ceil(performance.now()-began),db=env.AUTH_DB;
  const active=async()=>!!await db.prepare('SELECT 1 AS x FROM auth_kv WHERE k=? AND v=? AND expires_at>?').bind('active-session:'+uid,owner,clock()).first('x');
  const saved=await finishedTestReviewResult(env,uid,selection.jobId,{owner,now:clock()});
  if(!saved||saved.job.state!=='done')return reply({error:'not_found'},404);
  const item=saved.items.find(i=>i.questionId===selection.questionId),source=saved.questions.find(q=>q.id===selection.questionId);
  if(!item||item.practiceId!==selection.practiceId||!source)return reply({error:'not_found'},404);
  const question=await publicReviewPractice(source,selection.practiceId);
  if(!question)return reply({error:'not_found'},404);
  if(!await active())return reply({error:'active_session'},409);
  if(request.method==='GET'){
   if(!selection.attemptId)return reply({question});
   const raw=await db.prepare('SELECT v FROM auth_kv WHERE k=? AND expires_at=0').bind('ai-review-practice-attempt:'+uid+':'+selection.attemptId).first('v');let receipt=null;
   if(raw){const row=JSON.parse(raw),fp=JSON.parse(row.fingerprint);if(row.version!==1||row.id!==selection.attemptId||fp.jobId!==selection.jobId||fp.questionId!==selection.questionId||fp.practiceId!==selection.practiceId)return reply({error:'not_found'},404);const result=await gradeReviewPractice(source,selection.practiceId,fp.answer);if(JSON.stringify(row.result)!==JSON.stringify(result)||!Number.isSafeInteger(row.at)||row.at<0)throw Error('invalid_saved_practice');receipt={id:row.id,at:row.at,result:row.result,cached:true};}
   if(!await active())return reply({error:'active_session'},409);return reply({question,receipt});
  }
  const key='ai-review-practice-attempt:'+uid+':'+selection.id,fingerprint=JSON.stringify({jobId:selection.jobId,questionId:selection.questionId,practiceId:selection.practiceId,answer:selection.answer}),result=await gradeReviewPractice(source,selection.practiceId,selection.answer);
  const decode=raw=>{const row=JSON.parse(raw);if(!exact(row,'at,fingerprint,id,result,version')||row.version!==1||row.id!==selection.id||row.fingerprint!==fingerprint||!Number.isSafeInteger(row.at)||row.at<0||JSON.stringify(row.result)!==JSON.stringify(result))throw Error(row?.fingerprint!==fingerprint?'id_conflict':'invalid_saved_practice');return row;};
  const shown=(row,cached)=>({id:row.id,at:row.at,result:row.result,cached});
  const existing=await db.prepare('SELECT v FROM auth_kv WHERE k=? AND expires_at=0').bind(key).first('v');
  if(existing){const row=decode(existing);if(!await active())return reply({error:'active_session'},409);return reply(shown(row,true));}
  const row={version:1,id:selection.id,at:clock(),fingerprint,result};
  // Immutable receipt + current active owner are tested in the same statement.
  const raw=await db.prepare('INSERT INTO auth_kv(k,v,expires_at) SELECT ?,?,0 WHERE EXISTS(SELECT 1 FROM auth_kv WHERE k=? AND v=? AND expires_at>?) AND (SELECT COUNT(*) FROM auth_kv WHERE k>=? AND k<?) < 10000 ON CONFLICT(k) DO NOTHING RETURNING v').bind(key,JSON.stringify(row),'active-session:'+uid,owner,clock(),'ai-review-practice-attempt:'+uid+':','ai-review-practice-attempt:'+uid+':\uffff').first('v');
  if(!await active())return reply({error:'active_session'},409);
  if(raw)return reply(shown(decode(raw),false));
  const recovered=await db.prepare('SELECT v FROM auth_kv WHERE k=? AND expires_at=0').bind(key).first('v');
  if(!await active())return reply({error:'active_session'},409);
  return recovered?reply(shown(decode(recovered),true)):reply({error:'practice_limit'},429);
 }catch(error){const code=error?.message;return reply({error:code==='session_changed'?'active_session':code==='id_conflict'?code:'practice_unavailable'},['session_changed','id_conflict'].includes(code)?409:503);}
}
