// 📮 配布物（台帳41・Claude・2026-10-07）
// なお（u1）が課題を配る → 生徒が答えて提出 → なおが1問ずつコメントして返却 → 生徒が返却を見る。
// ・保存先は認証用D1の auth_kv。時刻はすべてサーバーの Date.now()（端末の時計は信用しない）。
// ・見本の答えは保存するが、生徒には絶対に返さない。提出物を読めるのは本人と u1 だけ。x_ アカウントは空の一覧。
// ・活動の記録（activity:）には答えやコメントの文章を残さない。
const reply=(body,status=200)=>Response.json(body,{status,headers:{'Cache-Control':'no-store'}});
import {profilesFor} from './admin-workspace.mjs';
const FAMILY=['u1','u2'],NAMES={u1:'なお',u2:'りらん',p_free:'f1 · Free',p_mini:'m1 · Mini',p_standard:'s1 · Standard',p_pro:'p1 · Pro',p_unlimit:'u1 · UNLIMIT'};
export const LIMITS=Object.freeze({title:60,note:1000,prompt:1000,model:1000,questions:50,questionText:60000,points:100,answer:4000,answersTotal:20000,comment:1000,overall:2000,minutes:300,horizonMs:366*86400000,openSlackMs:5*60000,minSpanMs:60000,assignments:300,draftsPerMinute:20});
const BODY_LIMIT={create:262144,other:131072};
const A_PREFIX='assignment:',W_PREFIX='assignment-work:';
const validId=id=>typeof id==='string'&&/^[a-f0-9]{32}$/.test(id);
const QID=/^[A-Za-z][A-Za-z0-9_-]{0,19}$/;// 先頭は英字（__proto__ などを問題idにさせない）
const isObj=v=>!!v&&typeof v==='object'&&!Array.isArray(v);
const keysOk=(o,allowed,required)=>isObj(o)&&Object.keys(o).every(k=>allowed.includes(k))&&required.every(k=>Object.prototype.hasOwnProperty.call(o,k));
const randHex=n=>Array.from(crypto.getRandomValues(new Uint8Array(n)),b=>b.toString(16).padStart(2,'0')).join('');
const BAD_CHARS=/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f\u2028\u2029\u202a-\u202e\u2066-\u2069]|[\ud800-\udbff](?![\udc00-\udfff])|(?<![\ud800-\udbff])[\udc00-\udfff]/;
class Refuse extends Error{constructor(code,status){super(code);this.code=code;this.status=status;}}
const refuse=(code,status=400)=>{throw new Refuse(code,status);};
// 文章：改行は \n にそろえる。制御文字・向きを変える見えない文字・壊れた文字はことわる
function text(v,max,{line=false,required=false,trim=false}={}){
    if(typeof v!=='string')return null;
    let s=v.replace(/\r\n?/g,'\n');
    if(trim)s=s.trim();
    if(BAD_CHARS.test(s)||(line&&s.includes('\n'))||s.length>max||(required&&!s.trim()))return null;
    return s;
}
async function readBody(request,limit){
    if(!request.body||Number(request.headers.get('Content-Length'))>limit)throw new Error('body');
    const reader=request.body.getReader();let total=0;const parts=[];
    try{while(true){const {done,value}=await reader.read();if(done)break;total+=value.length;if(total>limit){await reader.cancel();throw new Error('body');}parts.push(value);}}finally{reader.releaseLock();}
    const bytes=new Uint8Array(total);let offset=0;for(const part of parts){bytes.set(part,offset);offset+=part.length;}
    return JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes));
}
// ---- 配る内容の検査 ----
export function cleanAssignment(raw,now,allowed=FAMILY){
    if(!keysOk(raw,['title','note','targets','openAt','dueAt','minutes','questions'],['title','targets','openAt','dueAt','questions']))refuse('invalid_assignment');
    const title=text(raw.title,LIMITS.title,{line:true,required:true,trim:true});if(title===null)refuse('invalid_title');
    const note=raw.note===undefined?'':text(raw.note,LIMITS.note,{trim:true});if(note===null)refuse('invalid_note');
    if(!Array.isArray(raw.targets)||!raw.targets.length||raw.targets.length>allowed.length||raw.targets.some(t=>!allowed.includes(t))||new Set(raw.targets).size!==raw.targets.length)refuse('invalid_targets');
    const targets=allowed.filter(t=>raw.targets.includes(t));
    let {openAt,dueAt}=raw;
    if(!Number.isSafeInteger(openAt)||!Number.isSafeInteger(dueAt))refuse('invalid_time');
    if(openAt<now-LIMITS.openSlackMs)refuse('open_in_past');
    if(openAt<now)openAt=now;// 「今すぐ」は通信の遅れぶんだけ過去になるので、今にそろえる
    if(openAt>now+LIMITS.horizonMs||dueAt>now+LIMITS.horizonMs)refuse('too_far');
    if(dueAt<openAt+LIMITS.minSpanMs)refuse('due_before_open');
    const minutes=raw.minutes===undefined||raw.minutes===null?null:raw.minutes;
    if(minutes!==null&&!(Number.isInteger(minutes)&&minutes>=1&&minutes<=LIMITS.minutes))refuse('invalid_minutes');
    if(!Array.isArray(raw.questions)||!raw.questions.length||raw.questions.length>LIMITS.questions)refuse('invalid_questions');
    const ids=new Set();let textTotal=0;
    const questions=raw.questions.map((q,i)=>{
        if(!keysOk(q,['id','prompt','answer','points'],['prompt','points']))refuse('invalid_question');
        const id=q.id===undefined||q.id===null?'q'+(i+1):q.id;
        if(typeof id!=='string'||!QID.test(id)||ids.has(id))refuse('invalid_question_id');ids.add(id);
        const prompt=text(q.prompt,LIMITS.prompt,{required:true,trim:true});if(prompt===null)refuse('invalid_prompt');
        let answer=null;
        if(q.answer!==undefined&&q.answer!==null){answer=text(q.answer,LIMITS.model,{trim:true});if(answer===null)refuse('invalid_model_answer');if(!answer)answer=null;}
        if(!Number.isInteger(q.points)||q.points<0||q.points>LIMITS.points)refuse('invalid_points');
        textTotal+=prompt.length+(answer?answer.length:0);
        return {id,prompt,answer,points:q.points};
    });
    if(textTotal>LIMITS.questionText)refuse('too_long');
    return {title,note,targets,openAt,dueAt,minutes,questions};
}
// 生徒の答え：問題のidだけ・1問4000字・合計20000字。空の答えは持たない
function cleanAnswers(raw,assignment){
    if(!isObj(raw))refuse('invalid_answers');
    const qids=new Set(assignment.questions.map(q=>q.id)),out={};let total=0;
    for(const [k,v] of Object.entries(raw)){
        if(!qids.has(k))refuse('invalid_answers');
        const s=text(v,LIMITS.answer);if(s===null)refuse('invalid_answers');
        if(!s.trim())continue;
        total+=s.length;out[k]=s;
    }
    if(total>LIMITS.answersTotal)refuse('too_long');
    return sortKeys(out,assignment);
}
const sortKeys=(map,assignment)=>Object.fromEntries(assignment.questions.filter(q=>map[q.id]!==undefined).map(q=>[q.id,map[q.id]]));
const sameMap=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
const totalPoints=a=>a.questions.reduce((s,q)=>s+q.points,0);
const deadlineOf=(a,w)=>a.minutes&&w&&w.startedAt?Math.min(a.dueAt,w.startedAt+a.minutes*60000):a.dueAt;
const statusOf=w=>w&&w.review&&w.review.returnedAt?'返却済み':w&&w.submission?'提出済み':'未提出';
function studentView(a,w,now){
    const submitted=!!(w&&w.submission),returned=!!(w&&w.review&&w.review.returnedAt),deadline=deadlineOf(a,w);
    const needsStart=!!(a.minutes&&!(w&&w.startedAt)&&!submitted);
    return {id:a.id,title:a.title,note:a.note,openAt:a.openAt,dueAt:a.dueAt,minutes:a.minutes,startedAt:w&&w.startedAt||null,deadline,needsStart,
        questionCount:a.questions.length,totalPoints:totalPoints(a),
        // 時間制限つきは「始める」まで問題を見せない。見本の答え（answer）はどの場合も入れない
        questions:needsStart?[]:a.questions.map(q=>({id:q.id,prompt:q.prompt,points:q.points})),
        status:statusOf(w),closed:!submitted&&now>deadline,
        draft:!submitted&&w&&w.draft?{answers:w.draft.answers,at:w.draft.at}:null,
        submission:submitted?{answers:w.submission.answers,at:w.submission.at}:null,
        review:returned?{comments:w.review.comments,explanations:w.review.explanations||{},overall:w.review.overall,score:w.review.score,returnedAt:w.review.returnedAt}:null};
}
function adminWork(a,w){
    return {status:statusOf(w),startedAt:w&&w.startedAt||null,deadline:deadlineOf(a,w),
        submission:w&&w.submission?{answers:w.submission.answers,at:w.submission.at}:null,
        review:w&&w.review?{comments:w.review.comments,explanations:w.review.explanations||{},overall:w.review.overall,score:w.review.score,savedAt:w.review.savedAt,returnedAt:w.review.returnedAt||null}:null};
}
async function loadAssignment(db,id){
    if(!validId(id))refuse('invalid_body');
    const row=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(A_PREFIX+id).first();
    if(!row)refuse('not_found',404);
    return JSON.parse(row.v);
}
const activity=(db,actor,record,now,guardKey,guardValue)=>{
    const key='activity:'+actor+':'+String(now).padStart(15,'0')+':'+randHex(6),value=JSON.stringify(record);
    // guard があるときは「本体の書きこみが本当に入ったとき」だけ記録する（同じ1取引の中で確かめる）
    return guardKey?db.prepare('INSERT INTO auth_kv(k,v,expires_at) SELECT ?,?,? WHERE EXISTS(SELECT 1 FROM auth_kv WHERE k=? AND v=?)').bind(key,value,now+3650*86400000,guardKey,guardValue)
        :db.prepare('INSERT INTO auth_kv(k,v,expires_at) VALUES(?,?,?)').bind(key,value,now+3650*86400000);
};
// 提出物の行を「読んだときと同じなら書く」で更新する（2台から同時に押されても上書きし合わない）
async function changeWork(db,key,make,logOf){
    for(let attempt=0;attempt<3;attempt++){
        const row=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(key).first();
        const current=row?JSON.parse(row.v):null,out=make(current);
        if(out.unchanged)return out;
        const value=JSON.stringify(out.value);
        const write=row?db.prepare('UPDATE auth_kv SET v=? WHERE k=? AND v=?').bind(value,key,row.v)
            :db.prepare('INSERT INTO auth_kv(k,v,expires_at) VALUES(?,?,0) ON CONFLICT(k) DO NOTHING').bind(key,value);
        const log=logOf&&logOf(out);let changed;
        if(log){const results=await db.batch([write,log(key,value)]);changed=Number(results[0]&&results[0].meta&&results[0].meta.changes);}
        else changed=Number((await write.run()).meta.changes);
        if(changed===1)return out;
    }
    refuse('conflict',409);
}
const notifyFor=(kind,a,uid,now)=>kind==='submit'
    ?{uid:'u1',id:'assignment-submit:'+a.id+':'+uid,at:now,title:'提出がありました',body:NAMES[uid]+'の「'+a.title+'」の回答が終わりました。アドミン（管理）を開いて提出箱を確認してください。'}
    :{uid,id:'assignment-return:'+a.id+':'+uid,at:now,title:'返却されました',body:'「'+a.title+'」が返ってきました。見直してみよう。'};

export async function assignmentsRoute(request,env,session,helpers){
    if(!session||typeof session.uid!=='string'||!session.uid)return reply({error:'unauthorized'},401);
    const url=new URL(request.url);
    if(url.pathname!=='/assignments')return reply({error:'not_found'},404);
    if(url.search)return reply({error:'invalid_query'},400);
    const allowed=profilesFor(env).map(p=>p.uid),uid=session.uid,family=allowed.includes(uid),admin=uid==='u1';
    if(request.method==='GET'){
        if(!family)return reply({items:[],now:Date.now()});
        if(!env.AUTH_DB)return reply({error:'unavailable'},503);
        const db=env.AUTH_DB,now=Date.now();
        const all=((await db.prepare('SELECT v FROM auth_kv WHERE k>=? AND k<? LIMIT ?').bind(A_PREFIX,A_PREFIX+'\uffff',LIMITS.assignments+50).all()).results||[]).map(r=>JSON.parse(r.v)).sort((x,y)=>y.openAt-x.openAt||y.createdAt-x.createdAt);
        const works=new Map();
        const workRows=admin?(await db.prepare('SELECT k,v FROM auth_kv WHERE k>=? AND k<? LIMIT 2000').bind(W_PREFIX,W_PREFIX+'\uffff').all()).results||[]
            :(await db.prepare("SELECT k,v FROM auth_kv WHERE k>=? AND k<? AND json_extract(v,'$.uid')=? LIMIT 1000").bind(W_PREFIX,W_PREFIX+'\uffff',uid).all()).results||[];
        for(const r of workRows){const w=JSON.parse(r.v);if(r.k===W_PREFIX+w.id+':'+w.uid)works.set(r.k,w);}
        const mine=all.filter(a=>a.targets.includes(uid)&&a.openAt<=now).map(a=>studentView(a,works.get(W_PREFIX+a.id+':'+uid)||null,now));
        const out={items:mine,now};
        if(admin)out.admin={people:profilesFor(env),assignments:all.map(a=>({...a,totalPoints:totalPoints(a)})),submissions:Object.fromEntries(all.map(a=>[a.id,Object.fromEntries(a.targets.map(t=>[t,adminWork(a,works.get(W_PREFIX+a.id+':'+t)||null)]))]))};
        return reply(out);
    }
    if(request.method!=='POST')return reply({error:'method_not_allowed'},405);
    if(request.headers.get('Origin')!==env.APP_ORIGIN)return reply({error:'origin_rejected'},403);
    if(!(request.headers.get('Content-Type')||'').startsWith('application/json'))return reply({error:'bad_content_type'},415);
    if(!family)return reply({error:'family_only'},403);
    if(!env.AUTH_DB)return reply({error:'unavailable'},503);
    let body;try{body=await readBody(request,admin?BODY_LIMIT.create:BODY_LIMIT.other);}catch(e){return reply({error:'invalid_body'},400);}
    if(!isObj(body))return reply({error:'invalid_body'},400);
    const db=env.AUTH_DB,now=Date.now();
    try{
        if(body.action==='create'){
            if(!admin)refuse('admin_only',403);
            if(!keysOk(body,['action','assignment'],['action','assignment']))refuse('invalid_body');
            const clean=cleanAssignment(body.assignment,now,allowed);
            const count=Number(await db.prepare('SELECT COUNT(*) AS n FROM auth_kv WHERE k>=? AND k<?').bind(A_PREFIX,A_PREFIX+'\uffff').first('n'))||0;
            if(count>=LIMITS.assignments)refuse('too_many',409);
            const item={id:randHex(16),...clean,createdBy:uid,createdAt:now};
            await db.batch([db.prepare('INSERT INTO auth_kv(k,v,expires_at) VALUES(?,?,0)').bind(A_PREFIX+item.id,JSON.stringify(item)),activity(db,uid,{type:'assignment-create',id:item.id,at:now},now)]);
            return reply({ok:true,item:{...item,totalPoints:totalPoints(item)}},201);
        }
        if(body.action==='return'){
            if(!admin)refuse('admin_only',403);
            if(!keysOk(body,['action','id','uid','comments','explanations','complete','overall','score','final'],['action','id','uid','comments','overall','score']))refuse('invalid_body');
            if(body.final!==undefined&&body.final!==true)refuse('invalid_body');
            const a=await loadAssignment(db,body.id);
            if(!allowed.includes(body.uid)||!a.targets.includes(body.uid))refuse('not_found',404);
            if(!isObj(body.comments))refuse('invalid_comments');
            const qids=new Set(a.questions.map(q=>q.id)),comments={};
            for(const [k,v] of Object.entries(body.comments)){if(!qids.has(k))refuse('invalid_comments');const s=text(v,LIMITS.comment,{trim:true});if(s===null)refuse('invalid_comments');if(s)comments[k]=s;}
            const explanations={};if(body.explanations!==undefined){if(!isObj(body.explanations))refuse('invalid_comments');for(const [k,v] of Object.entries(body.explanations)){if(!qids.has(k))refuse('invalid_comments');const t=text(v,LIMITS.comment,{trim:true});if(t===null)refuse('invalid_comments');if(t)explanations[k]=t;}}
            if(body.complete!==undefined&&body.complete!==true)refuse('invalid_body');
            if(body.final&&body.complete&&a.questions.some(q=>!comments[q.id]||!explanations[q.id]))refuse('incomplete_review');
            const overall=text(body.overall,LIMITS.overall,{trim:true});if(overall===null)refuse('invalid_overall');
            const max=Math.max(totalPoints(a),0);
            if(body.score!==null&&!(Number.isInteger(body.score)&&body.score>=0&&body.score<=max))refuse('invalid_score');
            const review={comments:sortKeys(comments,a),explanations:sortKeys(explanations,a),overall,score:body.score};
            const final=body.final===true,key=W_PREFIX+a.id+':'+body.uid;
            const out=await changeWork(db,key,w=>{
                if(!w||!w.submission)refuse('not_submitted',409);
                if(w.review&&w.review.returnedAt){
                    const old=w.review;
                    if(final&&sameMap([old.comments,old.explanations||{},old.overall,old.score],[review.comments,review.explanations,review.overall,review.score]))return {unchanged:true,value:w,repeat:true};
                    refuse('already_returned',409);
                }
                return {value:{...w,review:{...review,savedAt:now,returnedAt:final?now:null}}};
            },final?()=>(k,v)=>activity(db,uid,{type:'assignment-return',id:a.id,student:body.uid,at:now},now,k,v):null);
            const res={ok:true,returned:!!out.value.review.returnedAt,review:adminWork(a,out.value).review};
            if(out.repeat)res.repeat=true;else if(final)res.notify=notifyFor('return',a,body.uid,now);
            return reply(res);
        }
        if(['start','draft','submit'].includes(body.action)){
            const allowed=body.action==='start'?['action','id']:['action','id','answers'];
            if(!keysOk(body,allowed,allowed))refuse('invalid_body');
            const a=await loadAssignment(db,body.id);
            if(!a.targets.includes(uid)||a.openAt>now)refuse('not_found',404);// 自分あてでない・まだ配られていないものは「ない」と同じ
            const key=W_PREFIX+a.id+':'+uid;
            if(body.action==='start'){
                const out=await changeWork(db,key,w=>{
                    if(w&&(w.startedAt||w.submission))return {unchanged:true,value:w};
                    if(now>=a.dueAt)refuse('closed',409);
                    return {value:{id:a.id,uid,...(w||{}),startedAt:now}};
                });
                return reply({ok:true,item:studentView(a,out.value,now)});
            }
            const answers=cleanAnswers(body.answers,a);
            if(body.action==='draft'){
                const minute=Math.floor(now/60000),rateKey='assignment-rate:'+uid+':'+minute;
                const allowedRate=await db.prepare("INSERT INTO auth_kv(k,v,expires_at) VALUES(?,'1',?) ON CONFLICT(k) DO UPDATE SET v=CAST(CAST(v AS INTEGER)+1 AS TEXT) WHERE CAST(v AS INTEGER)<? RETURNING v").bind(rateKey,now+120000,LIMITS.draftsPerMinute).first();
                if(!allowedRate)refuse('rate_limited',429);
                const out=await changeWork(db,key,w=>{
                    if(w&&w.submission)refuse('already_submitted',409);
                    if(a.minutes&&!(w&&w.startedAt))refuse('not_started',409);
                    if(now>deadlineOf(a,w))refuse('closed',409);
                    return {value:{id:a.id,uid,...(w||{}),draft:{answers,at:now}}};
                });
                return reply({ok:true,savedAt:out.value.draft.at});
            }
            // submit：1回だけ。同じ中身の送り直しは同じ結果を返す（通知はもう出さない）
            const out=await changeWork(db,key,w=>{
                if(w&&w.submission){if(sameMap(w.submission.answers,answers))return {unchanged:true,value:w,repeat:true};refuse('already_submitted',409);}
                if(a.minutes&&!(w&&w.startedAt))refuse('not_started',409);
                if(now>deadlineOf(a,w))refuse('closed',409);
                const next={id:a.id,uid,...(w||{}),submission:{answers,at:now}};delete next.draft;
                return {value:next};
            },()=>(k,v)=>activity(db,uid,{type:'assignment-submit',id:a.id,at:now},now,k,v));
            const res={ok:true,item:studentView(a,out.value,now)};
            if(out.repeat)res.repeat=true;else res.notify=notifyFor('submit',a,uid,now);
            return reply(res);
        }
        return reply({error:'invalid_action'},400);
    }catch(e){
        if(e instanceof Refuse)return reply({error:e.code},e.status);
        throw e;
    }
}
