const reply=(body,status=200)=>Response.json(body,{status,headers:{'Cache-Control':'no-store'}});
const validId=id=>typeof id==='string'&&/^[a-f0-9]{32}$/.test(id);
function cleanEntry(entry){
    if(!entry||Object.keys(entry).some(k=>!['kind','title','score','date'].includes(k)))return null;
    const title=String(entry.title||'').trim(),date=String(entry.date||'');
    if(!title||title.length>100||/[<>\x00-\x1f]/.test(title)||!/^\d{4}-\d{2}-\d{2}$/.test(date))return null;
    const timestamp=Date.parse(date+'T00:00:00Z');
    if(!Number.isFinite(timestamp)||new Date(timestamp).toISOString().slice(0,10)!==date)return null;
    if(entry.kind==='qualification'&&entry.score===undefined)return {kind:entry.kind,title,date};
    if(entry.kind==='test'&&Number.isInteger(entry.score)&&entry.score>=90&&entry.score<=100)return {kind:entry.kind,title,date,score:entry.score};
    return null;
}
async function readBody(request){
    if(!request.body||Number(request.headers.get('Content-Length'))>2048)throw new Error('body');
    const reader=request.body.getReader();let total=0;const parts=[];
    try{while(true){const {done,value}=await reader.read();if(done)break;total+=value.length;if(total>2048){await reader.cancel();throw new Error('body');}parts.push(value);}}finally{reader.releaseLock();}
    const bytes=new Uint8Array(total);let offset=0;for(const part of parts){bytes.set(part,offset);offset+=part.length;}
    return JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes));
}
export async function achievementsRoute(request,env,session){
    if(!session||!['u1','u2'].includes(session.uid))return reply({error:'unauthorized'},401);
    if(!env.AUTH_DB)return reply({error:'unavailable'},503);
    if(request.method==='GET'){
        const own=(await env.AUTH_DB.prepare("SELECT v FROM auth_kv WHERE k>=? AND k<? AND json_extract(v,'$.uid')=? ORDER BY json_extract(v,'$.at') DESC LIMIT 200").bind('achievement:','achievement:\uffff',session.uid).all()).results||[];
        const pending=session.uid==='u1'?(await env.AUTH_DB.prepare("SELECT v FROM auth_kv WHERE k>=? AND k<? AND json_extract(v,'$.status')='pending' ORDER BY json_extract(v,'$.at') LIMIT 200").bind('achievement:','achievement:\uffff').all()).results||[]:[];
        return reply({items:own.map(r=>JSON.parse(r.v)),pending:pending.map(r=>JSON.parse(r.v)),canApprove:session.uid==='u1'});
    }
    if(request.method!=='POST')return reply({error:'method_not_allowed'},405);
    if(request.headers.get('Origin')!==env.APP_ORIGIN)return reply({error:'origin_rejected'},403);
    if(!request.headers.get('Content-Type')?.startsWith('application/json'))return reply({error:'bad_content_type'},415);
    let body;try{body=await readBody(request);}catch(e){return reply({error:'invalid_body'},400);}
    if(!body||typeof body!=='object'||Array.isArray(body))return reply({error:'invalid_body'},400);
    if(body.action==='request'){
        if(Object.keys(body).sort().join(',')!=='action,entry')return reply({error:'invalid_body'},400);
        const entry=cleanEntry(body.entry);if(!entry)return reply({error:'invalid_entry'},400);
        const now=Date.now(),rateKey='achievement-rate:'+session.uid+':'+Math.floor(now/86400000);
        const allowed=await env.AUTH_DB.prepare("INSERT INTO auth_kv(k,v,expires_at) VALUES(?,'1',?) ON CONFLICT(k) DO UPDATE SET v=CAST(CAST(v AS INTEGER)+1 AS TEXT) WHERE CAST(v AS INTEGER)<10 RETURNING v").bind(rateKey,now+2*86400000).first();
        if(!allowed)return reply({error:'rate_limited'},429);
        const id=Array.from(crypto.getRandomValues(new Uint8Array(16)),n=>n.toString(16).padStart(2,'0')).join('');
        const item={id,uid:session.uid,entry,status:'pending',at:now};
        await env.AUTH_DB.prepare('INSERT INTO auth_kv(k,v,expires_at) VALUES(?,?,0)').bind('achievement:'+id,JSON.stringify(item)).run();
        return reply({item},201);
    }
    if(['approve','reject'].includes(body.action)){
        if(session.uid!=='u1')return reply({error:'approval_required'},403);
        if(Object.keys(body).sort().join(',')!=='action,id'||!validId(body.id))return reply({error:'invalid_body'},400);
        const key='achievement:'+body.id,row=await env.AUTH_DB.prepare('SELECT v FROM auth_kv WHERE k=?').bind(key).first();
        if(!row)return reply({error:'not_found'},404);
        const item=JSON.parse(row.v);
        if(item.status!=='pending')return reply({error:'already_reviewed'},409);
        const reviewed={...item,status:body.action==='approve'?'approved':'rejected',reviewedBy:'u1',reviewedAt:Date.now()};
        const changed=await env.AUTH_DB.prepare("UPDATE auth_kv SET v=? WHERE k=? AND json_extract(v,'$.status')='pending' RETURNING k").bind(JSON.stringify(reviewed),key).first();
        return changed?reply({item:reviewed}):reply({error:'already_reviewed'},409);
    }
    return reply({error:'invalid_action'},400);
}
