// Metadata only. Does not start an AI operation, consume credits, or write learning records.
import {textbookAccessOn} from './textbook-access.mjs';
import {readPublicTextbookContext} from './textbook-ai-context.mjs';
const reply=(value,status=200)=>Response.json(value,{status,headers:{'Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff'}});
export async function textbookAIContextRoute(request,env,session,{owner,now=()=>Date.now(),readContext=readPublicTextbookContext}={}){
 if(!textbookAccessOn(env))return reply({error:'not_found'},404);
 if(typeof session?.uid!=='string'||typeof owner!=='string'||!owner)return reply({error:'unauthorized'},401);
 const uid=session.uid;
 if(!/^(?:u[124]|p_(?:free|mini|standard|pro|unlimit))$/.test(uid)||(uid.startsWith('p_')&&env.PREVIEW_PLAN_ACCOUNTS!=='1'))return reply({error:'forbidden'},403);
 if(!env.AUTH_DB)return reply({error:'unavailable'},503);
 const url=new URL(request.url);
 if(url.pathname!=='/textbook-ai-context')return reply({error:'not_found'},404);
 if(request.method!=='GET')return reply({error:'method_not_allowed'},405);
 const origin=request.headers.get('Origin');
 if(origin!==null&&origin!==env.APP_ORIGIN)return reply({error:'origin'},403);
 const required=['book','anchor','annotationSignature'],allowed=[...required,'contextSha256'];
 if([...url.searchParams.keys()].some(k=>!allowed.includes(k))||required.some(k=>url.searchParams.getAll(k).length!==1)||url.searchParams.getAll('contextSha256').length>1)return reply({error:'invalid_query'},400);
 const selection=Object.fromEntries(url.searchParams);
 const active=async()=>!!await env.AUTH_DB.prepare('SELECT 1 AS x FROM auth_kv WHERE k=? AND v=? AND expires_at>?').bind('active-session:'+uid,owner,now()).first('x');
 try{
  if(!await active())return reply({error:'active_session'},409);
  const context=await readContext(env,selection);
  if(!await active())return reply({error:'active_session'},409);
  return reply({context});
 }catch(error){
  const code=error?.message;
  if(code==='invalid_context')return reply({error:'invalid_query'},400);
  if(code==='context_changed')return reply({error:code},409);
  if(code==='context_not_found')return reply({error:code},404);
  return reply({error:'context_unavailable'},503);
 }
}
