import {createTestSession,testSessionStatus} from './ai-test-session.mjs';
const UUID=/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/;
const reply=(body,status=200)=>Response.json(body,{status,headers:{'Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff'}});
async function readBody(request){
 if(!/^application\/json(?:\s*;|$)/i.test(request.headers.get('Content-Type')||'')||!request.body)throw Error('invalid_body');
 const reader=request.body.getReader(),parts=[];let size=0;
 try{for(;;){const part=await reader.read();if(part.done)break;size+=part.value.byteLength;if(size>90000){await reader.cancel();throw Error('invalid_body');}parts.push(part.value);}}finally{reader.releaseLock();}
 const bytes=new Uint8Array(size);let at=0;for(const part of parts){bytes.set(part,at);at+=part.byteLength;}
 return JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes));
}
// Parent must supply an authenticated session and its opaque active-owner value.
// This endpoint reserves question/first-attempt IDs only; it neither starts study,
// grades answers nor consumes credits. Paid AI admission is separate.
export async function testSessionRoute(request,env,session,{owner,now=()=>Date.now(),readUnit}={}){
 const url=new URL(request.url),uid=session?.uid;
 if(url.pathname!=='/material-test-session')return reply({error:'not_found'},404);
 if(!['GET','POST'].includes(request.method))return reply({error:'method_not_allowed'},405);
 if(typeof uid!=='string'||typeof owner!=='string'||!owner)return reply({error:'unauthorized'},401);
 if(!/^(?:u[124]|p_(?:free|mini|standard|pro|unlimit))$/.test(uid)||(uid.startsWith('p_')&&env.PREVIEW_PLAN_ACCOUNTS!=='1'))return reply({error:'forbidden'},403);
 const origin=request.headers.get('Origin');
 if((request.method==='POST'||origin!==null)&&origin!==env.APP_ORIGIN)return reply({error:'origin'},403);
 if(!env.AUTH_DB)return reply({error:'unavailable'},503);
 try{
  if(request.method==='GET'){
   if([...url.searchParams.keys()].some(k=>k!=='id')||url.searchParams.getAll('id').length!==1||!UUID.test(url.searchParams.get('id')||''))return reply({error:'invalid_query'},400);
   return reply(await testSessionStatus(env,uid,url.searchParams.get('id'),{owner,now:now()}));
  }
  if(url.search)return reply({error:'invalid_query'},400);
  let body;try{body=await readBody(request);}catch{return reply({error:'invalid_body'},400);}
  return reply(await createTestSession(env,uid,body,{owner,now:now(),...(readUnit?{readUnit}:{})}));
 }catch(error){
  const code=error?.message;
  if(code==='session_changed')return reply({error:'active_session'},409);
  if(code==='id_conflict')return reply({error:code},409);
  if(code==='test_session_not_found'||code==='unknown_test_unit')return reply({error:'not_found'},404);
  if(['invalid_test_request','invalid_test_count','unknown_test_question','incomplete_kentei_selection','test_source_too_large'].includes(code))return reply({error:'invalid_test_request'},400);
  if(code==='test_session_limit')return reply({error:code},429);
  return reply({error:'test_session_unavailable'},503);
 }
}
