// Owned, immutable test rosters. No grading, AI request, plan change or credit use here.
import bank from './material-bank.mjs';
import engine from './material-engine.cjs';
const UID=/^(?:u[124]|p_(?:free|mini|standard|pro|unlimit))$/,ID=/^[a-zA-Z0-9_-]{8,64}$/;
const UUID=/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/;
const HASH=/^[a-f0-9]{64}$/,DAY=86400000,JST=32400000;
const activeSql='EXISTS(SELECT 1 FROM auth_kv WHERE k=? AND v=? AND expires_at>?)';
const equal=(a,b)=>JSON.stringify(a)===JSON.stringify(b),copy=x=>JSON.parse(JSON.stringify(x));
const digest=async x=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(x))),x=>x.toString(16).padStart(2,'0')).join('');
const fail=code=>{throw Error(code);},validQid=x=>typeof x==='string'&&!!x.trim()&&x.length<=160&&!/[\x00-\x1f\x7f<>]/.test(x);
const verifiedUnits=new Map();
function canonicalUnit(id){
 if(verifiedUnits.has(id))return verifiedUnits.get(id);
 const unit=bank.units.find(u=>u.id===id&&u.status==='ready'&&u.subject!=='保健体育');
 if(!unit||engine.validateUnit(unit,{sources:bank.sources}).length)return null;
 verifiedUnits.set(id,unit);return unit;
}
function identity(env,uid,owner,now){
 if(!env.AUTH_DB||!UID.test(uid)||(uid.startsWith('p_')&&env.PREVIEW_PLAN_ACCOUNTS!=='1')||typeof owner!=='string'||!owner||!Number.isSafeInteger(now)||now<0)fail('invalid_test_identity');
 const began=performance.now();return {db:env.AUTH_DB,args:()=>['active-session:'+uid,owner,now+Math.ceil(performance.now()-began)]};
}
const active=async(db,args)=>!!await db.prepare('SELECT 1 AS x FROM auth_kv WHERE k=? AND v=? AND expires_at>?').bind(...args()).first('x');
const sessionKey=(uid,id)=>{if(!UID.test(uid)||!UUID.test(id))fail('invalid_test_session');return 'ai-test-session:'+uid+':'+id;};
export function testSessionRequest(body){
 if(!body||Object.keys(body).sort().join(',')!=='id,mode,questionIds,unitId'||!ID.test(body.id)||typeof body.id!=='string'||!validQid(body.unitId)||!['study','test'].includes(body.mode)||!Array.isArray(body.questionIds)||body.questionIds.length<1||body.questionIds.length>500||body.questionIds.some(x=>!validQid(x))||new Set(body.questionIds).size!==body.questionIds.length)fail('invalid_test_request');
 return {id:body.id,unitId:body.unitId,mode:body.mode,questionIds:[...body.questionIds]};
}
async function storedSession(db,uid,id){
 const raw=await db.prepare('SELECT v FROM auth_kv WHERE k=? AND expires_at=0').bind(sessionKey(uid,id)).first('v');
 if(!raw)return null;if(new TextEncoder().encode(raw).length>1000000)fail('invalid_test_session');
 let row;try{row=JSON.parse(raw);}catch{fail('invalid_test_session');}
 if(!row||Object.keys(row).sort().join(',')!=='at,fingerprint,id,mode,questions,requestId,rosterSha256,sourceSha256,uid,unitId,version'||row.version!==1||row.uid!==uid||row.id!==id||!ID.test(row.requestId)||!HASH.test(row.fingerprint)||!HASH.test(row.sourceSha256)||!HASH.test(row.rosterSha256)||!validQid(row.unitId)||!['study','test'].includes(row.mode)||!Number.isSafeInteger(row.at)||row.at<0||!Array.isArray(row.questions)||row.questions.length<1||row.questions.length>500)fail('invalid_test_session');
 const qids=new Set(),slots=new Set();for(const slot of row.questions){
  if(!slot||Object.keys(slot).sort().join(',')!=='attemptId,question'||!UUID.test(slot.attemptId)||slots.has(slot.attemptId)||!slot.question||!validQid(slot.question.id)||qids.has(slot.question.id)||typeof slot.question.prompt!=='string'||!slot.question.prompt.trim()||!slot.question.answer||typeof slot.question.answer!=='object')fail('invalid_test_session');
  qids.add(slot.question.id);slots.add(slot.attemptId);
 }
 const request={id:row.requestId,unitId:row.unitId,mode:row.mode,questionIds:row.questions.map(s=>s.question.id)};
 if(row.fingerprint!==await digest(JSON.stringify(request))||row.sourceSha256!==await digest(JSON.stringify(row.questions.map(s=>s.question)))||row.rosterSha256!==await digest(JSON.stringify(row.questions)))fail('invalid_test_session');
 return {row,raw};
}
function publicSession(row){return {id:row.id,unitId:row.unitId,mode:row.mode,at:row.at,total:row.questions.length,slots:row.questions.map(s=>({questionId:s.question.id,attemptId:s.attemptId}))};}
export async function createTestSession(env,uid,body,{owner,now=Date.now(),readUnit=canonicalUnit}={}){
 const {db,args}=identity(env,uid,owner,now),request=testSessionRequest(body),fingerprint=await digest(JSON.stringify(request)),requestKey='ai-test-session-request:'+uid+':'+request.id;
 if(!await active(db,args))fail('session_changed');
 const existing=await db.prepare('SELECT v FROM auth_kv WHERE k=? AND expires_at=0').bind(requestKey).first('v');
 if(existing){const saved=await storedSession(db,uid,existing);if(!saved||saved.row.fingerprint!==fingerprint)fail('id_conflict');if(!await active(db,args))fail('session_changed');return {...publicSession(saved.row),cached:true};}
 const unit=await readUnit(request.unitId);
 if(!unit||unit.id!==request.unitId||unit.status!=='ready')fail('unknown_test_unit');
 const pool=request.mode==='test'?unit.tests:unit.questions;if(!Array.isArray(pool))fail('unknown_test_unit');
 const flags=(await db.prepare("SELECT k,json_extract(v,'$.paused') AS paused FROM auth_kv WHERE k>=? AND k<?").bind('qflag:'+unit.id+':','qflag:'+unit.id+':\uffff').all()).results||[];
 const paused=new Set(flags.filter(f=>f.paused===1).map(f=>f.k.slice(('qflag:'+unit.id+':').length)));
 const available=pool.filter(q=>!paused.has(q.id)),chosen=request.questionIds.map(id=>available.find(q=>q.id===id));
 if(chosen.some(q=>!q))fail('unknown_test_question');
 if(unit.mode==='kentei'){
  if(!equal(request.questionIds,available.map(q=>q.id)))fail('incomplete_kentei_selection');
 }else if(![5,10,15,30,45,60].includes(chosen.length))fail('invalid_test_count');
 const questions=chosen.map(q=>({question:copy(q),attemptId:crypto.randomUUID()}));
 const row={version:1,id:crypto.randomUUID(),uid,requestId:request.id,unitId:request.unitId,mode:request.mode,at:now,fingerprint,sourceSha256:await digest(JSON.stringify(chosen)),rosterSha256:await digest(JSON.stringify(questions)),questions};
 const raw=JSON.stringify(row);if(new TextEncoder().encode(raw).length>1000000)fail('test_source_too_large');
 const prefix='ai-test-session:'+uid+':',key=sessionKey(uid,row.id),day=Math.floor((now+JST)/DAY)*DAY-JST;
 await db.batch([
  db.prepare('INSERT INTO auth_kv(k,v,expires_at) SELECT ?,?,0 WHERE '+activeSql+' AND NOT EXISTS(SELECT 1 FROM auth_kv WHERE k=?) AND (SELECT COUNT(*) FROM auth_kv WHERE k>=? AND k<? AND json_extract(v,\'$.at\')>=? AND json_extract(v,\'$.at\')<?)<50 ON CONFLICT(k) DO NOTHING').bind(key,raw,...args(),requestKey,prefix,prefix+'\uffff',day,day+DAY),
  db.prepare('INSERT INTO auth_kv(k,v,expires_at) SELECT ?,?,0 WHERE EXISTS(SELECT 1 FROM auth_kv WHERE k=? AND v=?) ON CONFLICT(k) DO NOTHING').bind(requestKey,row.id,key,raw)
 ]);
 if(!await active(db,args))fail('session_changed');
 const winner=await db.prepare('SELECT v FROM auth_kv WHERE k=? AND expires_at=0').bind(requestKey).first('v');
 if(!winner)fail('test_session_limit');
 const saved=await storedSession(db,uid,winner);if(!saved||saved.row.fingerprint!==fingerprint)fail('id_conflict');
 return {...publicSession(saved.row),cached:saved.row.id!==row.id};
}
function matchesRecord(row,record){
 const slot=row.questions.find(s=>s.attemptId===record.id);
 return !!slot&&record.unitId===row.unitId&&record.mode===row.mode&&record.questionId===slot.question.id&&Number.isSafeInteger(record.at)&&record.at>=row.at&&typeof record.answer==='string'&&!!record.answer.trim()&&record.answer.length<=4000;
}
async function sessionStatus(db,uid,saved,args){
 const slots=saved.row.questions.map(s=>({attemptId:s.attemptId}));
 // Metadata projection only: no learner text, hidden answers or notes are returned/read for status.
 const records=(await db.prepare("SELECT json_extract(a.v,'$.id') AS id,json_extract(a.v,'$.unitId') AS unitId,json_extract(a.v,'$.mode') AS mode,json_extract(a.v,'$.questionId') AS questionId,json_extract(a.v,'$.at') AS at,length(trim(json_extract(a.v,'$.answer'))) AS answerLength FROM json_each(?) s JOIN auth_kv a ON a.k=?||json_extract(s.value,'$.attemptId') WHERE "+activeSql).bind(JSON.stringify(slots),'material-attempt:'+uid+':',...args()).all()).results||[];
 let answered=0;for(const r of records){const slot=saved.row.questions.find(s=>s.attemptId===r.id);if(slot&&r.unitId===saved.row.unitId&&r.mode===saved.row.mode&&r.questionId===slot.question.id&&Number.isSafeInteger(r.at)&&r.at>=saved.row.at&&Number.isSafeInteger(r.answerLength)&&r.answerLength>0&&r.answerLength<=4000)answered++;}
 return {id:saved.row.id,unitId:saved.row.unitId,mode:saved.row.mode,at:saved.row.at,total:slots.length,answered,complete:answered===slots.length};
}
export async function testSessionStatus(env,uid,id,{owner,now=Date.now()}={}){
 const {db,args}=identity(env,uid,owner,now);if(!await active(db,args))fail('session_changed');
 const saved=await storedSession(db,uid,id);if(!saved)fail('test_session_not_found');
 const result=await sessionStatus(db,uid,saved,args);if(!await active(db,args))fail('session_changed');return result;
}
const proofs=new WeakMap();
class CompletedTest{
 constructor(data){proofs.set(this,data);this.id=data.session.id;this.uid=data.session.uid;this.total=data.session.questions.length;this.fingerprint=data.fingerprint;Object.freeze(this);}
}
export function completedTestData(proof,uid){const data=proofs.get(proof);if(!data||data.session.uid!==uid)fail('completed_test_required');return copy(data);}
export async function readCompletedTest(env,uid,id,{owner,now=Date.now()}={}){
 const {db,args}=identity(env,uid,owner,now);if(!await active(db,args))fail('session_changed');
 const saved=await storedSession(db,uid,id);if(!saved)fail('test_session_not_found');
 const status=await sessionStatus(db,uid,saved,args);if(!status.complete)fail('test_incomplete');
 const rows=(await db.prepare('SELECT a.v FROM json_each(?) s JOIN auth_kv a ON a.k=?||json_extract(s.value,\'$.attemptId\') WHERE '+activeSql).bind(JSON.stringify(saved.row.questions.map(s=>({attemptId:s.attemptId}))),'material-attempt:'+uid+':',...args()).all()).results||[];
 const records=[];for(const slot of saved.row.questions){
  const raw=rows.find(r=>{try{return JSON.parse(r.v).id===slot.attemptId;}catch{return false;}})?.v;if(!raw||raw.length>65536)fail('invalid_test_record');
  const record=JSON.parse(raw);
  if(!matchesRecord(saved.row,record)||record.prompt!==slot.question.prompt||!equal(record.expected,slot.question.answer)||typeof record.result?.correct!=='boolean')fail('test_source_changed');
  records.push(record);
 }
 if(!await active(db,args))fail('session_changed');
 return new CompletedTest({session:saved.row,records,fingerprint:await digest(saved.raw+'\n'+JSON.stringify(records))});
}
