// 個人ノート/相談の画像。入力は画素だけ、保存するPNGは固定構造で作り直す。
import {planAllows,subscriptionOn} from './plans.mjs';
const MAX=400*1024,MAX_BODY=560*1024,UID=/^(u[12]|p_(free|mini|standard|pro|unlimit))$/,ID=/^[a-f0-9]{64}$/;
const headers={'Cache-Control':'no-store','X-Content-Type-Options':'nosniff','Referrer-Policy':'no-referrer'};
const reply=(data,status=200)=>Response.json(data,{status,headers});
async function bounded(stream,max){const parts=[];let n=0;const reader=stream.getReader();try{while(true){const r=await reader.read();if(r.done)break;n+=r.value.length;if(n>max){await reader.cancel();throw Error('limit');}parts.push(r.value);}}finally{reader.releaseLock();}const out=new Uint8Array(n);let at=0;for(const p of parts){out.set(p,at);at+=p.length;}return out;}
function crc(bytes){let n=0xffffffff;for(const b of bytes){n^=b;for(let i=0;i<8;i++)n=(n>>>1)^((n&1)?0xedb88320:0);}return (n^0xffffffff)>>>0;}
function chunk(name,data){const out=new Uint8Array(data.length+12),v=new DataView(out.buffer);v.setUint32(0,data.length);out.set(new TextEncoder().encode(name),4);out.set(data,8);v.setUint32(out.length-4,crc(out.subarray(4,out.length-4)));return out;}
const b64=bytes=>{let s='';for(let i=0;i<bytes.length;i+=8192)s+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(s);};
export async function canonicalImage(body){
 if(!body||Array.isArray(body)||Object.keys(body).sort().join(',')!=='data,height,width')throw Error('shape');
 const {width,height,data}=body;
 if(!Number.isSafeInteger(width)||!Number.isSafeInteger(height)||width<1||height<1||width>1024||height>1024||typeof data!=='string'||!data.length||data.length>MAX_BODY||data.length%4||!/^[A-Za-z0-9+/]*={0,2}$/.test(data))throw Error('image');
 const packed=Uint8Array.from(atob(data),x=>x.charCodeAt(0));if(packed.length>MAX)throw Error('limit');
 const count=width*height*4,pixels=await bounded(new Blob([packed]).stream().pipeThrough(new DecompressionStream('deflate')),count);if(pixels.length!==count)throw Error('pixels');
 const rows=new Uint8Array(count+height);for(let y=0;y<height;y++)rows.set(pixels.subarray(y*width*4,(y+1)*width*4),y*(width*4+1)+1);
 const compressed=await bounded(new Blob([rows]).stream().pipeThrough(new CompressionStream('deflate')),MAX-57);
 const ihdr=new Uint8Array(13),dv=new DataView(ihdr.buffer);dv.setUint32(0,width);dv.setUint32(4,height);ihdr[8]=8;ihdr[9]=6;
 const blocks=[new Uint8Array([137,80,78,71,13,10,26,10]),chunk('IHDR',ihdr),chunk('IDAT',compressed),chunk('IEND',new Uint8Array())];
 const png=new Uint8Array(blocks.reduce((n,x)=>n+x.length,0));let at=0;for(const b of blocks){png.set(b,at);at+=b.length;}
 // 圧縮器の更新でも同じ画素は同じID。幅・高さも識別に含める。
 const identity=new Uint8Array(ihdr.length+pixels.length);identity.set(ihdr);identity.set(pixels,ihdr.length);
 const id=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',identity)),b=>b.toString(16).padStart(2,'0')).join('');
 return {id,width,height,bytes:png.length,png:b64(png)};
}
export async function ownImages(db,uid,ids){
 if(!Array.isArray(ids)||ids.length>3||new Set(ids).size!==ids.length||ids.some(id=>typeof id!=='string'||!ID.test(id)))return false;
 for(const id of ids)if(!await db.prepare('SELECT 1 x FROM auth_kv WHERE k=?').bind('learning-image:'+uid+':'+id).first('x'))return false;
 return true;
}
export async function learningImagesRoute(request,env,session){
 if(!subscriptionOn(env))return reply({error:'not_found'},404);
 const uid=session?.uid;if(typeof uid!=='string'||!UID.test(uid))return reply({error:'unauthorized'},401);
 const db=env.AUTH_DB;if(!db)return reply({error:'unavailable'},503);const url=new URL(request.url),prefix='learning-image:'+uid+':';
 if(url.pathname==='/learning-image'){
  if(request.method!=='GET')return reply({error:'method_not_allowed'},405);
  if([...url.searchParams.keys()].some(k=>k!=='id')||url.searchParams.getAll('id').length!==1||!ID.test(url.searchParams.get('id')||''))return reply({error:'invalid_query'},400);
  const raw=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(prefix+url.searchParams.get('id')).first('v');if(!raw)return reply({error:'not_found'},404);
  const image=JSON.parse(raw);return new Response(Uint8Array.from(atob(image.png),x=>x.charCodeAt(0)),{headers:{...headers,'Content-Type':'image/png','Content-Disposition':'inline; filename="nobilog-image.png"'}});
 }
 if(url.pathname!=='/learning-images'||url.search)return reply({error:'invalid_query'},400);
 if(request.method!=='POST')return reply({error:'method_not_allowed'},405);
 if(!env.APP_ORIGIN||request.headers.get('Origin')!==env.APP_ORIGIN)return reply({error:'origin'},403);
 if(!await planAllows(env,uid,'notes'))return reply({error:'plan_required'},403);
 if(!/^application\/json\b/.test(request.headers.get('Content-Type')||''))return reply({error:'content_type'},415);
 let image;try{const bytes=await bounded(request.body,MAX_BODY);image=await canonicalImage(JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes)));}catch(_){return reply({error:'invalid_image'},400);}
 const key=prefix+image.id;
 const stored=await db.prepare("INSERT INTO auth_kv(k,v,expires_at) SELECT ?,?,0 WHERE (SELECT COUNT(*) FROM auth_kv WHERE k>=? AND k<?)<300 ON CONFLICT(k) DO NOTHING RETURNING k").bind(key,JSON.stringify(image),prefix,prefix+'\uffff').first('k');
 if(!stored&&!await db.prepare('SELECT 1 x FROM auth_kv WHERE k=?').bind(key).first('x'))return reply({error:'image_limit'},409);
 const {png,...item}=image;return reply({item,cached:!stored});
}
