// 🖼 アイコン・のびログで撮った写真・UNLIMITのアイコン生成の受付（Claude・2026-10-12）
// - アイコン：だれでも自分のものだけ。サーバーに保存し、再ログイン・別の端末でも同じものを出す（/avatar・/avatar-image）
// - 写真：Standard 以上が「のびログのカメラ」で撮ったものだけ（/photos）。画像そのものは learning-images と同じ置き場所
//   learning-image:<uid>:<id> に入れるので、本人のノート・相談にそのまま添付できる。読めるのは本人だけ（キーにUIDが入る）
// - アイコン生成（UNLIMIT）：実Geminiは未接続（Codexと調整中）。生成したふりはせず、自己紹介も保存しない（/avatar-generate）
// UIDはセッションだけから決める。画素は canonicalImage で決まった形のPNGに作り直す（届いたファイルをそのまま保存しない）。
import {canonicalImage} from './learning-images.mjs';
import {planStatus,subscriptionOn} from './plans.mjs';
const headers={'Cache-Control':'no-store','X-Content-Type-Options':'nosniff','Referrer-Policy':'no-referrer'};
const reply=(data,status=200)=>Response.json(data,{status,headers});
const ID=/^[a-f0-9]{64}$/,MAX_BODY=560*1024,PHOTO_LIMIT=300,AVATAR_MAX=512;
export const PHOTO_PLANS=Object.freeze(['standard','pro','unlimit']);
async function body(request){
 if(!/^application\/json\b/.test(request.headers.get('Content-Type')||''))throw Object.assign(Error('type'),{status:415});
 if(!request.body||Number(request.headers.get('Content-Length'))>MAX_BODY)throw Object.assign(Error('size'),{status:400});
 const reader=request.body.getReader(),parts=[];let n=0;
 try{while(true){const r=await reader.read();if(r.done)break;n+=r.value.byteLength;if(n>MAX_BODY){await reader.cancel();throw Object.assign(Error('size'),{status:400});}parts.push(r.value);}}finally{reader.releaseLock();}
 const bytes=new Uint8Array(n);let at=0;for(const p of parts){bytes.set(p,at);at+=p.byteLength;}
 try{return JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes));}catch(_){throw Object.assign(Error('json'),{status:400});}
}
const originOk=(request,env)=>!!env.APP_ORIGIN&&request.headers.get('Origin')===env.APP_ORIGIN;
const png=raw=>new Response(Uint8Array.from(atob(raw),x=>x.charCodeAt(0)),{headers:{...headers,'Content-Type':'image/png','Content-Disposition':'inline; filename="nobilog-image.png"'}});
// プランの確認：読めないときは「使えない」とは言わず 503（勝手に Free 扱いにしない）
async function plan(env,uid){try{return await planStatus(env,uid,Date.now());}catch(_){return null;}}
export async function profilePhotosRoute(request,env,session,helpers={}){
 const uid=session?.uid;if(typeof uid!=='string'||!/^[A-Za-z0-9_-]{2,64}$/.test(uid))return reply({error:'unauthorized'},401);
 const db=env.AUTH_DB;if(!db)return reply({error:'unavailable'},503);
 const url=new URL(request.url),path=url.pathname;
 if(path==='/avatar-generations'||path==='/avatar-generate'&&env.OPENAI_AVATAR_READY==='1'){
  const {avatarRoute}=await import('./openai-avatar-route.mjs');
  return avatarRoute(request,env,session,helpers);
 }
 // ── アイコン ──
 if(path==='/avatar'){
  if(request.method==='GET'){
   if(url.search)return reply({error:'invalid_query'},400);
   const raw=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind('avatar:'+uid).first('v');
   if(!raw)return reply({avatar:null});const a=JSON.parse(raw);return reply({avatar:{id:a.id,rev:a.rev,at:a.at,width:a.width,height:a.height}});
  }
  if(request.method!=='POST')return reply({error:'method_not_allowed'},405);
  if(!originOk(request,env))return reply({error:'origin'},403);
  let b;try{b=await body(request);}catch(e){return reply({error:'invalid_body'},e.status||400);}
  if(!b||typeof b!=='object'||Array.isArray(b)||Object.keys(b).sort().join(',')!=='data,height,width'||b.width!==b.height||b.width>AVATAR_MAX)return reply({error:'invalid_image'},400);
  let image;try{image=await canonicalImage(b);}catch(_){return reply({error:'invalid_image'},400);}
  const old=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind('avatar:'+uid).first('v'),prev=old?JSON.parse(old):null;
  // 同じ画像をもう一度送っても（通信が切れて再試行したときなど）番号は増やさない
  if(prev&&prev.id===image.id)return reply({avatar:{id:prev.id,rev:prev.rev,at:prev.at,width:prev.width,height:prev.height},cached:true});
  const item={id:image.id,rev:(prev?.rev||0)+1,at:Date.now(),width:image.width,height:image.height,png:image.png};
  await db.prepare('INSERT INTO auth_kv(k,v,expires_at) VALUES(?,?,0) ON CONFLICT(k) DO UPDATE SET v=excluded.v').bind('avatar:'+uid,JSON.stringify(item)).run();
  return reply({avatar:{id:item.id,rev:item.rev,at:item.at,width:item.width,height:item.height},cached:false});
 }
 if(path==='/avatar-image'){
  if(request.method!=='GET')return reply({error:'method_not_allowed'},405);
  if([...url.searchParams.keys()].some(k=>k!=='rev'))return reply({error:'invalid_query'},400);
  const raw=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind('avatar:'+uid).first('v');
  return raw?png(JSON.parse(raw).png):reply({error:'not_found'},404);
 }
 // ── のびログで撮った写真（Standard 以上） ──
 if(path==='/photos'){
  if(!subscriptionOn(env))return reply({error:'not_found'},404);
  const st=await plan(env,uid);if(!st)return reply({error:'plan_unavailable'},503);
  const allowed=!!st.provisional&&PHOTO_PLANS.includes(st.plan),prefix='camera-photo:'+uid+':';
  if(request.method==='GET'){
   if(url.search)return reply({error:'invalid_query'},400);
   // 保存した写真の一覧は、プランが下がっても本人なら見られる（消さない）。新しく撮るのは Standard 以上だけ
   const rows=((await db.prepare('SELECT v FROM auth_kv WHERE k>=? AND k<? ORDER BY k DESC LIMIT ?').bind(prefix,prefix+'￿',PHOTO_LIMIT).all()).results||[]).map(r=>JSON.parse(r.v));
   return reply({items:rows,canTake:allowed,limit:PHOTO_LIMIT});
  }
  if(request.method!=='POST')return reply({error:'method_not_allowed'},405);
  if(!originOk(request,env))return reply({error:'origin'},403);
  if(!allowed)return reply({error:'plan_required'},403);
  let image;try{image=await canonicalImage(await body(request));}catch(e){return reply({error:'invalid_image'},e.status===415?415:400);}
  const imageKey='learning-image:'+uid+':'+image.id;
  // 同じ写真の再送は1枚のまま（画素が同じなら同じID）
  const existing=await db.prepare('SELECT v FROM auth_kv WHERE k>=? AND k<? AND json_extract(v,\'$.id\')=? LIMIT 1').bind(prefix,prefix+'￿',image.id).first('v');
  if(existing)return reply({item:JSON.parse(existing),cached:true});
  const now=Date.now(),item={id:image.id,at:now,width:image.width,height:image.height,bytes:image.bytes},hi=prefix+'\uffff';
  // 同じ写真が同時に2回届いても1行だけ・300枚の上限もこの1文の中で数える（あとから数えると同時の送信ですり抜ける）
  const added=await db.prepare("INSERT INTO auth_kv(k,v,expires_at) SELECT ?,?,0 WHERE NOT EXISTS (SELECT 1 FROM auth_kv WHERE k>=? AND k<? AND json_extract(v,'$.id')=?) AND (SELECT COUNT(*) FROM auth_kv WHERE k>=? AND k<?)<? ON CONFLICT(k) DO NOTHING RETURNING k").bind(prefix+String(now).padStart(15,'0')+':'+image.id.slice(0,12),JSON.stringify(item),prefix,hi,image.id,prefix,hi,PHOTO_LIMIT).first('k');
  if(!added){const again=await db.prepare("SELECT v FROM auth_kv WHERE k>=? AND k<? AND json_extract(v,'$.id')=? LIMIT 1").bind(prefix,hi,image.id).first('v');return again?reply({item:JSON.parse(again),cached:true}):reply({error:'photo_limit'},409);}
  await db.prepare('INSERT INTO auth_kv(k,v,expires_at) VALUES(?,?,0) ON CONFLICT(k) DO NOTHING').bind(imageKey,JSON.stringify(image)).run();
  return reply({item,cached:false},201);
 }
 // ── UNLIMIT のアイコン生成（受付だけ） ──
 if(path==='/avatar-generate'){
  if(!subscriptionOn(env))return reply({error:'not_found'},404);
  if(request.method!=='POST')return reply({error:'method_not_allowed'},405);
  if(!originOk(request,env))return reply({error:'origin'},403);
  const st=await plan(env,uid);if(!st)return reply({error:'plan_unavailable'},503);
  if(!st.provisional||st.plan!=='unlimit')return reply({error:'plan_required'},403);
  let b;try{b=await body(request);}catch(e){return reply({error:'invalid_body'},e.status||400);}
  if(!b||typeof b!=='object'||Array.isArray(b)||Object.keys(b).sort().join(',')!=='id,intro'||typeof b.id!=='string'||!/^[a-f0-9-]{36}$/.test(b.id)||typeof b.intro!=='string'||!b.intro.trim()||b.intro.length>600)return reply({error:'invalid_body'},400);
  // 実Geminiへの接続・回数・料金は Codex の担当。つながるまでは何も送らず、自己紹介も保存せず、回数も使わない
  return reply({error:'generator_not_ready',real:false,candidates:[]},503);
 }
 return reply({error:'not_found'},404);
}
