import {chatContent,chatResponse} from './openai-chat-content.mjs';
const UID=/^(u[12]|p_(free|mini|standard|pro|unlimit))$/,ID=/^[a-zA-Z0-9_-]{8,64}$/;
async function digest(text){return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text))),b=>b.toString(16).padStart(2,'0')).join('');}
function checkSnapshot(snapshot,hash,body){
 if(!snapshot||snapshot.version!==1||snapshot.digest!==hash)throw Error('chat_context_conflict');
 chatContent(body,snapshot.history);return snapshot.history;
}
export async function capturedChatHistory(db,uid,requestId,body){
 if(!db||!UID.test(uid)||typeof requestId!=='string'||!ID.test(requestId))throw Error('invalid_chat_context');
 chatContent(body); // Never persist a private or unsupported current input.
 const hash=await digest(body.text),prefix='openai-chat-context:'+uid+':',key=prefix+requestId;
 const prior=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(key).first('v');
 if(prior){if(prior.length>7000)throw Error('invalid_chat_context');return checkSnapshot(JSON.parse(prior),hash,body);}
 const chatPrefix='learning-chat:'+uid+':';
 const rows=(await db.prepare("SELECT v FROM auth_kv WHERE k>=? AND k<? AND json_valid(v) AND json_extract(v,'$.state')='done' AND json_extract(v,'$.mock')=0 AND json_extract(v,'$.real')=1 AND json_extract(v,'$.id')<>? ORDER BY CAST(json_extract(v,'$.at') AS INTEGER) DESC,k DESC LIMIT 6").bind(chatPrefix,chatPrefix+'\uffff',requestId).all()).results||[];
 const newest=[];
 for(const item of rows){
  const row=JSON.parse(item.v);
  if(typeof row.text!=='string'||!['gpt-6-luna','gpt-6.1-sol'].includes(row.model))throw Error('invalid_chat_context');
  chatContent({text:row.text,images:[]});const answer=chatResponse(JSON.stringify({answer:row.answer})).answer;
  const pair={text:row.text.trim().slice(0,1000),answer:answer.slice(0,1000)};
  if(JSON.stringify([pair,...newest]).length>6000)break;
  newest.unshift(pair);
 }
 const snapshot=JSON.stringify({version:1,digest:hash,history:newest});
 const saved=await db.prepare("INSERT INTO auth_kv(k,v,expires_at) SELECT ?,?,0 WHERE (SELECT COUNT(*) FROM auth_kv WHERE k>=? AND k<?)<100000 ON CONFLICT(k) DO NOTHING RETURNING v").bind(key,snapshot,prefix,prefix+'\uffff').first('v');
 const authoritative=saved||await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(key).first('v');
 if(!authoritative||authoritative.length>7000)throw Error('chat_context_unavailable');
 return checkSnapshot(JSON.parse(authoritative),hash,body);
}
