import {textbookAccessOn,textbookAccess} from './textbook-access.mjs';
import {textbookChatHistory} from './textbook-ai-history.mjs';
import {serveTextbookChat} from './textbook-ai-service.mjs';
import {textbookChatRequest} from './textbook-ai-chat-content.mjs';
const reply=(value,status=200)=>Response.json(value,{status,headers:{'Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff'}});
async function readBody(request){
 if(!/^application\/json(?:\s*;|$)/i.test(request.headers.get('Content-Type')||'')||!request.body)throw Error('invalid_body');
 const reader=request.body.getReader(),parts=[];let size=0;
 try{for(;;){const r=await reader.read();if(r.done)break;size+=r.value.byteLength;if(size>18000){await reader.cancel();throw Error('invalid_body');}parts.push(r.value);}}finally{reader.releaseLock();}
 const bytes=new Uint8Array(size);let at=0;for(const p of parts){bytes.set(p,at);at+=p.byteLength;}
 return JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes));
}
export async function textbookAIRoute(request,env,session,{owner,now=()=>Date.now(),fetcher,readContext}={}){
 if(!textbookAccessOn(env))return reply({error:'not_found'},404);
 const uid=session?.uid;
 if(typeof uid!=='string'||typeof owner!=='string'||!owner)return reply({error:'unauthorized'},401);
 if(!/^(?:u[124]|p_(?:free|mini|standard|pro|unlimit))$/.test(uid)||(uid.startsWith('p_')&&env.PREVIEW_PLAN_ACCOUNTS!=='1'))return reply({error:'forbidden'},403);
 if(!env.AUTH_DB)return reply({error:'unavailable'},503);
 const url=new URL(request.url);if(url.pathname!=='/textbook-ai-chat')return reply({error:'not_found'},404);
 if(!['GET','POST'].includes(request.method))return reply({error:'method_not_allowed'},405);
 const origin=request.headers.get('Origin');if((request.method==='POST'||origin!==null)&&origin!==env.APP_ORIGIN)return reply({error:'origin'},403);
 const active=async()=>!!await env.AUTH_DB.prepare('SELECT 1 AS x FROM auth_kv WHERE k=? AND v=? AND expires_at>?').bind('active-session:'+uid,owner,now()).first('x');
 try{
  if(!await active())return reply({error:'active_session'},409);
  if(request.method==='GET'){
   const keys=[...url.searchParams.keys()];
   if(keys.some(k=>!['book','anchor','id'].includes(k))||['book','anchor'].some(k=>url.searchParams.getAll(k).length!==1)||url.searchParams.getAll('id').length>1)return reply({error:'invalid_query'},400);
   try{textbookChatRequest({book:url.searchParams.get('book'),anchor:url.searchParams.get('anchor'),id:url.searchParams.get('id')||'history_query',text:'履歴',annotationSignature:'0'.repeat(64),contextSha256:'0'.repeat(64)});}catch{return reply({error:'invalid_query'},400);}
   const history=await textbookChatHistory(env.AUTH_DB,uid,Object.fromEntries(url.searchParams));
   if(!await active())return reply({error:'active_session'},409);
   const rights=await textbookAccess(env,uid,now());
   if(!await active())return reply({error:'active_session'},409);
   return reply({...history,canSend:rights.enabled&&rights.features.chat===true});
  }
  if(url.search)return reply({error:'invalid_query'},400);
  let body;try{body=await readBody(request);}catch{return reply({error:'invalid_body'},400);}
  const result=await serveTextbookChat(env,session,body,{owner,fetcher,readContext,now:now()});
  const status=result.error?['invalid_request','ai_unsupported'].includes(result.error)?400:['plan_required','ai_consent_required'].includes(result.error)?403:['session_changed','context_changed','id_conflict','plan_changed','request_outcome_unknown','request_in_progress'].includes(result.error)?409:503:200;
  return reply(result,status);
 }catch{return reply({error:request.method==='GET'?'history_unavailable':'textbook_chat_unavailable'},503);}
}
