// Exactly-once full-test reservation in the existing normal subscription ledger.
// Only a branded, owned completed-test snapshot can enter this module.
import {completedTestData} from './ai-test-session.mjs';
import {TEST_REVIEW_CREDITS,testReviewModel} from './ai-test-review-format.mjs';
import {planStatus,readPlanContractSnapshot,SUBSCRIPTION_TERMS} from './plans.mjs';
import {creditPolicyOn} from './subscription-credits.mjs';
import {textbookAccess,textbookWriteGuard} from './textbook-access.mjs';
const DAY=86400000,JST=32400000,UID=/^(?:u[124]|p_(?:free|mini|standard|pro|unlimit))$/;
const UUID=/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/,HASH=/^[a-f0-9]{64}$/;
const fail=code=>{throw Error(code);};
function identity(env,uid,owner,now){if(!env.AUTH_DB||!UID.test(uid)||(uid.startsWith('p_')&&env.PREVIEW_PLAN_ACCOUNTS!=='1')||typeof owner!=='string'||!owner||!Number.isSafeInteger(now)||now<0)fail('invalid_review_identity');}
function rowKey(uid,id){if(!UID.test(uid)||!UUID.test(id))fail('invalid_review_receipt');return 'ai-test-review-credit:'+uid+':'+id;}
function readReceipt(raw,uid){
 let row;try{row=JSON.parse(raw);}catch{fail('invalid_review_receipt');}
 if(!row||row.version!==1||row.uid!==uid||!UUID.test(row.sessionId)||!UUID.test(row.token)||!HASH.test(row.fingerprint)||row.credits!==TEST_REVIEW_CREDITS||!['pro','unlimit'].includes(row.plan)||row.model!==testReviewModel(row.plan)||!['charged','refunded'].includes(row.state)||!Number.isSafeInteger(row.day)||row.day<0||!Array.isArray(row.operations)||row.operations.length>128||row.operations.some(o=>!HASH.test(o.id)||!UUID.test(o.token)||!HASH.test(o.digest))||new Set(row.operations.map(o=>o.id)).size!==row.operations.length)fail('invalid_review_receipt');
 if(row.mode==='daily-v2'){
  if(row.units!==200||row.key!=='plan-credit-day:'+uid+':'+row.day)fail('invalid_review_receipt');
 }else if(row.mode==='legacy-monthly'){
  if(row.units!==100||!Number.isSafeInteger(row.periodFrom)||row.periodFrom<0||row.key!=='plan-quota:'+uid+':'+row.periodFrom)fail('invalid_review_receipt');
 }else fail('invalid_review_receipt');
 return row;
}
async function access(env,uid,owner,at){
 // A textbook-only early gift must not unlock reviews throughout the normal problem tab.
 if(env.SUBSCRIPTION_PREVIEW!=='1')fail('plan_required');
 if(!await env.AUTH_DB.prepare('SELECT 1 AS x FROM auth_kv WHERE k=? AND v=? AND expires_at>?').bind('active-session:'+uid,owner,at).first('x'))fail('session_changed');
 const status=await planStatus(env,uid,at),book=await textbookAccess(env,uid,at),contract=await readPlanContractSnapshot(env.AUTH_DB,uid,at);
 if(!status.provisional||!['pro','unlimit'].includes(status.plan)||contract.plan!==status.plan||!book.features.chat||book.mode==='v3'&&book.plan!==status.plan)fail('plan_required');
 const base=textbookWriteGuard(book,{uid,owner,feature:'chat',now:at});
 let sql=base.sql,values=[...base.values];
 if(contract.rawContract===null)fail('plan_required');
 sql+=' AND EXISTS(SELECT 1 FROM auth_kv WHERE k=? AND v=?)';values.push('plan:'+uid,contract.rawContract);
 let deadline=contract.row.end===null?null:contract.row.end+SUBSCRIPTION_TERMS.graceDays*DAY;
 if(contract.row.next)deadline=Math.min(deadline??Number.MAX_SAFE_INTEGER,contract.row.next.from);
 if(deadline!==null){if(!Number.isSafeInteger(deadline)||at>=deadline)fail('plan_changed');sql+=' AND ?<?';values.push(at,deadline);}
 return {status,plan:status.plan,model:testReviewModel(status.plan),guard:{sql,values}};
}
function validDaily(raw){
 if(!raw)return;
 const r=JSON.parse(raw);if(r.version!==2||!Number.isSafeInteger(r.units)||r.units<0||!Number.isSafeInteger(r.calls)||r.calls<0)fail('review_quota_unavailable');
}
function validMonthly(raw){
 if(!raw)return;
 const r=JSON.parse(raw);if(!Number.isSafeInteger(r.n)||r.n<0||!Number.isSafeInteger(r.daily)||r.daily<0||!(r.day===null||Number.isSafeInteger(r.day)))fail('review_quota_unavailable');
}
export async function reserveTestReviewCredits(env,uid,proof,{owner,now=Date.now()}={}){
 identity(env,uid,owner,now);const source=completedTestData(proof,uid),db=env.AUTH_DB,began=performance.now(),clock=()=>now+Math.ceil(performance.now()-began);
 const rights=await access(env,uid,owner,clock()),key=rowKey(uid,source.session.id),priorRaw=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(key).first('v');
 if(priorRaw){const prior=readReceipt(priorRaw,uid);if(prior.fingerprint!==source.fingerprint)fail('id_conflict');if(prior.state==='charged'){if(prior.plan!==rights.plan)fail('plan_changed');if(!await db.prepare('SELECT 1 AS x FROM auth_kv WHERE k=? AND v=? AND expires_at>?').bind('active-session:'+uid,owner,clock()).first('x'))fail('session_changed');return {receipt:{key,token:prior.token},credits:100,cached:true,model:prior.model};}}
 const s=rights.status;if(s.dailyLeft<TEST_REVIEW_CREDITS||s.aiLeft!==null&&s.aiLeft<TEST_REVIEW_CREDITS)fail('review_quota_exhausted');
 const mode=creditPolicyOn(env)?'daily-v2':'legacy-monthly',day=Math.floor((now+JST)/DAY),token=crypto.randomUUID(),units=mode==='daily-v2'?200:100;
 const quotaKey=mode==='daily-v2'?'plan-credit-day:'+uid+':'+day:'plan-quota:'+uid+':'+s.periodFrom;
 const quotaRaw=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(quotaKey).first('v');
 if(mode==='daily-v2')validDaily(quotaRaw);else validMonthly(quotaRaw);
 const receipt={version:1,uid,sessionId:source.session.id,fingerprint:source.fingerprint,token,state:'charged',plan:rights.plan,model:rights.model,credits:100,units,mode,key:quotaKey,day,periodFrom:mode==='legacy-monthly'?s.periodFrom:null,operations:[]};
 const serialized=JSON.stringify(receipt),expires=(mode==='daily-v2'?(day+1)*DAY-JST:s.renewAt)+400*DAY;
 const fresh=await access(env,uid,owner,clock());if(fresh.plan!==rights.plan)fail('plan_changed');
 let guard=fresh.guard.sql+(priorRaw===null?' AND NOT EXISTS(SELECT 1 FROM auth_kv WHERE k=?)':' AND EXISTS(SELECT 1 FROM auth_kv WHERE k=? AND v=?)');
 const args=[...fresh.guard.values,key,...(priorRaw===null?[]:[priorRaw])];
 // Preserve legacy pre-ledger usage too, and pin it against an older concurrent writer.
 if(mode==='legacy-monthly'){
  const legacyKey='plan-ai:'+uid+':'+s.periodFrom,legacy=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(legacyKey).first('v');
  if(legacy!==null&&(!/^\d{1,9}$/.test(legacy)||Number(legacy)>s.aiUsed))fail('review_quota_unavailable');
  if(legacy===null){guard+=' AND NOT EXISTS(SELECT 1 FROM auth_kv WHERE k=?)';args.push(legacyKey);}else{guard+=' AND EXISTS(SELECT 1 FROM auth_kv WHERE k=? AND v=?)';args.push(legacyKey,legacy);}
 }
 const statements=[];
 if(mode==='daily-v2'){
  statements.push(db.prepare("INSERT INTO auth_kv(k,v,expires_at) SELECT ?,?,? WHERE ?<=? AND "+guard+" ON CONFLICT(k) DO UPDATE SET v=json_object('version',2,'units',json_extract(auth_kv.v,'$.units')+CAST(? AS INTEGER),'calls',json_extract(auth_kv.v,'$.calls')+1,'lastCharge',?) WHERE json_valid(auth_kv.v) AND json_extract(auth_kv.v,'$.version')=2 AND json_type(auth_kv.v,'$.units')='integer' AND json_extract(auth_kv.v,'$.units')>=0 AND json_type(auth_kv.v,'$.calls')='integer' AND json_extract(auth_kv.v,'$.calls')>=0 AND json_extract(auth_kv.v,'$.units')+CAST(? AS INTEGER)<=? AND "+guard).bind(quotaKey,JSON.stringify({version:2,units,calls:1,lastCharge:token}),expires,units,s.dailyLimit*2,...args,units,token,units,s.dailyLimit*2,...args));
 }else{
  const monthly=s.aiLimit??1000000000;
  statements.push(db.prepare("INSERT INTO auth_kv(k,v,expires_at) SELECT ?,?,? WHERE ?<=? AND ?<=? AND "+guard+" ON CONFLICT(k) DO UPDATE SET v=json_object('n',json_extract(auth_kv.v,'$.n')+100,'day',CAST(? AS INTEGER),'daily',CASE WHEN json_extract(auth_kv.v,'$.day')=? THEN json_extract(auth_kv.v,'$.daily')+100 ELSE 100 END,'lastCharge',?) WHERE json_valid(auth_kv.v) AND json_type(auth_kv.v,'$.n')='integer' AND json_extract(auth_kv.v,'$.n')>=0 AND json_type(auth_kv.v,'$.daily')='integer' AND json_extract(auth_kv.v,'$.daily')>=0 AND json_extract(auth_kv.v,'$.n')+100<=? AND (CASE WHEN json_extract(auth_kv.v,'$.day')=? THEN json_extract(auth_kv.v,'$.daily') ELSE 0 END)+100<=? AND "+guard).bind(quotaKey,JSON.stringify({n:s.aiUsed+100,day,daily:s.dailyUsed+100,lastCharge:token}),expires,s.aiUsed+100,monthly,s.dailyUsed+100,s.dailyLimit,...args,day,day,token,monthly,day,s.dailyLimit,...args));
 }
 statements.push(db.prepare("INSERT INTO auth_kv(k,v,expires_at) SELECT ?,?,? WHERE EXISTS(SELECT 1 FROM auth_kv WHERE k=? AND json_extract(v,'$.lastCharge')=?) ON CONFLICT(k) DO UPDATE SET v=excluded.v,expires_at=excluded.expires_at WHERE json_extract(auth_kv.v,'$.state')='refunded' AND json_extract(auth_kv.v,'$.fingerprint')=json_extract(excluded.v,'$.fingerprint')").bind(key,serialized,expires,quotaKey,token));
 const result=await db.batch(statements);
 const committed=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(key).first('v');
 if(!committed)fail('review_quota_or_access_changed');
 const final=readReceipt(committed,uid);if(final.fingerprint!==source.fingerprint)fail('id_conflict');if(final.state!=='charged')fail('review_quota_or_access_changed');
 // Only the winning transaction can charge. Replays return its receipt without another debit.
 return {receipt:{key,token:final.token},credits:100,cached:final.token!==token||result[0]?.meta?.changes!==1,model:final.model};
}
export async function linkTestReviewOperation(env,uid,proof,receipt,operation,{owner,now=Date.now()}={}){
 identity(env,uid,owner,now);const source=completedTestData(proof,uid),db=env.AUTH_DB,key=rowKey(uid,source.session.id);
 if(receipt?.key!==key||!UUID.test(receipt?.token)||!HASH.test(operation?.id)||!UUID.test(operation?.token))fail('invalid_review_operation');
 const raw=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(key).first('v'),row=readReceipt(raw,uid);
 if(row.token!==receipt.token||row.state!=='charged'||row.fingerprint!==source.fingerprint)fail('invalid_review_operation');
 const rights=await access(env,uid,owner,now);if(rights.plan!==row.plan)fail('plan_changed');
 const before=row.operations.find(o=>o.id===operation.id);
 // Repeated checkpoint is UNKNOWN, never permission to dispatch again.
 if(before?.token===operation.token)return false;
 if(!before&&row.operations.length>=128)fail('review_operation_limit');
 const opKey='openai-operation:'+uid+':'+operation.id,opRaw=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(opKey).first('v');
 let op;try{op=JSON.parse(opRaw);}catch{return false;}
 if(op?.state!=='started'||op.token!==operation.token||op.pricing?.model!==row.model||!HASH.test(op.digest)||before&&before.digest!==op.digest)return false;
 // A new nonce for the same digest is possible only after the shared monetary
 // journal rejected the earlier attempt as uncharged. Keep the new current nonce.
 const entry={id:operation.id,token:operation.token,digest:op.digest};
 const next=JSON.stringify({...row,operations:before?row.operations.map(o=>o.id===operation.id?entry:o):[...row.operations,entry]});
 return !!await db.prepare("UPDATE auth_kv SET v=? WHERE k=? AND v=? AND "+rights.guard.sql+" AND EXISTS(SELECT 1 FROM auth_kv WHERE k=? AND v=?) RETURNING v").bind(next,key,raw,...rights.guard.values,opKey,opRaw).first('v');
}
export async function refundTestReviewCredits(env,uid,receipt){
 if(!env.AUTH_DB||!UID.test(uid)||typeof receipt?.key!=='string'||!receipt.key.startsWith('ai-test-review-credit:'+uid+':')||!UUID.test(receipt.key.slice(('ai-test-review-credit:'+uid+':').length))||!UUID.test(receipt.token))fail('invalid_review_receipt');
 const db=env.AUTH_DB,raw=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(receipt.key).first('v');if(!raw)return false;
 const row=readReceipt(raw,uid);if(row.token!==receipt.token||row.state==='refunded')return false;
 // Never refund after an issued/unknown/completed generation. An authoritative rejected
 // monetary journal is required for every linked provider operation.
 const safe="NOT EXISTS(SELECT 1 FROM json_each(?) x LEFT JOIN auth_kv o ON o.k=?||json_extract(x.value,'$.id') WHERE o.k IS NULL OR NOT json_valid(o.v) OR json_extract(o.v,'$.token') IS NOT json_extract(x.value,'$.token') OR json_extract(o.v,'$.digest') IS NOT json_extract(x.value,'$.digest') OR json_extract(o.v,'$.state') IS NOT 'rejected')";
 const args=[JSON.stringify(row.operations),'openai-operation:'+uid+':'];
 const nonce=crypto.randomUUID(),guard='EXISTS(SELECT 1 FROM auth_kv WHERE k=? AND v=?) AND '+safe;
 let update;
 if(row.mode==='daily-v2')update=db.prepare("UPDATE auth_kv SET v=json_set(v,'$.units',json_extract(v,'$.units')-200,'$.calls',json_extract(v,'$.calls')-1,'$.reviewRefund',?) WHERE k=? AND json_valid(v) AND json_extract(v,'$.version')=2 AND json_type(v,'$.units')='integer' AND json_extract(v,'$.units')>=200 AND json_type(v,'$.calls')='integer' AND json_extract(v,'$.calls')>=1 AND "+guard).bind(nonce,row.key,receipt.key,raw,...args);
 else update=db.prepare("UPDATE auth_kv SET v=json_set(v,'$.n',json_extract(v,'$.n')-100,'$.daily',CASE WHEN json_extract(v,'$.day')=? THEN json_extract(v,'$.daily')-100 ELSE json_extract(v,'$.daily') END,'$.reviewRefund',?) WHERE k=? AND json_valid(v) AND json_type(v,'$.n')='integer' AND json_extract(v,'$.n')>=100 AND json_type(v,'$.daily')='integer' AND (json_extract(v,'$.day')<>? OR json_extract(v,'$.daily')>=100) AND "+guard).bind(row.day,nonce,row.key,row.day,receipt.key,raw,...args);
 const result=await db.batch([update,db.prepare("UPDATE auth_kv SET v=json_set(v,'$.state','refunded') WHERE k=? AND v=? AND EXISTS(SELECT 1 FROM auth_kv WHERE k=? AND json_extract(v,'$.reviewRefund')=?)").bind(receipt.key,raw,row.key,nonce)]);
 return result[0]?.meta?.changes===1&&result[1]?.meta?.changes===1;
}
// Server-only access/snapshot for the durable review worker. Reading the
// existing receipt must never implicitly reserve another100 credits.
export async function testReviewAccess(env,uid,{owner,now=Date.now()}={}){
 identity(env,uid,owner,now);return access(env,uid,owner,now);
}
export async function testReviewCreditSnapshot(db,uid,sessionId){
 const key=rowKey(uid,sessionId),raw=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(key).first('v');
 return raw===null?null:{key,raw,row:readReceipt(raw,uid)};
}
