// 英検の練習答案を、同じ配布物の提出箱へ保存する。問題文・正解はサーバーの正本から取得する。
import bank from './admin-eiken-bank.json' with {type:'json'};
import {profilesFor} from './admin-workspace.mjs';
const reply=(value,status=200)=>Response.json(value,{status,headers:{'Cache-Control':'no-store'}});
const encode=new TextEncoder();
export async function eikenSubmitRoute(request,env,session){
 if(!session?.uid)return reply({error:'unauthorized'},401);
 const allowed=profilesFor(env);
 if(!allowed.some(p=>p.uid===session.uid))return reply({error:'forbidden'},403);
 if(request.method!=='POST')return reply({error:'method_not_allowed'},405);
 if(request.headers.get('Origin')!==env.APP_ORIGIN)return reply({error:'origin'},403);
 if(new URL(request.url).search)return reply({error:'invalid_query'},400);
 if(!/^application\/json\b/.test(request.headers.get('Content-Type')||''))return reply({error:'content_type'},415);
 if(!env.AUTH_DB||!request.body)return reply({error:'unavailable'},503);
 const reader=request.body.getReader(),parts=[];let length=0,b;
 try{while(true){const r=await reader.read();if(r.done)break;length+=r.value.length;if(length>90000){await reader.cancel();throw Error();}parts.push(r.value);}const bytes=new Uint8Array(length);let at=0;for(const p of parts){bytes.set(p,at);at+=p.length;}b=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes));}catch(_){return reply({error:'invalid_body'},400);}finally{reader.releaseLock();}
 if(!b||typeof b!=='object'||Array.isArray(b)||Object.keys(b).some(k=>!['id','grade','set','answers','questionIds'].includes(k))||!/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/.test(b.id||'')||!Number.isInteger(b.set)||!b.answers||typeof b.answers!=='object'||Array.isArray(b.answers)||!Array.isArray(b.questionIds)||!b.questionIds.length||b.questionIds.length>20||new Set(b.questionIds).size!==b.questionIds.length)return reply({error:'invalid_body'},400);
 const grade=bank.grades.find(g=>g.id===b.grade),set=grade?.sets.find(s=>s.n===b.set);
 if(!set||b.questionIds.some(id=>!set.questions.some(q=>q.id===id))||Object.keys(b.answers).some(id=>!b.questionIds.includes(id)))return reply({error:'invalid_body'},400);
 const selected=set.questions.filter(q=>b.questionIds.includes(q.id)),answers={};
 let total=0;for(const [i,q] of selected.entries()){const v=b.answers[q.id]??'';if(typeof v!=='string'||v.length>4000||/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/.test(v))return reply({error:'invalid_body'},400);total+=v.length;if(v.trim())answers['q'+(i+1)]=v;}
 if(total>20000)return reply({error:'too_long'},400);
 const uid=session.uid,db=env.AUTH_DB,now=Date.now(),id=[...new Uint8Array(await crypto.subtle.digest('SHA-256',encode.encode('eiken:'+uid+':'+b.id)))].map(x=>x.toString(16).padStart(2,'0')).join('').slice(0,32),key='assignment:'+id;
 const payload={grade:b.grade,set:b.set,questionIds:selected.map(q=>q.id),answers};
 const old=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(key).first('v');
 if(old){const a=JSON.parse(old),receipt=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind('eiken-receipt:'+id).first('v');return a.createdBy===uid&&receipt===JSON.stringify(payload)?reply({ok:true,id,repeat:true}):reply({error:'conflict'},409);}
 const name=allowed.find(p=>p.uid===uid).label,title='英検'+grade.label+' 練習'+b.set+' · '+name;
 const item={id,title,writeId:crypto.randomUUID(),note:'のびログ独自の練習問題の答案です。自動判定とは別に、なおが確認して返却します。',targets:[uid],openAt:now,dueAt:now+86400000,minutes:null,createdBy:uid,createdAt:now,eikenPayload:{grade:b.grade,set:b.set,questionIds:selected.map(q=>q.id)},
  questions:selected.map((q,i)=>({id:'q'+(i+1),prompt:(q.context?q.context+'\n\n':'')+q.q,answer:q.answer+'\n解説：'+(q.why||''),points:5}))};
 // 答案は work にだけ置き、問題の定義には入れない。
 const work={id,uid,submission:{answers,at:now},startedAt:null,draft:null,review:null};
 const serialized=JSON.stringify(item),workText=JSON.stringify(work),token=crypto.randomUUID().replace(/-/g,'').slice(0,12),receipt={...payload};
 // 同じrequest IDの中身は別行へ保存する。既存のassignment IDと本人・回答を照合して再送を判定する。
 const count=Number(await db.prepare('SELECT COUNT(*) n FROM auth_kv WHERE k>=? AND k<?').bind('assignment:','assignment:\uffff').first('n'))||0;
 if(count>=300)return reply({error:'too_many'},409);
 const results=await db.batch([
  db.prepare('INSERT INTO auth_kv(k,v,expires_at) SELECT ?,?,0 WHERE (SELECT COUNT(*) FROM auth_kv WHERE k>=? AND k<?)<300 ON CONFLICT(k) DO NOTHING').bind(key,serialized,'assignment:','assignment:\uffff'),
  db.prepare('INSERT INTO auth_kv(k,v,expires_at) SELECT ?,?,0 WHERE EXISTS(SELECT 1 FROM auth_kv WHERE k=? AND v=?) ON CONFLICT(k) DO NOTHING').bind('assignment-work:'+id+':'+uid,workText,key,serialized),
  db.prepare('INSERT INTO auth_kv(k,v,expires_at) SELECT ?,?,0 WHERE EXISTS(SELECT 1 FROM auth_kv WHERE k=? AND v=?) ON CONFLICT(k) DO NOTHING').bind('eiken-receipt:'+id,JSON.stringify(receipt),key,serialized),
  db.prepare('INSERT INTO auth_kv(k,v,expires_at) SELECT ?,?,? WHERE EXISTS(SELECT 1 FROM auth_kv WHERE k=? AND v=?)').bind('activity:'+uid+':'+String(now).padStart(15,'0')+':'+token,JSON.stringify({type:'assignment-submit',id,at:now}),now+315360000000,key,serialized)
 ]);
 if(Number(results[0]?.meta?.changes)!==1)return reply({error:'conflict'},409);
 return reply({ok:true,id,notify:{uid:'u1',id:'assignment-submit:'+id+':'+uid,at:now,title:'英検の回答が終わりました',body:name+'の英検練習が終わりました。アドミンを開いて提出箱を確認してください。'}},201);
}
