import { createProblemPdf, PDF_LIMITS } from '../../site-assets/problem-pdf.mjs';
const TTL = 7 * 86400;
const BODY_LIMIT = 9 * 1024 * 1024;
const HEADERS = {'Cache-Control':'no-store','X-Content-Type-Options':'nosniff','Referrer-Policy':'no-referrer','X-Robots-Tag':'noindex, noarchive'};
const reply = (body,status=200) => Response.json(body,{status,headers:HEADERS});
const validId = id => /^[a-f0-9]{48}$/.test(id);

async function readBounded(stream, limit) {
    if (!stream) throw new Error('missing_body');
    const reader=stream.getReader(),parts=[];let size=0;
    try {
        while(true){const {done,value}=await reader.read();if(done)break;size+=value.byteLength;if(size>limit){await reader.cancel();throw new Error('too_large');}parts.push(value);}
    }finally{reader.releaseLock();}
    const result=new Uint8Array(size);let offset=0;
    for(const part of parts){result.set(part,offset);offset+=part.length;}
    return result;
}
async function decodePages(body) {
    if(!body||Object.keys(body).length!==1||!Array.isArray(body.pages)||!body.pages.length||body.pages.length>PDF_LIMITS.pages)throw new Error('bad_pages');
    let total=0;const pages=[];
    for(const page of body.pages){
        if(!page||Object.keys(page).sort().join(',')!=='data,height,width')throw new Error('bad_page');
        const {width,height,data}=page,count=width*height;
        if(!Number.isInteger(width)||!Number.isInteger(height)||width<320||height<320||width>2200||height>2200||count>PDF_LIMITS.pagePixels||(total+=count)>PDF_LIMITS.totalPixels)throw new Error('bad_dimensions');
        if(typeof data!=='string'||!data.length||data.length>BODY_LIMIT||data.length%4||!/^[A-Za-z0-9+/]*={0,2}$/.test(data))throw new Error('bad_encoding');
        const raw=Uint8Array.from(atob(data),c=>c.charCodeAt(0));
        const pixels=await readBounded(new Blob([raw]).stream().pipeThrough(new DecompressionStream('deflate')),count);
        if(pixels.length!==count)throw new Error('bad_pixels');
        pages.push({width,height,pixels});
    }
    return pages;
}

export async function publicProblemPdf(request,env,id) {
    if(!validId(id)||!['GET','HEAD'].includes(request.method))return reply({error:'not_found'},404);
    if(!env.AUTH_DB||!env.BOARD)return reply({error:'unavailable'},503);
    const row=await env.AUTH_DB.prepare('SELECT v,expires_at FROM auth_kv WHERE k=?').bind('problem-share:'+id).first();
    if(!row||row.expires_at<=Date.now())return reply({error:'not_found'},404);
    const bytes=await env.BOARD.get('problem-pdf:'+id,'arrayBuffer');
    if(!bytes)return reply({error:'not_ready'},503);
    // Recheck after storage I/O so revocation during a slow read takes effect.
    const live=await env.AUTH_DB.prepare('SELECT expires_at FROM auth_kv WHERE k=?').bind('problem-share:'+id).first();
    if(!live||live.expires_at<=Date.now())return reply({error:'not_found'},404);
    return new Response(request.method==='HEAD'?null:bytes,{headers:{...HEADERS,'Content-Type':'application/pdf','Content-Disposition':'inline; filename="nobilog-problems.pdf"'}});
}

export async function problemShareRoute(request,env,session) {
    if(!session||!['u1','u2'].includes(session.uid))return reply({error:'unauthorized'},401);
    if(!env.AUTH_DB||!env.BOARD)return reply({error:'unavailable'},503);
    const url=new URL(request.url);
    if(request.method==='GET'){
        const rows=(await env.AUTH_DB.prepare("SELECT k,v,expires_at FROM auth_kv WHERE k>=? AND k<? AND expires_at>? AND json_extract(v,'$.owner')=? ORDER BY expires_at DESC LIMIT 50").bind('problem-share:','problem-share:\uffff',Date.now(),session.uid).all()).results||[];
        return reply({shares:rows.filter(row=>JSON.parse(row.v).owner===session.uid).map(row=>({id:row.k.slice(14),expiresAt:row.expires_at}))});
    }
    if(request.method!=='POST')return reply({error:'method_not_allowed'},405);
    if(request.headers.get('Origin')!==env.APP_ORIGIN)return reply({error:'origin_rejected'},403);
    if(url.searchParams.get('revoke')!==null){
        const id=url.searchParams.get('revoke');
        if(!validId(id))return reply({error:'not_found'},404);
        const revoked=await env.AUTH_DB.prepare("DELETE FROM auth_kv WHERE k=? AND json_extract(v,'$.owner')=? RETURNING k").bind('problem-share:'+id,session.uid).first();
        if(!revoked)return reply({error:'not_found'},404);
        // D1 is the authority: stale KV bytes cannot make a revoked link valid.
        try{await env.BOARD.delete('problem-pdf:'+id);}catch(e){/* KV expiry also removes orphan bytes. */}
        return reply({ok:true});
    }
    if(!request.headers.get('Content-Type')?.startsWith('application/json'))return reply({error:'bad_content_type'},415);
    if(Number(request.headers.get('Content-Length'))>BODY_LIMIT)return reply({error:'too_large'},413);
    const now=Date.now(),day=Math.floor(now/86400000);
    const allowed=await env.AUTH_DB.prepare("INSERT INTO auth_kv(k,v,expires_at) VALUES(?,'1',?) ON CONFLICT(k) DO UPDATE SET v=CAST(CAST(v AS INTEGER)+1 AS TEXT) WHERE CAST(v AS INTEGER)<20 RETURNING v").bind('problem-share-rate:'+session.uid+':'+day,now+2*86400000).first();
    if(!allowed)return reply({error:'rate_limited'},429);
    let pdf;
    try{
        const bytes=await readBounded(request.body,BODY_LIMIT);
        const body=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes));
        pdf=await createProblemPdf(await decodePages(body));
    }catch(e){return reply({error:e.message==='too_large'?'too_large':'invalid_pages'},e.message==='too_large'?413:400);}
    const id=Array.from(crypto.getRandomValues(new Uint8Array(24)),n=>n.toString(16).padStart(2,'0')).join('');
    const expiresAt=now+TTL*1000;
    await env.BOARD.put('problem-pdf:'+id,pdf.buffer,{expirationTtl:TTL});
    await env.AUTH_DB.prepare('INSERT INTO auth_kv(k,v,expires_at) VALUES(?,?,?)').bind('problem-share:'+id,JSON.stringify({owner:session.uid}),expiresAt).run();
    return reply({id,expiresAt,url:url.origin+'/problem-pdf/'+id},201);
}
