import {admitTestReview} from './ai-test-review-service.mjs';
import {finishedTestReviewResult,listTestReviewJobs} from './ai-test-review-jobs.mjs';
const UUID=/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/;
const reply=(value,status=200)=>Response.json(value,{status,headers:{'Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff'}});
async function readBody(request){
 if(!/^application\/json(?:\s*;|$)/i.test(request.headers.get('Content-Type')||'')||!request.body)throw Error('invalid_body');
 const reader=request.body.getReader(),parts=[];let size=0;
 try{for(;;){const part=await reader.read();if(part.done)break;size+=part.value.byteLength;if(size>2000){await reader.cancel();throw Error('invalid_body');}parts.push(part.value);}}finally{reader.releaseLock();}
 const bytes=new Uint8Array(size);let at=0;for(const part of parts){bytes.set(part,at);at+=part.byteLength;}return JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes));
}
export async function testReviewRoute(request,env,session,{owner,now=()=>Date.now()}={}){
 const uid=session?.uid,url=new URL(request.url);
 if(url.pathname!=='/material-test-review')return reply({error:'not_found'},404);
 if(typeof uid!=='string'||typeof owner!=='string'||!owner)return reply({error:'unauthorized'},401);
 if(!/^(?:u[124]|p_(?:free|mini|standard|pro|unlimit))$/.test(uid)||(uid.startsWith('p_')&&env.PREVIEW_PLAN_ACCOUNTS!=='1'))return reply({error:'forbidden'},403);
 if(!['GET','POST'].includes(request.method))return reply({error:'method_not_allowed'},405);
 const origin=request.headers.get('Origin');if((request.method==='POST'||origin!==null)&&origin!==env.APP_ORIGIN)return reply({error:'origin'},403);
 if(!env.AUTH_DB)return reply({error:'unavailable'},503);
 try{
  if(request.method==='GET'){
   if([...url.searchParams.keys()].some(k=>k!=='id')||url.searchParams.getAll('id').length>1)return reply({error:'invalid_query'},400);
   if(!url.searchParams.has('id'))return reply(await listTestReviewJobs(env,uid,{owner,now:now()}));
   const id=url.searchParams.get('id');if(!UUID.test(id))return reply({error:'invalid_query'},400);
   const saved=await finishedTestReviewResult(env,uid,id,{owner,now:now()});return saved?reply(saved):reply({error:'not_found'},404);
  }
  if(url.search)return reply({error:'invalid_query'},400);
  let body;try{body=await readBody(request);}catch{return reply({error:'invalid_body'},400);}
  const result=await admitTestReview(env,session,body,{owner,now:now()});
  const status=result.error?['invalid_review_request','review_input_too_large','private_chat_input','unsupported_chat_input'].includes(result.error)?400:['plan_required','ai_consent_required'].includes(result.error)?403:result.error==='test_session_not_found'?404:['session_changed','test_incomplete','test_source_changed','plan_changed','content_changed','id_conflict'].includes(result.error)?409:503:result.job?.state==='done'?200:202;
  return reply(result,status);
 }catch(error){return reply({error:error?.message==='session_changed'?'active_session':'review_unavailable'},error?.message==='session_changed'?409:503);}
}
