// admin v1.0.0: 管理対象と版付きの下書き。権限は入口の番号ではなくセッションで判定する。
const reply=(body,status=200)=>Response.json(body,{status,headers:{'Cache-Control':'no-store'}});
export const PROFILES=Object.freeze([
 {uid:'u1',label:'なお',alias:'nao',icon:'🌳',focus:'提出・返却と運営',accent:'forest'},
 {uid:'u2',label:'りらん',alias:'riran',icon:'🌷',focus:'学習と弱点',accent:'rose'},
 {uid:'p_free',label:'f1 · Free',alias:'f1',icon:'🌱',focus:'学習の入口',accent:'mint'},
 {uid:'p_mini',label:'m1 · Mini',alias:'m1',icon:'🍊',focus:'単語と毎日の練習',accent:'amber'},
 {uid:'p_standard',label:'s1 · Standard',alias:'s1',icon:'🗓️',focus:'計画と週間の学習',accent:'blue'},
 {uid:'p_pro',label:'p1 · Pro',alias:'p1',icon:'🔭',focus:'分析・ノート・相談',accent:'violet'},
 {uid:'p_unlimit',label:'u1 · UNLIMIT',alias:'u1',icon:'💎',focus:'解説・提出物・アーカイブ',accent:'navy'}
]);
export const profilesFor=env=>PROFILES.filter(p=>['u1','u2'].includes(p.uid)||env.PREVIEW_PLAN_ACCOUNTS==='1');
const kinds=['template','draft','page','schedule','layout'],idRx=/^[a-z0-9][a-z0-9_-]{0,119}$/;
const obj=v=>v&&typeof v==='object'&&!Array.isArray(v);
const keys=(v,list)=>obj(v)&&Object.keys(v).every(k=>list.includes(k));
const txt=(v,max)=>typeof v==='string'&&v.length<=max&&!/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/.test(v);
const integer=(v,min,max)=>Number.isInteger(v)&&v>=min&&v<=max;
export function validValue(kind,v){
 if(!obj(v)||!txt(v.title,120)||!v.title.trim())return false;
 if(kind==='template')return keys(v,['title','subject','purpose','count','minutes','instructions'])&&['数学','英語','国語','理科','社会'].includes(v.subject)&&txt(v.purpose,60)&&integer(v.count,1,50)&&integer(v.minutes,1,300)&&txt(v.instructions,4000);
 if(kind==='draft')return keys(v,['title','subject','instructions','questions'])&&txt(v.subject,20)&&txt(v.instructions,4000)&&Array.isArray(v.questions)&&v.questions.length<=50&&v.questions.every(q=>keys(q,['prompt','answer','explanation','points'])&&txt(q.prompt,1000)&&q.prompt.trim()&&txt(q.answer,1000)&&txt(q.explanation,1000)&&integer(q.points,0,100));
 if(kind==='page')return keys(v,['title','book','page','digest','status','note','draft'])&&idRx.test(v.book)&&integer(v.page,1,10000)&&/^[a-f0-9]{64}$/.test(v.digest)&&['pending','reviewed','needs-fix'].includes(v.status)&&txt(v.note,4000)&&txt(v.draft,50000);
 if(kind==='schedule')return keys(v,['title','date','time','minutes','note','done'])&&/^\d{4}-\d{2}-\d{2}$/.test(v.date)&&new Date(v.date+'T00:00:00Z').toISOString().slice(0,10)===v.date&&/^([01]\d|2[0-3]):[0-5]\d$/.test(v.time)&&integer(v.minutes,1,300)&&txt(v.note,2000)&&typeof v.done==='boolean';
 if(kind==='layout')return keys(v,['title','order','density'])&&['comfortable','compact'].includes(v.density)&&Array.isArray(v.order)&&v.order.length===4&&new Set(v.order).size===4&&v.order.every(s=>['summary','heat','week','actions'].includes(s));
 return false;
}
async function body(request,max=240000){
 if(!/^application\/json\b/.test(request.headers.get('Content-Type')||''))throw Object.assign(Error('type'),{status:415});
 if(!request.body)throw Error('body');
 const reader=request.body.getReader(),parts=[];let size=0;
 try{while(true){const r=await reader.read();if(r.done)break;size+=r.value.length;if(size>max){await reader.cancel();throw Error('size');}parts.push(r.value);}}finally{reader.releaseLock();}
 const bytes=new Uint8Array(size);let at=0;for(const p of parts){bytes.set(p,at);at+=p.length;}return JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes));
}
const docKey=(uid,kind,id)=>'admin-doc:'+uid+':'+kind+':'+id;
const revisionKey=(key,revision)=>'admin-revision:'+key+':'+String(revision).padStart(10,'0');
export async function workspaceRoute(request,env,session,{snapshot}={}){
 if(!session?.uid)return reply({error:'unauthorized'},401);
 if(session.uid!=='u1')return reply({error:'forbidden'},403);
 if(!env.AUTH_DB)return reply({error:'unavailable'},503);
 const url=new URL(request.url),db=env.AUTH_DB,people=profilesFor(env),now=Date.now();
 if(url.pathname==='/admin/profiles'){
  if(request.method!=='GET')return reply({error:'method_not_allowed'},405);
  if(url.search)return reply({error:'invalid_query'},400);
  return reply({people,environment:env.PREVIEW_PLAN_ACCOUNTS==='1'?'preview':'production'});
 }
 if(url.pathname==='/admin/vocabulary'){
  if(request.method!=='GET')return reply({error:'method_not_allowed'},405);
  const uid=url.searchParams.get('uid');
  if([...url.searchParams.keys()].length!==1||!people.some(p=>p.uid===uid))return reply({error:'invalid_query'},400);
  if(typeof snapshot!=='function')return reply({error:'unavailable'},503);
  const saved=await snapshot(uid);let value=null;try{value=JSON.parse(saved?.keys?.[uid+':eikenVocab']||'null');}catch(_){}
  const words={};for(const [id,v] of Object.entries(value?.words||{}))if(idRx.test(id)&&obj(v))words[id]={c:Math.max(0,Number(v.c)||0),w:Math.max(0,Number(v.w)||0),due:Math.max(0,Number(v.due)||0),last:Math.max(0,Number(v.last)||0)};
  return reply({uid,words,now});
 }
 if(url.pathname==='/admin/alerts'){
  if(request.method!=='GET')return reply({error:'method_not_allowed'},405);
  if(url.search)return reply({error:'invalid_query'},400);
  const rows=(await db.prepare("SELECT k,v FROM auth_kv WHERE k>=? AND k<? AND json_extract(v,'$.type')='assignment-submit' ORDER BY k DESC LIMIT 30").bind('activity:','activity:\uffff').all()).results||[],items=[];
  for(const row of rows){
   const uid=row.k.split(':')[1],p=people.find(p=>p.uid===uid);if(!p)continue;
   let v;try{v=JSON.parse(row.v);}catch(_){continue;}if(!/^[a-f0-9]{32}$/.test(v.id||''))continue;
   const raw=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind('assignment:'+v.id).first('v');if(!raw)continue;
   const a=JSON.parse(raw);
   items.push({id:'assignment-submit:'+v.id+':'+uid,at:Number(v.at)||now,title:'回答が終わりました',body:p.label+'が「'+a.title+'」を提出しました。アドミンを開いて提出箱を確認してください。',category:'other',assignmentId:v.id});
  }
  const health=(await db.prepare('SELECT v FROM auth_kv WHERE k>=? AND k<? ORDER BY k DESC LIMIT 20').bind('app-health:','app-health:\uffff').all()).results||[];for(const row of health){let x;try{x=JSON.parse(row.v);}catch(_){continue;}if(!people.some(p=>p.uid===x.uid))continue;items.push({id:'app-health:'+x.id,at:x.at,title:'動作の確認が必要です',body:(people.find(p=>p.uid===x.uid)?.label||'')+' · '+x.file+' '+x.line+'行 · '+x.code+'。アドミンの保存・履歴で確認してください。',category:'other'});}
  return reply({items:items.sort((a,b)=>b.at-a.at),now});
 }
 if(url.pathname!=='/admin/workspace')return reply({error:'not_found'},404);
 if(request.method==='GET'){
  const q=url.searchParams,uid=q.get('uid'),kind=q.get('kind'),id=q.get('id'),cursor=q.get('cursor')||'',history=q.get('history');
  const allowed=['uid','kind','id','cursor','history'];
  if([...q.keys()].some(k=>!allowed.includes(k))||new Set(q.keys()).size!==[...q.keys()].length||!people.some(p=>p.uid===uid)||!kinds.includes(kind)||(id&&!idRx.test(id))||(history&&(!id||history!=='1'))||(cursor&&!idRx.test(cursor)&&!(history&&/^\d{10}$/.test(cursor))))return reply({error:'invalid_query'},400);
  const prefix=id?docKey(uid,kind,id):'admin-doc:'+uid+':'+kind+':';
  if(id&&!history){const row=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(prefix).first('v');return reply({item:row?JSON.parse(row):null});}
  const lo=history?'admin-revision:'+prefix+':':prefix;
  const rows=(await db.prepare('SELECT k,v FROM auth_kv WHERE k>=? AND k<? ORDER BY k '+(history?'DESC':'ASC')+' LIMIT 51').bind(history?lo:cursor?lo+cursor+'\u0000':lo,history&&cursor?lo+cursor:lo+'\uffff').all()).results||[];
  return reply({items:rows.slice(0,50).map(r=>JSON.parse(r.v)),next:rows.length>50?rows[49].k.slice(lo.length):null,now});
 }
 if(request.method!=='POST')return reply({error:'method_not_allowed'},405);
 if(!env.APP_ORIGIN||request.headers.get('Origin')!==env.APP_ORIGIN)return reply({error:'origin'},403);
 if(url.search)return reply({error:'invalid_query'},400);
 let b;try{b=await body(request);}catch(e){return reply({error:'invalid_body'},e.status||400);}
 if(!keys(b,['action','uid','kind','id','base','value','revision'])||!['save','restore'].includes(b.action)||!people.some(p=>p.uid===b.uid)||!kinds.includes(b.kind)||!idRx.test(b.id)||!integer(b.base,0,100000000))return reply({error:'invalid_body'},400);
 const key=docKey(b.uid,b.kind,b.id),raw=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(key).first('v'),old=raw?JSON.parse(raw):null;
 if((old?.revision||0)!==b.base)return reply({error:'conflict'},409);
 let value=b.value;
 if(b.action==='restore'){
  if(!integer(b.revision,1,b.base))return reply({error:'invalid_body'},400);
  const stored=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(revisionKey(key,b.revision)).first('v');
  if(!stored)return reply({error:'not_found'},404);value=JSON.parse(stored).value;
 }
 try{if(!validValue(b.kind,value))return reply({error:'invalid_value'},400);}catch(_){return reply({error:'invalid_value'},400);}
 const item={uid:b.uid,kind:b.kind,id:b.id,revision:b.base+1,value,createdAt:old?.createdAt||now,at:now,by:'u1',operationId:crypto.randomUUID()},serialized=JSON.stringify(item);
 const write=raw?db.prepare('UPDATE auth_kv SET v=? WHERE k=? AND v=?').bind(serialized,key,raw):db.prepare('INSERT INTO auth_kv(k,v,expires_at) SELECT ?,?,0 WHERE (SELECT COUNT(*) FROM auth_kv WHERE k>=? AND k<?)<3000 ON CONFLICT(k) DO NOTHING').bind(key,serialized,'admin-doc:','admin-doc:\uffff');
 const log={type:'admin-document',at:now,student:b.uid,unitId:b.kind,id:b.id,action:b.action,revision:item.revision};
 const rand=crypto.randomUUID().replace(/-/g,'').slice(0,12);
 const result=await db.batch([write,db.prepare('INSERT INTO auth_kv(k,v,expires_at) SELECT ?,?,0 WHERE EXISTS(SELECT 1 FROM auth_kv WHERE k=? AND v=?)').bind(revisionKey(key,item.revision),serialized,key,serialized),db.prepare('INSERT INTO auth_kv(k,v,expires_at) SELECT ?,?,? WHERE EXISTS(SELECT 1 FROM auth_kv WHERE k=? AND v=?)').bind('activity:u1:'+String(now).padStart(15,'0')+':'+rand,JSON.stringify(log),now+315360000000,key,serialized)]);
 if(Number(result[0]?.meta?.changes)!==1)return reply({error:'conflict'},409);
 return reply({ok:true,item});
}
