import {profilesFor} from './admin-workspace.mjs';
const reply=(body,status=200)=>Response.json(body,{status,headers:{'Cache-Control':'no-store'}});
export async function reportsRoute(request,env,session){
 if(!session?.uid)return reply({error:'unauthorized'},401);
 if(session.uid!=='u1')return reply({error:'forbidden'},403);
 if(request.method!=='GET')return reply({error:'method_not_allowed'},405);
 if(!env.AUTH_DB)return reply({error:'unavailable'},503);
 const url=new URL(request.url),q=url.searchParams,db=env.AUTH_DB,uid=q.get('uid');
 if(!profilesFor(env).some(p=>p.uid===uid)||new Set(q.keys()).size!==[...q.keys()].length)return reply({error:'invalid_query'},400);
 if(url.pathname==='/admin/report'){
  const month=q.get('month');if([...q.keys()].some(k=>!['uid','month'].includes(k))||!/^(?:20\d{2})-(?:0[1-9]|1[0-2])$/.test(month||''))return reply({error:'invalid_query'},400);
  const [y,m]=month.split('-').map(Number),start=Date.UTC(y,m-1,1)-9*3600000,end=Date.UTC(y,m,1)-9*3600000,lo='material-attempt:'+uid+':',hi=lo+'\uffff';
  const sel="COUNT(*) attempts, SUM(CASE WHEN json_extract(v,'$.result.correct') THEN 1 ELSE 0 END) correct, SUM(CAST(json_extract(v,'$.elapsedMs') AS INTEGER)) elapsedMs";
  const where=" FROM auth_kv WHERE k>=? AND k<? AND CAST(json_extract(v,'$.at') AS INTEGER)>=? AND CAST(json_extract(v,'$.at') AS INTEGER)<? ";
  const [total,days,units]=await Promise.all([
   db.prepare('SELECT '+sel+where).bind(lo,hi,start,end).first(),
   db.prepare("SELECT CAST((CAST(json_extract(v,'$.at') AS INTEGER)+32400000)/86400000 AS INTEGER) d,"+sel+where+'GROUP BY d ORDER BY d').bind(lo,hi,start,end).all(),
   db.prepare("SELECT json_extract(v,'$.unitId') unitId,json_extract(v,'$.unitTitle') title,json_extract(v,'$.subject') subject,"+sel+where+'GROUP BY unitId ORDER BY subject,title').bind(lo,hi,start,end).all()
  ]);
  const counts=v=>({attempts:Number(v?.attempts)||0,correct:Number(v?.correct)||0,elapsedMs:Number(v?.elapsedMs)||0});
  return reply({uid,month,total:counts(total),days:(days.results||[]).map(d=>({date:new Date(d.d*86400000).toISOString().slice(0,10),...counts(d)})),units:(units.results||[]).map(u=>({id:u.unitId,title:u.title,subject:u.subject,...counts(u)}))});
 }
 if(url.pathname!=='/admin/submissions')return reply({error:'not_found'},404);
 if([...q.keys()].some(k=>!['uid','id','cursor'].includes(k)))return reply({error:'invalid_query'},400);
 const id=q.get('id'),cursor=q.get('cursor'),prefix='assignment-work:',hi=prefix+'\uffff';
 if(id){
  if(cursor||!/^[a-f0-9]{32}$/.test(id))return reply({error:'invalid_query'},400);
  const [a,w]=await Promise.all([db.prepare('SELECT v FROM auth_kv WHERE k=?').bind('assignment:'+id).first('v'),db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(prefix+id+':'+uid).first('v')]);
  if(!a||!w)return reply({error:'not_found'},404);
  const assignment=JSON.parse(a),work=JSON.parse(w);if(work.uid!==uid||!assignment.targets.includes(uid))return reply({error:'not_found'},404);
  return reply({assignment:{id:assignment.id,title:assignment.title,note:assignment.note,questions:assignment.questions,totalPoints:assignment.questions.reduce((n,q)=>n+q.points,0)},work:{uid,submission:work.submission,review:work.review}});
 }
 const match=cursor&&/^(\d{1,16}):([a-f0-9]{32})$/.exec(cursor);
 if(cursor&&!match)return reply({error:'invalid_query'},400);
 const before=match?Number(match[1]):Number.MAX_SAFE_INTEGER,beforeKey=match?prefix+match[2]+':'+uid:hi;
 const rows=(await db.prepare("SELECT w.k,w.v work,a.v assignment FROM auth_kv w JOIN auth_kv a ON a.k='assignment:'||json_extract(w.v,'$.id') WHERE w.k>=? AND w.k<? AND json_extract(w.v,'$.uid')=? AND json_extract(w.v,'$.submission.at') IS NOT NULL AND (CAST(json_extract(w.v,'$.submission.at') AS INTEGER)<? OR (CAST(json_extract(w.v,'$.submission.at') AS INTEGER)=? AND w.k<?)) ORDER BY CAST(json_extract(w.v,'$.submission.at') AS INTEGER) DESC,w.k DESC LIMIT 51").bind(prefix,hi,uid,before,before,beforeKey).all()).results||[];
 const items=rows.slice(0,50).map(row=>{const w=JSON.parse(row.work),a=JSON.parse(row.assignment);return {id:a.id,title:a.title,at:w.submission.at,returnedAt:w.review?.returnedAt||null,score:w.review?.score??null,totalPoints:a.questions.reduce((n,q)=>n+q.points,0),questionCount:a.questions.length};});
 const last=items.at(-1);return reply({uid,items,next:rows.length>50?last.at+':'+last.id:null});
}
