// Internal textbook chat quota. Independent of the global subscription preview switch.
// A reservation is retained when the provider outcome is unknown; only a known safe failure refunds.
import {textbookWriteGuard} from './textbook-access.mjs';
const DAY=86400000,JST=9*3600000,RETENTION=400*DAY;
const fail=()=>{throw Error('invalid_textbook_quota');};
const sha=x=>typeof x==='string'&&/^[a-f0-9]{64}$/.test(x);
function identity(access,uid,owner,now){
 const guard=textbookWriteGuard(access,{uid,owner,feature:'chat',now});
 if(!['early','v3'].includes(access.mode)||!Number.isSafeInteger(access.epoch)||!Number.isSafeInteger(access.dailyLimit)||access.dailyLimit<1||access.dailyLimit>5000)fail();
 const day=Math.floor((now+JST)/DAY),prefix='textbook-ai-quota:'+uid+':'+access.epoch+':';
 return {guard,day,key:prefix+day,limit:access.dailyLimit,resetAt:(day+1)*DAY-JST,prefix};
}
function ledger(raw){
 if(!raw)return {version:1,used:0};
 let row;try{row=JSON.parse(raw);}catch{fail();}
 if(row.version!==1||!Number.isSafeInteger(row.used)||row.used<0)fail();
 return row;
}
function receiptRow(raw){
 let row;try{row=JSON.parse(raw);}catch{fail();}
 if(!row||row.version!==1||!['charged','refunded'].includes(row.state)||!sha(row.fingerprint)||typeof row.token!=='string'||!/^[a-f0-9-]{36}$/.test(row.token)||!Number.isSafeInteger(row.day)||row.day<0||typeof row.key!=='string')fail();
 return row;
}
export async function textbookChatQuota(db,access,{uid,owner,now}){
 const id=identity(access,uid,owner,now),row=ledger(await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(id.key).first('v'));
 return {dailyLimit:id.limit,dailyUsed:row.used,dailyLeft:Math.max(0,id.limit-row.used),resetAt:id.resetAt};
}
export async function reserveTextbookChat(db,access,{uid,owner,now,requestId,fingerprint}){
 const id=identity(access,uid,owner,now);
 if(typeof requestId!=='string'||!/^[a-zA-Z0-9_-]{8,64}$/.test(requestId)||!sha(fingerprint))fail();
 const receiptKey=id.prefix+'request:'+requestId;
 const prior=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(receiptKey).first('v');
 if(prior){const row=receiptRow(prior);return row.fingerprint!==fingerprint?{error:'id_conflict'}:{error:row.state==='charged'?'request_outcome_unknown':'request_refunded'};}
 ledger(await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(id.key).first('v'));
 const token=crypto.randomUUID(),expires=id.resetAt+RETENTION;
 const value=JSON.stringify({version:1,state:'charged',token,fingerprint,key:id.key,day:id.day});
 const guard=' AND '+id.guard.sql+' AND NOT EXISTS(SELECT 1 FROM auth_kv WHERE k=?)';
 const args=[...id.guard.values,receiptKey];
 const results=await db.batch([
  db.prepare("INSERT INTO auth_kv(k,v,expires_at) SELECT ?,?,? WHERE 1<=?"+guard+" ON CONFLICT(k) DO UPDATE SET v=json_object('version',1,'used',CAST(json_extract(auth_kv.v,'$.used') AS INTEGER)+1,'lastCharge',?) WHERE json_valid(auth_kv.v) AND json_extract(auth_kv.v,'$.version')=1 AND json_type(auth_kv.v,'$.used')='integer' AND json_extract(auth_kv.v,'$.used')>=0 AND json_extract(auth_kv.v,'$.used')<?"+guard).bind(id.key,JSON.stringify({version:1,used:1,lastCharge:token}),expires,id.limit,...args,token,id.limit,...args),
  db.prepare("INSERT INTO auth_kv(k,v,expires_at) SELECT ?,?,? WHERE EXISTS(SELECT 1 FROM auth_kv WHERE k=? AND json_extract(v,'$.lastCharge')=?) ON CONFLICT(k) DO NOTHING").bind(receiptKey,value,expires,id.key,token)
 ]);
 if(results[0]?.meta?.changes===1&&results[1]?.meta?.changes===1)return {receipt:{receiptKey,token}};
 const raced=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(receiptKey).first('v');
 if(raced){const row=receiptRow(raced);return {error:row.fingerprint!==fingerprint?'id_conflict':row.state==='charged'?'request_outcome_unknown':'request_refunded'};}
 return {error:'quota_or_access_changed'};
}
export async function refundTextbookChat(db,uid,receipt){
 if(typeof uid!=='string'||!/^(?:u[124]|p_(?:free|mini|standard|pro|unlimit))$/.test(uid)||!receipt||typeof receipt.receiptKey!=='string'||!new RegExp('^textbook-ai-quota:'+uid+':\\d{13}:request:[a-zA-Z0-9_-]{8,64}$').test(receipt.receiptKey)||typeof receipt.token!=='string'||!/^[a-f0-9-]{36}$/.test(receipt.token))fail();
 const raw=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(receipt.receiptKey).first('v');if(!raw)return false;
 const row=receiptRow(raw),prefix=receipt.receiptKey.slice(0,receipt.receiptKey.indexOf(':request:'));
 if(row.token!==receipt.token||row.key!==prefix+':'+row.day)fail();
 if(row.state==='refunded')return false;
 const next=JSON.stringify({...row,state:'refunded'});
 const result=await db.batch([
  db.prepare("UPDATE auth_kv SET v=json_set(v,'$.used',CAST(json_extract(v,'$.used') AS INTEGER)-1,'$.lastRefund',?) WHERE k=? AND json_valid(v) AND json_extract(v,'$.version')=1 AND json_type(v,'$.used')='integer' AND json_extract(v,'$.used')>0 AND EXISTS(SELECT 1 FROM auth_kv WHERE k=? AND v=?)").bind(row.token,row.key,receipt.receiptKey,raw),
  db.prepare("UPDATE auth_kv SET v=? WHERE k=? AND v=? AND EXISTS(SELECT 1 FROM auth_kv WHERE k=? AND json_extract(v,'$.lastRefund')=?)").bind(next,receipt.receiptKey,raw,row.key,row.token)
 ]);
 return result[0]?.meta?.changes===1&&result[1]?.meta?.changes===1;
}
