// 個人の教科書マーカー・メモ。認証済みUIDだけを使い、教材や成績は変更しない。
import {textbookAccessOn,textbookAccess,textbookWriteGuard} from './textbook-access.mjs';
const BOOKS=new Set(['math1','kokugo1','english1','science1','geography','history']);
const COLORS=new Set(['none','yellow','blue','pink']);
const reply=(body,status=200)=>Response.json(body,{status,headers:{'Cache-Control':'no-store'}});
const plain=(s,n)=>typeof s==='string'&&s.length<=n&&!/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/.test(s);
async function bodyJson(request){
 if(!request.body||Number(request.headers.get('Content-Length'))>24000)throw Error('body');
 const reader=request.body.getReader(),parts=[];let length=0;
 try{for(;;){const r=await reader.read();if(r.done)break;length+=r.value.byteLength;if(length>24000){await reader.cancel();throw Error('body');}parts.push(r.value);}}
 finally{reader.releaseLock();}
 const data=new Uint8Array(length);let at=0;for(const p of parts){data.set(p,at);at+=p.byteLength;}
 return JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(data));
}
export async function textbookAnnotationsRoute(request,env,session,{owner,now=()=>Date.now()}={}){
 if(!textbookAccessOn(env))return reply({error:'not_found'},404);
 if(!session?.uid)return reply({error:'unauthorized'},401);
 if(!/^(?:u[124]|p_(?:free|mini|standard|pro|unlimit))$/.test(session.uid))return reply({error:'forbidden'},403);
 if(session.uid.startsWith('p_')&&env.PREVIEW_PLAN_ACCOUNTS!=='1')return reply({error:'forbidden'},403);
 if(!env.AUTH_DB)return reply({error:'unavailable'},503);
 const url=new URL(request.url),db=env.AUTH_DB,uid=session.uid;
 const configured=env.TEXTBOOK_RELEASE_STAGE!==undefined||env.TEXTBOOK_RELEASE_EPOCH!==undefined;
 if(configured&&(typeof owner!=='string'||!owner))return reply({error:'unauthorized'},401);
 // The authenticated parent always supplies owner. Legacy internal harness calls remain compatible.
 const enforceLease=typeof owner==='string'&&!!owner;
 const activeSql=enforceLease?'EXISTS(SELECT 1 FROM auth_kv WHERE k=? AND v=? AND expires_at>?)':'1';
 const activeArgs=()=>enforceLease?['active-session:'+uid,owner,now()]:[];
 const active=async()=>!enforceLease||!!await db.prepare('SELECT 1 AS x FROM auth_kv WHERE k=? AND v=? AND expires_at>?').bind(...activeArgs()).first('x');
 if(url.pathname!=='/textbook-annotations')return reply({error:'not_found'},404);
 if(request.method==='GET'){
  if([...url.searchParams.keys()].some(k=>k!=='book')||url.searchParams.getAll('book').length!==1||!BOOKS.has(url.searchParams.get('book')))return reply({error:'invalid_query'},400);
  const book=url.searchParams.get('book'),prefix='textbook-annotation:'+uid+':'+book+':';
  try{
   if(!await active())return reply({error:'active_session'},409);
   const status=await textbookAccess(env,uid,now());
   const rows=(await db.prepare('SELECT v FROM auth_kv WHERE k>=? AND k<? AND '+activeSql+' ORDER BY k LIMIT 2048').bind(prefix,prefix+'￿',...activeArgs()).all()).results||[];
   if(!await active())return reply({error:'active_session'},409);
   return reply({book,items:rows.map(r=>JSON.parse(r.v)),writable:!!status.features.annotations});
  }catch(_){return reply({error:'load_failed'},503);}
 }
 if(request.method!=='POST')return reply({error:'method_not_allowed'},405);
 if(url.search)return reply({error:'invalid_query'},400);
 if(!env.APP_ORIGIN||request.headers.get('Origin')!==env.APP_ORIGIN)return reply({error:'origin'},403);
 if(!/^application\/json\b/.test(request.headers.get('Content-Type')||''))return reply({error:'content_type'},415);
 let b;try{b=await bodyJson(request);}catch(_){return reply({error:'invalid_body'},400);}
 if(!b||Array.isArray(b)||Object.keys(b).sort().join(',')!=='anchor,book,color,note,quote,revision'||!BOOKS.has(b.book)||typeof b.anchor!=='string'||!/^[a-f0-9]{64}$/.test(b.anchor)||!COLORS.has(b.color)||!plain(b.note,2000)||!plain(b.quote,2000)||!b.quote.trim()||!Number.isSafeInteger(b.revision)||b.revision<0||b.revision>=1000000000)return reply({error:'invalid_body'},400);
 const prefix='textbook-annotation:'+uid+':'+b.book+':',key=prefix+b.anchor;
 try{
  // 下位プランでも本人の書き込みは読むことができる。書き足しはPro以上。
  if(!await active())return reply({error:'active_session'},409);
  const status=await textbookAccess(env,uid,now());
  if(!status.features.annotations)return reply({error:'plan_required'},403);
  const guard=enforceLease?textbookWriteGuard(status,{uid,owner,feature:'annotations',now:now()}):{sql:'1',values:[]};
  const item={book:b.book,anchor:b.anchor,quote:b.quote,color:b.color,note:b.note,revision:b.revision+1,updatedAt:now()};
  const raw=b.revision===0
   ?await db.prepare('INSERT INTO auth_kv(k,v,expires_at) SELECT ?,?,0 WHERE '+guard.sql+' AND (SELECT COUNT(*) FROM auth_kv WHERE k>=? AND k<?)<2048 ON CONFLICT(k) DO NOTHING RETURNING v').bind(key,JSON.stringify(item),...guard.values,prefix,prefix+'￿').first('v')
   :await db.prepare("UPDATE auth_kv SET v=? WHERE k=? AND CAST(json_extract(v,'$.revision') AS INTEGER)=? AND "+guard.sql+' RETURNING v').bind(JSON.stringify(item),key,b.revision,...guard.values).first('v');
  if(!await active())return reply({error:'active_session'},409);
  if(raw)return reply({item:JSON.parse(raw),cached:false});
  const latest=await textbookAccess(env,uid,now());
  if(latest.accessVersion!==status.accessVersion||!latest.features.annotations)return reply({error:'plan_changed'},409);
  const existing=await db.prepare('SELECT v FROM auth_kv WHERE k=? AND '+activeSql).bind(key,...activeArgs()).first('v');
  if(existing){
   const row=JSON.parse(existing);
   // 保存成功後に返答が失われたとき、同じ操作の再送は二重更新にしない。
   if(row.revision===b.revision+1&&row.quote===b.quote&&row.color===b.color&&row.note===b.note)return reply({item:row,cached:true});
   return reply({error:'revision_conflict'},409);
  }
  return reply({error:b.revision===0?'annotation_limit':'revision_conflict'},409);
 }catch(error){if(['release_changed','plan_changed'].includes(error?.message))return reply({error:'plan_changed'},409);return reply({error:'save_failed'},503);}
}
